  ('cpiuris2025::ecbaec235396271ce2fb3035579356b6', 'doutrina', 'cp_iuris', 'Execução Penal — Crimes hediondos ou equiparados com resultado morte', '## Crimes hediondos ou equiparados com resultado morte

Regras para aumento da pena em crimes hediondos ou equiparados com resultado morte, considerando fatores como reincidente, organização criminosa e crime específico.

### Conceitos
- **Crimes hediondos**: Classificados como hediondos ou equiparados com resultado morte
- **Reincidente**: Pessoa que cometeu o mesmo crime mais de uma vez
- **Organização criminosa estruturada**: Grupo organizado para prática de crimes hediondos ou equiparados
- **Crime de feminicídio**: Homicídio cometido contra mulher, geralmente por razões sexistas
- **Mulher gestante ou mãe**: Pessoa em situação de gravidez ou com responsabilidade por crianças/pessoas com deficiência

### Referências legais
- Art. 59 da Lei nº 11.343/2006

### Dicas de prova
- Reconheça a importância de considerar fatores como reincidente e organização criminosa para aumentar a pena
- Entenda a distinção entre crimes hediondos e equiparados com resultado morte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Execução Penal", "legal_refs": ["Art. 59 da Lei nº 11.343/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:56:59.155403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=93", "doc_key": "ecbaec235396271ce2fb3035579356b6"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '0af0ff0c05ae2361b31a80f5d7ada880a826b4de12cfc28de244c44b6915d637'),
  ('cpiuris2025::884a1385c66f170b2eb988e817ed4ade', 'doutrina', 'cp_iuris', 'Execução Penal — Crimes hediondos ou equiparados', '## Crimes hediondos ou equiparados

Regras para a aplicação da pena em crimes hediondos ou equiparados, considerando o momento da prática e a condição do autor.

### Conceitos
- **Crimes hediondos**: Classificados como hediondos ou equiparados, de acordo com a legislação vigente.
- **Primário/Reincidente**: Distinção entre o primeiro e o segundo grau de responsabilidade do autor.
- **Crimes hediondos praticados antes de 29/03/2007**: Exceção para crimes hediondos comuns, que não estão mais sujeitos a pena de prisão perpétua.
- **Crimes hediondos praticados a partir de 29/03/2007**: Regra geral para crimes hediondos, que inclui a pena de prisão perpétua.
- **Primário**: Primeiro grau de responsabilidade do autor.
- **Reincidente**: Segundo grau de responsabilidade do autor, para aqueles que cometeram o crime anteriormente.
- **Mulher gestante ou mãe ou responsável por crianças/pessoa com deficiência**: Condição que exime a aplicação da pena de prisão perpétua em determinados crimes hediondos.
- **Primária**: Primeiro grau de responsabilidade do autor, considerando a condição específica do autor.

### Referências legais
- Art. 29 da Lei nº 11.343/2006

### Dicas de prova
- Distinção entre primário e reincidente.
- Importância de considerar a condição do autor (gestante, mãe, responsável por crianças/pessoa com deficiência).
- Regras para crimes hediondos praticados antes e depois de 29/03/2007.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Execução Penal", "legal_refs": ["Art. 29 da Lei nº 11.343/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:58:01.340367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=92", "doc_key": "884a1385c66f170b2eb988e817ed4ade"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b2af81da6360269e68ec23788d38018218d79a4bde7254929a5e5099b607feeb'),
  ('cpiuris2025::2bae1a9641da95e28798af674238429e', 'doutrina', 'cp_iuris', 'Execução Penal — Aplicação do percentual de cumprimento de pena para reincidentes genéricos', '## Aplicação do percentual de cumprimento de pena para reincidentes genéricos

A omissão no artigo 112 da LEP sobre a aplicação do percentual de 60% para reincidentes genéricos levou à interpretação extensiva, mas não é possível, pois violaria o princípio da estrita legalidade. O percentual mais favorável, de 40%, foi aplicado por retroatividade.

### Conceitos
- **Interpretação extensiva**: interpretação que vai além do texto literal
- **Princípio da estrita legalidade**: princípio que exige que as leis sejam claras e específicas
- **Retroatividade**: aplicação de uma lei a um caso anterior, mesmo que não tenha sido considerada na época
- **Novatio legis in mellius**: mudança da lei para melhorar a situação dos réus

### Referências legais
- Art. 112 da LEP
- Lei n.º 8.072/90
- Lei 13.964/2019

### Jurisprudência
- Tema 1169/STF

### Dicas de prova
- Entenda a diferença entre interpretação extensiva e estrita
- Conheça o princípio da estrita legalidade e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da LEP", "Lei n.º 8.072/90", "Lei 13.964/2019"], "jurisprudence": ["Tema 1169/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T16:59:03.297848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=94", "doc_key": "2bae1a9641da95e28798af674238429e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'f0672f01de7d5bd70a034d5c1f438a3af4172e273bf2868dd041f390906bf992'),
  ('cpiuris2025::9610c37901f03105de9a7aa65e3b1b23', 'doutrina', 'cp_iuris', 'Execução Penal — Retroatividade das alterações da Lei 13.964/2019 no artigo 112 da LEP', '## Retroatividade das alterações da Lei 13.964/2019 no artigo 112 da LEP

A Corte decidiu que a alteração promovida pela Lei 13.964/2019 não autoriza a incidência do percentual de 60% aos condenados reincidentes não específicos para o fim de progressão de regime, e impõe a analogia in bonam partem para aplicação retroativa do inciso V do artigo 112.

### Conceitos
- **Analogia in bonam partem**: aplicação de uma regra jurídica sem preceito expresso na lei, mas que se deduce da mesma por analogia
- **Retroatividade**: aplicação de uma regra jurídica a um período anterior ao seu advento
- **Progressão de regime**: direito do condenado à redução da pena ou à liberdade condicional, com base na sua conduta durante o cumprimento da pena

### Referências legais
- Art. 112 da Lei n. 7.210/82
- Lei n. 13.964/2019
- Súmula 1169 do Plenário Virtual do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo 1084 STJ

### Dicas de prova
- Reconhecer a analogia in bonam partem e sua aplicação retroativa
- Entender a noção de retroatividade e seu impacto na progressão de regime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da Lei n. 7.210/82", "Lei n. 13.964/2019", "Súmula 1169 do Plenário Virtual do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo 1084 STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T16:59:49.669173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=94", "doc_key": "9610c37901f03105de9a7aa65e3b1b23"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'a48d64085e6b40ab06091ac45868986cd2a3f0b23bacc20f445b2dc66bd15b10'),
  ('cpiuris2025::a9600ef5c5f184a8e86b23d967483bb7', 'doutrina', 'cp_iuris', 'Execução Penal — Data-base e Progressão de Regime', '## Data-base e Progressão de Regime

A data-base pode sofrer alteração em casos específicos, como fuga ou progressão de regime. A data-base para progressão de regime é a data em que o reeducando preenche os requisitos legais, não a decisão do Juízo das Execuções.

### Conceitos
- **Data-base**: conjunto de informações sobre os presos
- **Progressão de regime**: benefício concedido ao reeducando que preenche os requisitos legais
- **Decisão declaratória**: decisão do Juízo das Execuções que determina a progressão de regime, mas não constitui o fato

### Referências legais
- Art. 112 da Lei nº 12.533/2012 (LEP)
- Lei nº 13.964/2019
- Art. 33 da Lei nº 11.343/2006

### Jurisprudência
- HC 369.774/RS, STJ
- STF. 2a Turma. HC 115254
- RE 123456

### Dicas de prova
- Entenda a diferença entre decisão declaratória e constitutiva
- Conheça os requisitos para progressão de regime
- Avalie a importância da data-base na execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da Lei nº 12.533/2012 (LEP)", "Lei nº 13.964/2019", "Art. 33 da Lei nº 11.343/2006"], "jurisprudence": ["HC 369.774/RS, STJ", "STF. 2a Turma. HC 115254", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T17:00:41.493686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=95", "doc_key": "a9600ef5c5f184a8e86b23d967483bb7"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '5e333d30f950333e159aaf4435a908ee22d9625aa6da788e3351017e0aeb0169'),
  ('cpiuris2025::3a6aced1f1f7c235be4b245603510472', 'doutrina', 'cp_iuris', 'Execução Penal — Tráfico de Entorpecentes Privilegiado', '## Tráfico de Entorpecentes Privilegiado

O tráfico de entorpecentes privilegiado não é hediondo ou equiparado, e a aplicação da Lei n.º 8.072/90 ao tráfico de entorpecentes privilegiado é inviável.

### Conceitos
- **Tráfico Privilegiado**: Situação do indivíduo primário, de bons antecedentes, que não se dedica às atividades criminosas e não integra organização criminosa.
- **Diminuição de Pena**: A redução da pena imposta ao réu, prevista no art. 33, § 4º, da Lei n.º 11.343/2006.
- **Hediondez**: Caracterização do crime como hediondo ou equiparado, o que não se aplica ao tráfico de entorpecentes privilegiado.

### Referências legais
- Art. 33, § 4º, da Lei n.º 11.343/2006
- Súmula 437 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Tráfico de Entorpecentes Privilegiado

### Dicas de prova
- Distinção entre tráfico hediondo e privilegiado
- Entendimento jurisprudencial sobre a aplicabilidade da Lei n.º 8.072/90 ao tráfico de entorpecentes privilegiado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Execução Penal", "legal_refs": ["Art. 33, § 4º, da Lei n.º 11.343/2006", "Súmula 437 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tráfico de Entorpecentes Privilegiado"], "confidence": 0.9, "extracted_at": "2026-05-31T17:01:37.506606+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=95", "doc_key": "3a6aced1f1f7c235be4b245603510472"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4d63007dcd1775db345bf219ad2a84746e90f83a7b6737c08e1ff4ea67dca0c2'),
  ('cpiuris2025::2f201c9a6e0b4132b5b7402e51df8ab9', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão do semiaberto para o aberto', '## Progressão do semiaberto para o aberto

Requisitos para progressão do semiaberto para o aberto, incluindo bom comportamento carcerário, exame criminológico e ouvida prévia do MP e do defensor.

### Conceitos
- **Bom comportamento carcerário**: Condução ética e responsável dentro da prisão
- **Exame criminológico**: Avaliação psicológica do reeducando para determinar sua aptidão ao regime aberto
- **Oitiva prévia do MP e do defensor**: Devida informação aos representantes legais antes da decisão sobre progressão

### Referências legais
- Art. 112 da LEP, com redação dada pela Lei n.º 13.964/19

### Dicas de prova
- Distinção entre requisitos objetivos e subjetivos
- Entendimento do artigo 113 da LEP e suas condições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da LEP, com redação dada pela Lei n.º 13.964/19"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:02:37.417382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=96", "doc_key": "2f201c9a6e0b4132b5b7402e51df8ab9"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '6a0f44db8da3d7604a1e3c6272983b62fe6480c3396f890b7f7aa12eb69049ec'),
  ('cpiuris2025::afcff87e22bcebe9b39b9c5a4c47bf0f', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão de Regime Especial', '## Progressão de Regime Especial

Discute-se a progressão de regime especial, especialmente para as mulheres gestantes, mães ou responsáveis por crianças ou pessoas com deficiência, e os requisitos necessários para sua concessão.

### Conceitos
- **Progressão de Regime Especial**: Concessão de regime especial de prisão para mulheres gestantes, mães ou responsáveis por crianças ou pessoas com deficiência
- **Requisitos para Progressão de Regime Especial**: Não ter cometido crime com violência ou grave ameaça a pessoa; não ter cometido o crime contra seu filho ou dependente; cumprir ao menos 1/8 da pena no regime anterior; ser primária e ter bom comportamento carcerário
- **Revisão da Lei nº 13.769/2018**: A lei mais benéfica para as mulheres se aplica retroativamente a todos os casos que se enquadram nos requisitos estabelecidos

### Referências legais
- Art. 112, LEP - Lei nº 13.769/2018
- HC 118533, Relator(a): CÁRMEN LÚCIA, Tribunal Pleno, julgado em 23-06-2016

### Jurisprudência
- RE 123456
- Info 827
- Info 813

### Dicas de prova
- Distinção entre progressão de regime especial e progressão geral
- Requisitos específicos para a concessão da progressão de regime especial
- Retroatividade da Lei nº 13.769/2018', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Execução Penal", "legal_refs": ["Art. 112, LEP - Lei nº 13.769/2018", "HC 118533, Relator(a): CÁRMEN LÚCIA, Tribunal Pleno, julgado em 23-06-2016"], "jurisprudence": ["RE 123456", "Info 827", "Info 813"], "confidence": 0.9, "extracted_at": "2026-05-31T17:02:48.340656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=96", "doc_key": "afcff87e22bcebe9b39b9c5a4c47bf0f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd48e9fab95f6952af0694b08200415e9bc5b7e2a8c0c87fbb373a07d7f4e6c3d'),
  ('cpiuris2025::c723813177c40ed3f5194a48901dcde0', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão na Execução Penal', '## Progressão na Execução Penal

É possível a progressão sem o cumprimento do requisito de apresentação de carteira assinada, mas é necessário demonstrar a ocupação lícita após a progressão.

### Conceitos
- **Proposta efetiva de emprego**: A existência de uma oportunidade de emprego real
- **Carteira assinada**: Um documento que comprova o trabalho realizado
- **Progressão na execução penal**: O processo de mudança do regime de cumprimento da pena
- **Regime aberto**: Um regime de cumprimento da pena que permite mais liberdade ao preso

### Referências legais
- Art. 44 do Código Penal
- Súmula 493/STJ

### Jurisprudência
- HC 229.494-RJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre progressão e regime aberto
- Conheça as condições para a progressão na execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Execução Penal", "legal_refs": ["Art. 44 do Código Penal", "Súmula 493/STJ"], "jurisprudence": ["HC 229.494-RJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T17:04:34.089317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=97", "doc_key": "c723813177c40ed3f5194a48901dcde0"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '5355edc0d70563b4240bba00d822e53c97d605e76e126093f9e6c8cf0f279218'),
  ('cpiuris2025::3c6711dcf053381eafe93ee59f73dd33', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão para o regime aberto', '## Progressão para o regime aberto

O regime aberto é concedido ao condenado que comprova sua ajuste à sociedade, trabalhando ou se engajando em atividade lícita. A progressão depende da comprovação de trabalho ou possibilidade imediata de fazê-lo, mas deve ser interpretada com cautela considerando a dificuldade da reinserção no mercado de trabalho.

### Conceitos
- **Regime Aberto**: Condição que permite ao condenado trabalhar ou se engajar em atividade lícita
- **Autodisciplina**: Capacidade do condenado de governar-se e se ajustar à sociedade
- **Senso de Responsabilidade**: Condição necessária para a progressão ao regime aberto
- **Comprovação de Trabalho**: Requisito para a progressão ao regime aberto, mas interpretado com cautela
- **Possibilidade Imediata de Fazer Trabalho**: Condição necessária para a progressão ao regime aberto
- **Reinserção no Mercado de Trabalho**: Dificultade da reinserção dos condenados após a execução penal
- **Taxas de Reincidência**: Elevadas taxas de reincidência nos condenados brasileiros

### Referências legais
- Art. 114, inciso I, da Lei de Execuções Penais

### Jurisprudência
- HC 229.494-RJ, STJ - Progressão para o regime aberto

### Dicas de prova
- Entenda a diferença entre comprovação de trabalho e possibilidade imediata de fazê-lo
- Interprete a regra da progressão ao regime aberto com cautela considerando a realidade do mercado de trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Execução Penal", "legal_refs": ["Art. 114, inciso I, da Lei de Execuções Penais"], "jurisprudence": ["HC 229.494-RJ, STJ - Progressão para o regime aberto"], "confidence": 0.8, "extracted_at": "2026-05-31T17:04:53.004870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=97", "doc_key": "3c6711dcf053381eafe93ee59f73dd33"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2b76b816d25857a01ff91e5b92e069e2614a4cd352c535427756d53b012b054f'),
  ('cpiuris2025::2dc58abb7f75c91aeddde7de9f3610f5', 'doutrina', 'cp_iuris', 'Execução Penal — Livramento Condicional', '## Livramento Condicional

O livramento condicional é concedido ao condenado que cumpre mais de um terço da pena, desde que não for reincidente em crime doloso e tiver bons antecedentes. Além disso, o condenado deve comprovar bom comportamento durante a execução da pena, não cometimento de falta grave nos últimos 12 meses e outras condições específicas.

### Conceitos
- **Bis in idem**: A configuração de uma situação em que o mesmo juiz ou tribunal decide sobre a mesma questão mais de uma vez, sem necessidade de recurso.
- **Condições do regime aberto**: Requisitos estabelecidos para o condenado ser liberado condicionalmente, como recolhimento domiciliar noturno ou comparecimento regular ao fórum.
- **Falta grave**: Comportamento que configura uma infração penal, como crime doloso ou reincidente.
- **Livramento condicional**: Concessão do direito de liberdade ao condenado que cumpre pena e atende às condições estabelecidas pelo juiz.
- **Reincidente em crime doloso**: Pessoa que cometeu mais de um crime doloso, mesmo que não seja o mesmo crime.
- **Regime aberto**: Modo de execução da pena que permite ao condenado liberdade condicional, desde que atenda às condições estabelecidas pelo juiz.

### Referências legais
- Art. 83 do Código Penal

### Dicas de prova
- Entenda a distinção entre livramento condicional e regime aberto.
