  ('cpiuris2025::666e1e2d7638d97df50ee0663cfb9078', 'doutrina', 'cp_iuris', 'Execução Penal — Livramento Condicional em Crimes Hediondos', '## Livramento Condicional em Crimes Hediondos

O condenado por crime hediondo faz jus ao livramento condicional se atende a certos requisitos, como cumprimento de mais de 2/3 da pena e não ser reincidente específico. No entanto, o art. 112 da LEP veda a concessão de livramento condicional em casos de resultado morte.

### Conceitos
- **Crime Hediondo**: Pena mais elevada para crimes hediondos
- **Livramento Condicional**: Concessão da liberdade condicional ao condenado
- **Reincidente Específico**: Pessoa que cometeu crime hediondo ou equiparado

### Referências legais
- Art. 112 da Lei de Execução Penal (LEP)
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre crimes hediondos e não hediondos
- Requisitos para o livramento condicional em crimes hediondos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da Lei de Execução Penal (LEP)", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T17:06:30.839221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=98", "doc_key": "666e1e2d7638d97df50ee0663cfb9078"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '53a4ca2d7180fc09d45f8af88b7078cef7c10918700e16c86064fed25c26f73e'),
  ('cpiuris2025::161dc8fb43e88f6c95cf6334b689c928', 'doutrina', 'cp_iuris', 'Execução Penal — Requisitos Subjetivos do Livramento Condicional', '## Requisitos Subjetivos do Livramento Condicional

O livramento condicional é um substitutivo penal que não é um regime de cumprimento de pena. É concedido ao reeducando que preenche os requisitos subjetivos, incluindo bom comportamento durante a execução da pena e não cometimento de falta grave nos últimos 12 meses.

### Conceitos
- **Livramento Condicional**: Substitutivo penal que concede-se ao reeducando que preenche os requisitos subjetivos
- **Requisito Subjetivo**: Condições que o reeducando deve atender para ser elegível ao livramento condicional
- **Bom Comportamento**: Ação do reeducando durante a execução da pena que demonstra sua capacidade de se reeducar
- **Não Cometimento de Falta Grave**: Ausência de infrações graves cometidas pelo reeducando nos últimos 12 meses

### Referências legais
- Art. 83, CP-2019

### Jurisprudência
- Súmula 432 STF

### Dicas de prova
- Análise do histórico do reeducando nos últimos 12 meses
- Compatibilização da alínea “a” com a alínea “b” do art. 83, CP-2019', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Execução Penal", "legal_refs": ["Art. 83, CP-2019"], "jurisprudence": ["Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T17:07:16.989017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=99", "doc_key": "161dc8fb43e88f6c95cf6334b689c928"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '960fa052145777117cb702de7e641e4dbb56b406915a202a3f5d1aeaca80015c'),
  ('cpiuris2025::33f1ad69d3f822e7361f7d5d16e9682a', 'doutrina', 'cp_iuris', 'Execução Penal — Requisitos para a libertação condicional de preso', '## Requisitos para a libertação condicional de preso

São estabelecidos requisitos objetivos e subjetivos para a libertação condicional de preso, que incluem comportamento carcerário satisfatório, bom desempenho no trabalho e aptidão para prover a própria subsistência.

### Conceitos
- **Reincidente**: Pessoa que cometeu mais de um crime doloso
- **Crime hediondo**: Crime que envolve violação grave dos direitos humanos, como tortura, tráfico ilícito de entorpecentes e terrorismo
- **Falta grave**: Omissão ou negligência grave que pode causar dano a outrem

### Referências legais
- Art. 77 da Lei nº 7.210/82

### Dicas de prova
- Entenda o conceito de reincidente e crime hediondo
- Não confunda falta grave com outros tipos de infrações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Execução Penal", "legal_refs": ["Art. 77 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:07:43.491591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=99", "doc_key": "33f1ad69d3f822e7361f7d5d16e9682a"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '30c385d39a829f1415809b98faec79aa93a03915550c48ff7fbf0efbe2286a32'),
  ('cpiuris2025::5d8fba7942f2dedced8a5086bd8f82df', 'doutrina', 'cp_iuris', 'Execução Penal — Livramento Condicional', '## Livramento Condicional

O livramento condicional é um direito que pode ser concedido ao sentenciado, desde que atenda às condições estabelecidas pelo juiz. O pedido deve ser feito por qualquer das partes ou pelos órgãos de execução penal, e o juiz sempre ouvirá o MP e o defensor antes de decidir.

### Conceitos
- **Livramento Condicional**: Concessão do direito ao sentenciado para sair da prisão antes do tempo previsto
- **Audiência Admonitória**: Reunião entre o juiz, MP e defensor para discutir as condições do livramento condicional
- **Obrigações ao Liberado Condicional**: Regras que devem ser seguidas pelo sentenciado após a saída da prisão

### Referências legais
- Art. 132 da LEP
- Súmula 333 do STF

### Jurisprudência
- RE 456789
- Incidente repetitivo sobre o livramento condicional

### Dicas de prova
- Entenda a diferença entre livramento condicional e indulto
- Conheça as obrigações ao liberado condicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Execução Penal", "legal_refs": ["Art. 132 da LEP", "Súmula 333 do STF"], "jurisprudence": ["RE 456789", "Incidente repetitivo sobre o livramento condicional"], "confidence": 0.8, "extracted_at": "2026-05-31T17:07:58.272811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=100", "doc_key": "5d8fba7942f2dedced8a5086bd8f82df"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b19bd8926d8693df2100a6e3f2bef9aed97ab610b7fcedc17fd92a69742b3015'),
  ('cpiuris2025::d76e34b3a6cc5c9c1f7b7c7bf9c18449', 'doutrina', 'cp_iuris', 'Execução Penal — Prazo para obtenção de livramento condicional', '## Prazo para obtenção de livramento condicional

O prazo para obtenção de livramento condicional não é interrompido pela prática de falta grave, exceto no caso do livramento condicional mesmo.

### Conceitos
- **Livramento Condicional**: direito concedido ao réu que cometeu crime menor
- **Falta Grave**: comporte regra de punição severa, como a morte ou pena de prisão perpétua
- **Prazo para obtenção de livramento condicional**: período durante o qual o réu pode solicitar e receber o livramento

### Referências legais
- Art. 77, § 3º da Lei nº 9.034/95
- ...

### Jurisprudência
- Súmula 441/STJ
- RE 123456

### Dicas de prova
- Distinção entre falta grave e livramento condicional
- Entendimento do prazo para obtenção de livramento condicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Execução Penal", "legal_refs": ["Art. 77, § 3º da Lei nº 9.034/95", "..."], "jurisprudence": ["Súmula 441/STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T17:09:53.068598+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=100", "doc_key": "d76e34b3a6cc5c9c1f7b7c7bf9c18449"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'cd5ed724fb566a68263eb2670b33c1ec8f1f8d59e7a03634aff94e4d5ee72e6e'),
  ('cpiuris2025::409d0736ea31cebdbb81333a0e38adc1', 'doutrina', 'cp_iuris', 'Execução Penal — Revogação do Livramento', '## Revogação do Livramento

A revogação do livramento ocorre quando o liberado é condenado a pena privativa de liberdade, em sentença irrecorrível, por crime cometido durante a vigência do benefício ou por crime anterior, observado o disposto no art. 84 do Código Penal.

### Conceitos
- **Livramento**: Benefício que exime o condão de pena para aqueles que não cometeram crime durante a vigência do benefício
- **Revogação**: Ação que elimina o direito ao livramento

### Referências legais
- Art. 86 do CP
- Art. 87 do CP
- Art. 112, inciso VI, alínea "a" da LEP

### Jurisprudência
- Súmula 617/STJ

### Dicas de prova
- Diferencie entre suspensão e revogação do livramento condicional
- Entenda a hipótese em que o juiz deve extinguir a punibilidade pelo integral cumprimento da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Execução Penal", "legal_refs": ["Art. 86 do CP", "Art. 87 do CP", "Art. 112, inciso VI, alínea \"a\" da LEP"], "jurisprudence": ["Súmula 617/STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T17:10:07.652553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=101", "doc_key": "409d0736ea31cebdbb81333a0e38adc1"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2c728284a2c5e44e0abbc0c94b0c050b5187228a9dd54721a4c4cb6f83298f48'),
  ('cpiuris2025::cc783eb3b84148261df3fd7d56eee932', 'doutrina', 'cp_iuris', 'Execução Penal — Livramento Condicional', '## Livramento Condicional

O juiz pode julgar extinta a pena privativa de liberdade se expirar o prazo do livramento sem revogação, considerando o bom comportamento carcerário e o histórico prisional do apenado.

### Conceitos
- **Livramento Condicional**: Benefício concedido ao reeducando que cometeu um crime menor, permitindo a liberdade condicional após cumprimento de pena determinada
- **Bom comportamento carcerário**: Condução responsável e respeitosa dentro da prisão, demonstrando melhoria do apenado
- **Histórico prisional conturbado**: Comportamento antigo que não se alterou durante a execução penal, indicativo de falta de melhoria

### Referências legais
- Art. 146, LEP

### Dicas de prova
- Análise cuidadosa das assertivas e consideração do requisito subjetivo para a concessão do livramento condicional
- Distinção entre bom comportamento carcerário e histórico prisional conturbado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Execução Penal", "legal_refs": ["Art. 146, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:10:29.317512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=101", "doc_key": "cc783eb3b84148261df3fd7d56eee932"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '56bb443441302a6d10a1c2359f785d031a4cd5567269da74cfec91a7a97cf4e0'),
  ('cpiuris2025::d69e200d4b42361c03a9ec8c6286db00', 'doutrina', 'cp_iuris', 'Execução Penal — Prescrição da medida de segurança em sentença absolutória imprópria', '## Prescrição da medida de segurança em sentença absolutória imprópria

A prescrição da medida de segurança é regulada pela pena máxima abstratamente prevista para o delito.

### Conceitos
- **prescrição**: Fim do prazo legal para processar um crime
- **medida de segurança**: Misura adotada pelo juiz para proteger a sociedade
- **sentença absolutória imprópria**: Sentença que absolviu o réu, mas não atendeu às necessidades da justiça

### Referências legais
- Art. 83, III, a, do CP

### Jurisprudência
- REsp n. 1.970.217/MG
- ...

### Dicas de prova
- Análise cuidadosa das condições de livramento condicional
- Entendimento da prescrição e medida de segurança em sentença absolutória imprópria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Execução Penal", "legal_refs": ["Art. 83, III, a, do CP"], "jurisprudence": ["REsp n. 1.970.217/MG", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T17:11:56.880044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=103", "doc_key": "d69e200d4b42361c03a9ec8c6286db00"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'e6e9d9fec61f03ecb6cf88b4186827ae1b4ac1b4b011f3791d7a4e143cd90f90'),
  ('cpiuris2025::8d80addaa5dc12d65d83d8d4d18700a3', 'doutrina', 'cp_iuris', 'Execução Penal — Benefícios e Condições do Livramento Condicional', '## Benefícios e Condições do Livramento Condicional

Resumo das assertivas sobre o livramento condicional, incluindo condições para concessão e requisitos subjetivos.

### Conceitos
- **Reincidente**: Pessoa que já foi condenada por crime anteriormente
- **Falta grave**: Omissão ou comissão de ato que não é considerado grave, mas que pode ser punido com pena alternativa
- **Pena unificada**: Pena aplicada ao réu em conjunto com todas as condenações passadas
- **Saída temporária**: Período de liberdade concedido ao preso para realizar atividades fora do estabelecimento prisional

### Referências legais
- Art. 75, CP
- Súmula 439 STF

### Jurisprudência
- RE 123456
- Tema repetitivo Livramento Condicional

### Dicas de prova
- Entenda a condição de reincidente e sua aplicação no livramento condicional
- Conheça as condições para concessão do livramento condicional, incluindo falta grave e pena unificada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.102", "page_number": 102, "discipline": "Execução Penal", "legal_refs": ["Art. 75, CP", "Súmula 439 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Livramento Condicional"], "confidence": 0.8, "extracted_at": "2026-05-31T17:12:28.627592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=102", "doc_key": "8d80addaa5dc12d65d83d8d4d18700a3"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '321bd3167d33133319939510cdeef94a60afeecec37722d451c87c92befb07ec'),
  ('cpiuris2025::f237f9498244bc86c9a2d3180795afef', 'doutrina', 'cp_iuris', 'Execução Penal — Revolimento fático-probatório inviável', '## Revolimento fático-probatório inviável

O revolimento fático-probatório não é inviável quando o habeas corpus não é conhecido.

### Conceitos
- **Revolimento fático-probatório**: Procedimento que visa a reabertura de um processo após a decisão final do juiz.
- **Inviabilidade**: Não pode ser realizada ou não é permitida.
- **Habeas corpus**: Ação judicial que visa à liberdade de alguém preso ou detido.
- **Conhecimento do habeas corpus**: Decisão do juiz que aceita a ação e permite a liberdade do réu.
- **Prova**: Testemunho ou evidências apresentadas em um processo para comprovar uma acusação.
- **Livremente**: Sem restrições ou limitações.
- **Tempo**: Unidade de medida do tempo.
- **Código Penal**: Lei que regula as infrações penais e os processos criminais.

### Referências legais
- Art. 75 do Código Penal

### Jurisprudência
- HC n. 734.064/SP

### Dicas de prova
- Entenda a diferença entre revolimento fático-probatório e conhecimento do habeas corpus.
- Conheça o prazo para o livremente encerramento do período de prova do livramento condicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Execução Penal", "legal_refs": ["Art. 75 do Código Penal"], "jurisprudence": ["HC n. 734.064/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T17:13:12.792340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=103", "doc_key": "f237f9498244bc86c9a2d3180795afef"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '470a4190e857266e209a5eff85f2ed9d8e09aa78f23f31f9e1c91224d18daa4a'),
  ('cpiuris2025::af782c17d584aa4140277b1159f42f8e', 'doutrina', 'cp_iuris', 'Execução Penal — Livramento Condicional', '## Livramento Condicional

O livramento condicional não pode ser concedido a indivíduos que cometem crimes durante o período de liberdade, mesmo que tenham sido soltos por falta grave nos últimos 12 meses.

### Conceitos
- **Livramento Condicional**: Concessão de liberdade condicional a indivíduos condenados
- **Falta Grave**: Omissão grave ou negligência que pode ser considerada como infração disciplinar
- **Requisito Subjetivo**: A ausência de falta grave nos últimos 12 meses não é suficiente para satisfazer o requisito subjetivo exigido para a concessão do livramento condicional

### Referências legais
- Art. 83, inciso III, da Lei nº 13.964/2019
- Súmula 444 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- REsp 1922012/RS
- HC 307.180/RS
- HC 271.907/SP

### Dicas de prova
- Entenda a noção de falta grave e seu impacto na concessão do livramento condicional
- Conheça o requisito subjetivo para a concessão do livramento condicional
- Análise da jurisprudência sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Execução Penal", "legal_refs": ["Art. 83, inciso III, da Lei nº 13.964/2019", "Súmula 444 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["REsp 1922012/RS", "HC 307.180/RS", "HC 271.907/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T17:14:27.620895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=104", "doc_key": "af782c17d584aa4140277b1159f42f8e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'f58230ddf13c60913583205fcfab584f07bfdec44cec126cb17af74cb260c0e1'),
  ('cpiuris2025::13a7e808ceecbc30362e2f2bf1fa467f', 'doutrina', 'cp_iuris', 'Execução Penal — Benefício de Livramento Condicional', '## Benefício de Livramento Condicional

O benefício de livramento condicional é concedido aos presos que demonstram bom comportamento durante a execução da pena, desde que o tempo necessário para cometer os crimes tenha mais de 12 meses.

### Conceitos
- **Requisito cumulativo**: Condição necessária para a concessão do benefício de livramento condicional
- **Bom comportamento**: Característica necessária para a concessão do benefício de livramento condicional
- **Tempo necessário**: Prazo que deve ter transcorrido desde o início da pena para conceder o benefício

### Referências legais
- Art. 83, inciso III do CP
- Súmula 715-STF

### Jurisprudência
- STJ. 6ª Turma. AgRg no HC 776645-SP, Rel. Min. Laurita Vaz, julgado em 25/10/2022 (Info 756)

### Dicas de prova
- Entenda a distinção entre o benefício de livramento condicional e o benefício de reduzido tempo de pena
- Conheça as condições necessárias para a concessão do benefício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Execução Penal", "legal_refs": ["Art. 83, inciso III do CP", "Súmula 715-STF"], "jurisprudence": ["STJ. 6ª Turma. AgRg no HC 776645-SP, Rel. Min. Laurita Vaz, julgado em 25/10/2022 (Info 756)"], "confidence": 0.8, "extracted_at": "2026-05-31T17:14:50.471201+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=104", "doc_key": "13a7e808ceecbc30362e2f2bf1fa467f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '5b4e211527dc8eed55edc8e1739aac863370015bf11ffbee665b3ef8aac55ea2'),
  ('cpiuris2025::015190a8424d4c323b83df58791f6e3a', 'doutrina', 'cp_iuris', 'Execução Penal — Ausência de suspensão ou revogação do livramento condicional', '## Ausência de suspensão ou revogação do livramento condicional

A ausência de suspensão ou revogação do livramento condicional antes do término do período de prova enseja a extinção da punibilidade pelo integral cumprimento da pena.

### Conceitos
- **Ausência de suspensão ou revogação do livramento condicional**: ausência de suspensão ou revogação do livramento condicional antes do término do período de prova
- **Extinção da punibilidade**: extinção da punibilidade pelo integral cumprimento da pena
- **Pena**: unidade de medida da punição

### Referências legais
- Art. 85, CP

### Jurisprudência
- Súmula 617-STJ

### Dicas de prova
- Distinção entre suspensão e revogação do livramento condicional
- Importância da ausência de suspensão ou revogação do livramento condicional antes do término do período de prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.105", "page_number": 105, "discipline": "Execução Penal", "legal_refs": ["Art. 85, CP"], "jurisprudence": ["Súmula 617-STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T17:15:09.049391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=105", "doc_key": "015190a8424d4c323b83df58791f6e3a"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '6d25fb831ad3af4c556a9be1c3a9754e9fd3f648a85b847ebc87d224525a1be0'),
  ('cpiuris2025::bd4e1498a29b076a1920c1330f7ef1bb', 'doutrina', 'cp_iuris', 'Execução Penal — Extinção da Pena', '## Extinção da Pena

A pena é considerada extinta pelo seu cumprimento quando ocorre uma anomalia não passageira, como a medida de segurança não ser reversível. Nesse caso, a pessoa permanece na medida de segurança por todo o tempo de cumprimento de pena.

### Conceitos
- **Extinção da Pena**: Ocorre quando a pena é considerada extinta pelo seu cumprimento
- **Anomalia não passageira**: Ocorre quando ocorre uma anomalia que não pode ser compensada com outra medida de segurança
- **Medida de segurança**: Uma medida adotada pelo juiz para proteger a vítima ou o autor da pena

### Referências legais
- Art. 97 do CP

### Dicas de prova
- Distinção entre anomalia passageira e não passageira
- Importância de fixar prazo mínimo de internação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Execução Penal", "legal_refs": ["Art. 97 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:16:42.733042+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=106", "doc_key": "bd4e1498a29b076a1920c1330f7ef1bb"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '0da858008b6cab4461d55fec88a3f840d759ff938f42282cfdf32f9e61b76840'),
  ('cpiuris2025::b3360ca5d4758428e8f160e4f894efc1', 'doutrina', 'cp_iuris', 'Execução Penal — Superveniência de anomalia psíquica', '## Superveniência de anomalia psíquica

A superveniência de anomalia psíquica durante a execução penal pode levar à substituição da pena privativa de liberdade por medida de segurança, com o objetivo de tratar a doença mental do condenado. O artigo 108 da LEP estabelece que o condenado deve ser internado em hospital de custódia e tratamento psiquiátrico.

### Conceitos
- **Anomalia psíquica**: Doença mental ou perturbação da saúde mental
- **Medida de segurança**: Mensagem de segurança para o condenado inimputável
- **Internação hospitalar**: Internamento do condenado em hospital de custódia e tratamento psiquiátrico

### Referências legais
- Art. 108, LEP
- Art. 183, LEP
- Art. 97, Código Penal

### Dicas de prova
- Distinção entre anomalia psíquica passageira e crônica
- Importância do artigo 108 da LEP para a internação hospitalar
- Consequências da substituição da pena privativa de liberdade por medida de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Execução Penal", "legal_refs": ["Art. 108, LEP", "Art. 183, LEP", "Art. 97, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:17:00.622313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=106", "doc_key": "b3360ca5d4758428e8f160e4f894efc1"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'a09bc5f72b00fef237cbef8a7758184d9606b453c19a63094ef7b23ae862efc4'),
  ('cpiuris2025::b74e9c9af97d1b3e8ee4b24a521fa08c', 'doutrina', 'cp_iuris', 'Execução Penal — Medida de Segurança e Autorização de Saída', '## Medida de Segurança e Autorização de Saída

A medida de segurança é uma sanção penal diferente da pena, dependendo do crime e da periculosidade do agente. A autorização de saída é um direito adquirido pelos apenados em regime semiaberto, permitindo a convivência familiar e com amigos.

### Conceitos
- **Medida de Segurança**: sanção penal diferente da pena
- **Autorização de Saída**: direito adquirido pelos apenados em regime semiaberto
- **Permissão de Saída**: situação específica que permite a saída do estabelecimento prisional
- **Saída Temporária**: direito adquirido pelos apenados em regime semiaberto, permitindo convivência familiar e com amigos

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- Resolução 487/2023 do CNJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre política antimanicomial

### Dicas de prova
- Diferenciar entre permissão de saída e saída temporária
- Entender a importância da política antimanicomial no Brasil
- Conhecer as disposições da Lei nº 14.994/2024', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Execução Penal", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "Resolução 487/2023 do CNJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre política antimanicomial"], "confidence": 0.8, "extracted_at": "2026-05-31T17:17:48.549700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=107", "doc_key": "b74e9c9af97d1b3e8ee4b24a521fa08c"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2f19a331c4bb850b1b0b6257cc20ac3871b9294127aaffb233b5d8524f845c05'),
  ('cpiuris2025::6add042b3ce41c30acf267c7d961e869', 'doutrina', 'cp_iuris', 'Execução Penal — Beneficiários de saída temporária', '## Beneficiários de saída temporária

Os beneficiários da saída temporária são presos definitivos em regime semiaberto ou aberto, presos definitivos em regime fechado ou semiaberto e presos cautelares.

### Conceitos
- **Saída Temporária**: Benefício concedido a presos com liberdade parcial
- **Regime Semiaberto**: Regime de prisão que permite liberdade parcial
- **Regime Fechado**: Regime de prisão mais rigoroso

### Referências legais
- Art. 121-A do Código Penal
- Resolução nº 487/2023

### Dicas de prova
- Entenda a diferença entre regime semiaberto e fechado
- Conheça os benefícios da saída temporária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Execução Penal", "legal_refs": ["Art. 121-A do Código Penal", "Resolução nº 487/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:18:26.431531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=107", "doc_key": "6add042b3ce41c30acf267c7d961e869"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '7e2893e13df9fcd55b95b495f500c7ca1bd0399cf98f4c5ec2d5824853c1cbdf'),
  ('cpiuris2025::4baadd627d0210eb46ceeea5e9f7a6fb', 'doutrina', 'cp_iuris', 'Execução Penal — Prazo e Permissão de Saída', '## Prazo e Permissão de Saída

A permissão de saída é concedida a presos sentenciados ou provisórios para tratamento médico externo, sem recorrer ao juízo da execução penal.

### Conceitos
- **Prazo**: Tempo necessário para cumprimento das atividades
- **Permissão de Saída**: Concessão autorização para sair do estabelecimento prisional
- **Autoridade Administrativa**: Diretor do presídio, autoridade máxima dentro do estabelecimento

### Referências legais
- Art. 120, LEP
- Art. 122, LEP

### Dicas de prova
- Distinção entre prazo e permissão de saída
- Importância da autoridade administrativa na concessão de permissão de saída', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Execução Penal", "legal_refs": ["Art. 120, LEP", "Art. 122, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:18:58.547579+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=108", "doc_key": "4baadd627d0210eb46ceeea5e9f7a6fb"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3d5c4221892f17655e2861d2ba0174f536d64cb8c27e713d0e6d0b8a6c13b9f4'),
  ('cpiuris2025::3b65f7f6c169b0bc9a4d7d61ec53903e', 'doutrina', 'cp_iuris', 'Execução Penal — Monitoramento Eletrônico de Condenados', '## Monitoramento Eletrônico de Condenados

O condenado pode utilizar equipamento de monitoração eletrônica com a autorização do juiz, mesmo sem vigilância direta. Além disso, há regras específicas para condenados que cumprem pena por crimes hediondos e que participam de cursos profissionalizantes.

### Conceitos
- **Monitoramento Eletrônico**: uso de equipamentos eletrônicos para supervisionar a conduta de condenados
- **Vigilância Direta**: supervisão contínua e pessoal da conduta de condenados
- **Lei n.º 13.964/2019**: leis que regulamentam o monitoramento eletrônico de condenados
- **Lei n.º 14.843/2024**: leis que atualizaram as regras do monitoramento eletrônico e da saída temporária

### Referências legais
- Art. 1º da Lei n.º 13.964 de 2019
- Art. 2º da Lei n.º 14.843 de 2024
- Súmula 456 do STF

### Dicas de prova
- Entenda a diferença entre vigilância direta e monitoramento eletrônico
- Conheça as regras específicas para condenados que cumprem pena por crimes hediondos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Execução Penal", "legal_refs": ["Art. 1º da Lei n.º 13.964 de 2019", "Art. 2º da Lei n.º 14.843 de 2024", "Súmula 456 do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:19:56.767290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=108", "doc_key": "3b65f7f6c169b0bc9a4d7d61ec53903e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2c334164a5c5b562f05939fd3fecc61c8d2e975e62e34be0828804c19a1f071a'),
  ('cpiuris2025::91a34b0d66efdc39b2bd46d20d5b1ba7', 'doutrina', 'cp_iuris', 'Execução Penal — Saída Temporária', '## Saída Temporária

A saída temporária é concedida ao preso sentenciado, em regime semiaberto ou aberto, para testar seu comportamento e reintegração social. O período de saída é caracterizado pela ausência de vigilância direta, mas pode incluir monitoração eletrônica.

### Conceitos
- **Saída Temporária**: Concessão do juiz da execução penal para testar o comportamento e reintegração social de um preso sentenciado.
- **Vigilância Direta**: Ausência de monitorização eletrônica ou física durante a saída temporária.
- **Monitoração Eletrônica**: Uso da tecnologia para acompanhar o preso durante a saída temporária.
- **Comportamento Adequado**: Requisito para a concessão da saída temporária, que deve ser demonstrado pelo preso.
- **Cumprimento de Pena**: Requisito temporal para a concessão da saída temporária, que varia de acordo com o tipo de condenado (primário ou reincidente).
- **Objetivos da Pena**: Requisito para a concessão da saída temporária, que deve ser compatível com os objetivos da pena.
- **Irretroatividade da Lei Penal**: Princípio que proíbe a aplicação de leis mais graves após sua promulgação.
- **Lei nº 14.843/2024**: Lei que alterou as hipóteses para a saída temporária, permitindo apenas a frequência aos cursos profissionalizantes.

### Referências legais
- Art. 123, LEP

### Dicas de prova
- Entenda o conceito de saída temporária e seus requisitos.
- Conheça as hipóteses que autorizam a saída temporária e as mudanças trazidas pela Lei nº 14.843/2024.
- Avalie a importância do comportamento adequado, cumprimento de pena e compatibilidade com os objetivos da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Execução Penal", "legal_refs": ["Art. 123, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:20:25.458569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=109", "doc_key": "91a34b0d66efdc39b2bd46d20d5b1ba7"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'f58f02d00f198ecaaa8ebe7d5f52a902cb5e267898b46d43e733935b17a45ea6'),
  ('cpiuris2025::b2ff6d908da9a940bad9a78883285488', 'doutrina', 'cp_iuris', 'Execução Penal — Incompatibilidade do benefício com os objetivos da pena', '## Incompatibilidade do benefício com os objetivos da pena

A incompatibilidade entre o benefício concedido e os objetivos da pena é um princípio fundamental na execução penal, que limita a duração da pena e as condições de cumprimento.

### Conceitos
- **Benefício**: Concessão de direitos ou vantagens ao condenado
- **Objetivos da pena**: Finalidades da pena, como a reabilitação e a segurança pública
- **Incompatibilidade**: Condição em que o benefício concedido não se alinha com os objetivos da pena

### Referências legais
- Art. 123 da Lei de Execução Penal

### Jurisprudência
- AgRg no HC 437.522/PR
- Súmula 432 do STF

### Dicas de prova
- Entenda a importância dos objetivos da pena na execução penal
- Conheça as hipóteses de cabimento do habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Execução Penal", "legal_refs": ["Art. 123 da Lei de Execução Penal"], "jurisprudence": ["AgRg no HC 437.522/PR", "Súmula 432 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T17:22:26.806305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=110", "doc_key": "b2ff6d908da9a940bad9a78883285488"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '477ea59b4c33cc625a96943d132feb4277d6b38a021671097fac6d09b6cfc25d'),
  ('cpiuris2025::9be11b1ebacf10a024b36b3166fa7b92', 'doutrina', 'cp_iuris', 'Execução Penal — Saída Temporária', '## Saída Temporária

A saída temporária é um benefício concedido ao preso que frequenta cursos, mas pode ser revogada se o preso não cumprir as condições ou cometer falta grave.

### Conceitos
- **Revogação de saída temporária**: A possibilidade de a saída temporária ser revogada em caso de descumprimento das condições estabelecidas.
- **Falta grave**: Comportamento que pode levar à revogação do benefício da saída temporária.
- **Reabilitação da falta**: Condição que pode restabelecer o direito à saída temporária após a revogação inicial.

### Referências legais
- Art. 125, LEP

### Jurisprudência
- Súmula 520/STJ
- Súmula 40/STJ
- Informativo 767 do STJ

### Dicas de prova
- Entenda a diferença entre permissão de saída e saída temporária.
- Conheça as condições para a revogação da saída temporária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Execução Penal", "legal_refs": ["Art. 125, LEP"], "jurisprudence": ["Súmula 520/STJ", "Súmula 40/STJ", "Informativo 767 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T17:22:49.004413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=110", "doc_key": "9be11b1ebacf10a024b36b3166fa7b92"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '0bd9cdc7710cdf1c29d9b5f67a51ab304a3ecf63a80157bb21180f31fc82fbbe'),
  ('cpiuris2025::bb1f7c5c1da57515572e00a55face56e', 'doutrina', 'cp_iuris', 'Execução Penal — Saída Temporária', '## Saída Temporária

A saída temporária foi alterada pela Lei nº 14.843/2024, criando uma lacuna legal sobre o prazo e condições da saída. A aplicação do art. 121 por analogia é sugerida para resolver a problemática.

### Conceitos
- **Saída Temporária**: Período de liberdade concedido ao réu durante o processo
- **Lei nº 14.843/2024**: Lei que alterou a saída temporária e criou uma lacuna legal
- **Art. 121**: Artigo do Código de Processo Penal que regula a saída temporária
- **Analogia**: Método jurídico para aplicar regras de um diploma ao outro, mesmo que não sejam idênticos

### Referências legais
- Art. 124 da Lei nº 14.843/2024
- Art. 121 do Código de Processo Penal

### Dicas de prova
- Entenda a alteração da saída temporária e a lacuna legal criada pela Lei nº 14.843/2024
- Aplique o art. 121 por analogia para resolver a problemática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Execução Penal", "legal_refs": ["Art. 124 da Lei nº 14.843/2024", "Art. 121 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:23:05.871978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=109", "doc_key": "bb1f7c5c1da57515572e00a55face56e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '14a9540952e153f771c84950de0acab7e7644a13ddc0891c1abf8cb351ca4fee'),
  ('cpiuris2025::84fd3a87da5c336affcf99db45b23307', 'doutrina', 'cp_iuris', 'Execução Penal — Agravo em Execução', '## Agravo em Execução

Recurso cabível para impugnar decisões judiciais no processo de execução penal, incluindo indeferimento ou deferimento de progressão de regime e perda de dias remidos.

### Conceitos
- **Agravo em Execução**: Recurso cabível para impugnar decisões judiciais no processo de execução penal
- **Recursos em Sentido Estrito**: Rito adotado pelo agravo em execução
- **Progressão de Regime**: Mudança na classificação do regime de cumprimento de pena
- **Perda de Dias Remidos**: Derramamento de dias remidos

### Referências legais
- Art. 197 da Lei nº 9.099/1995
- Súmula 700/STF

### Jurisprudência
- AgRg no HC n. 734.258/SC
- AgRg no HC n. 795.970/SC

### Dicas de prova
- Entenda a diferença entre agravo em execução e recurso em sentido estrito
- Conheça as hipóteses de impugnação da decisão do juiz da execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Execução Penal", "legal_refs": ["Art. 197 da Lei nº 9.099/1995", "Súmula 700/STF"], "jurisprudence": ["AgRg no HC n. 734.258/SC", "AgRg no HC n. 795.970/SC"], "confidence": 0.8, "extracted_at": "2026-05-31T17:24:45.750039+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=111", "doc_key": "84fd3a87da5c336affcf99db45b23307"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '17a020e59c4772a20ac24a14455467fbdc829fb37e24c35016b43d636d4c32f7'),
  ('cpiuris2025::76fb532fe99a5c240470fd91a8a30440', 'doutrina', 'cp_iuris', 'Execução Penal — Medida de Segurança', '## Medida de Segurança

A prescrição da medida de segurança é regulada pela pena máxima abstratamente prevista para o delito, e a duração está prevista na Parte Geral do Código Penal. A medida de segurança não pode ser cumprida em estabelecimento prisional comum, exceto se houver falta de vagas.

### Conceitos
- **Medida de Segurança**: medida imposta à pessoa condenada por comportamento que afeta a sua saúde mental
- **Pena Máxima Abstrata**: pena máxima prevista para o delito, usada como base para a prescrição da medida de segurança
- **Parte Geral do Código Penal**: parte do Código Penal que estabelece as regras gerais para a execução penal

### Referências legais
- Art. 183 da Lei de Execução Penal
- Súmula 6ª Turma STJ, HC 130.162-SP

### Dicas de prova
- Entenda a diferença entre medida de segurança e pena substituta.
- Conheça as regras para a prescrição da medida de segurança e como ela é regulada pela lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Execução Penal", "legal_refs": ["Art. 183 da Lei de Execução Penal", "Súmula 6ª Turma STJ, HC 130.162-SP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:25:23.275933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=112", "doc_key": "76fb532fe99a5c240470fd91a8a30440"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '48d3549ee692e5cf46365467f264a22bb3b9fb5f2cb7265429e979d674684004'),
  ('cpiuris2025::8db1409a3866a3e21149ccd91ec90be1', 'doutrina', 'cp_iuris', 'Execução Penal — Efeito Devolutivo e Recurso em Execução', '## Efeito Devolutivo e Recurso em Execução

O recurso em execução pode ter efeito devolutivo, regressivo, diferido ou iterativo. Não possui efeito suspensivo, salvo em casos de desinternação ou liberar indivíduo sujeito a medida de segurança.

### Conceitos
- **Efeito Devolutivo**: Ocorre quando o recurso é apresentado para devolver a decisão ao juiz prolator.
- **Recurso em Execução**: Processo que visa revisar uma decisão do juiz de execução.
- **Efeito Regressivo**: Ocorre quando o recurso é apresentado para reverter a decisão do juiz prolator.
- **Desinternação**: Medida de segurança que visa liberar indivíduo sujeito a medida de segurança.
- **Habeas Corpus**: Ação que busca garantir liberdade de alguém preso ou detido ilegalmente.
- **Direito Líquido e Certo**: Direito que pode ser exercido sem necessidade de provas adicionais.

### Referências legais
- Art. 176 da LEP
- Súmula N STF

### Jurisprudência
- RE 123456
- HC 238.021-SP; HC 232.497-SP; HC 255.405-SP

### Dicas de prova
- Distinção entre efeito devolutivo e regressivo.
- Exceção para desinternação ou liberar indivíduo sujeito a medida de segurança.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Execução Penal", "legal_refs": ["Art. 176 da LEP", "Súmula N STF"], "jurisprudence": ["RE 123456", "HC 238.021-SP; HC 232.497-SP; HC 255.405-SP"], "confidence": 0.8, "extracted_at": "2026-05-31T17:25:42.865906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=111", "doc_key": "8db1409a3866a3e21149ccd91ec90be1"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '9572b2e147d1a9b8cc9fff1eadfffb7784527520d87e8623d0c16ac9e538dd0c'),
  ('cpiuris2025::2a09fe0a9275b29f9bb85eeacef1d437', 'doutrina', 'cp_iuris', 'Execução Penal — Internação em hospital de custódia após medida de segurança', '## Internação em hospital de custódia após medida de segurança

A pessoa que recebeu medida de segurança, mas teve a punibilidade extinta por prescrição, não pode permanecer internada no hospital de custódia.

### Conceitos
- **Medida de segurança**: Mensagem do juiz para o réu, com objetivo de evitar que ele cometa novos crimes
- **Punibilidade**: O período durante o qual a pessoa é responsável por um crime
- **Prescrição**: O processo pelo qual a lei considera que o crime não foi cometido, pois tempo se passou desde então

### Referências legais
- Art. 318 do Código de Processo Penal
- ...

### Jurisprudência
- Súmula 387/2013 do STF
- ...

### Dicas de prova
- Entenda a diferença entre medida de segurança e punibilidade
- Conheça o conceito de prescrição no direito penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Execução Penal", "legal_refs": ["Art. 318 do Código de Processo Penal", "..."], "jurisprudence": ["Súmula 387/2013 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T17:26:49.140171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=112", "doc_key": "2a09fe0a9275b29f9bb85eeacef1d437"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2d68c927d51b7dd0e491e464685ba0521379acc37cd4bcdb75de1c93cb3dd75f'),
  ('cpiuris2025::8852496ef60c742927b226a2322b296f', 'doutrina', 'cp_iuris', 'Execução Penal — Medidas de Segurança e Autorizações de Saída', '## Medidas de Segurança e Autorizações de Saída

Resumo das assertivas sobre medidas de segurança, autorizações de saída e recursos.

### Conceitos
- **Medida de segurança**: Mensagem de segurança imposta ao acusado
- **Pena privativa de liberdade**: Pena que envolve a privação da liberdade do acusado
- **Custo julgada**: Conceito jurídico que se refere à imutabilidade de uma decisão judicial
- **Agravo**: Recurso que visa revisar ou anular uma decisão anterior

### Referências legais
- Art. 319 do Código de Processo Penal
- Súmula 313 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre medidas de segurança

### Dicas de prova
- Entenda a diferença entre medida de segurança e pena privativa de liberdade.
- Conheça o conceito de custo julgada e sua importância na execução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.113", "page_number": 113, "discipline": "Execução Penal", "legal_refs": ["Art. 319 do Código de Processo Penal", "Súmula 313 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre medidas de segurança"], "confidence": 0.8, "extracted_at": "2026-05-31T17:27:33.082637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=113", "doc_key": "8852496ef60c742927b226a2322b296f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'ba1e3971481277879d489848d3f0b2d5e0c03acf9630045da6a7df391427a05d'),
  ('cpiuris2025::61d6d0514f184cc1a43148c55afc90ba', 'doutrina', 'cp_iuris', 'Execução Penal — Saída temporária', '## Saída temporária

Resumo do trecho sobre saída temporária em execução penal, incluindo prazos e requisitos.

### Conceitos
- **Agravo Regumental**: Recurso apresentado contra decisão de não receber agravo
- **Habeas Corpus**: Recurso para garantir liberdade do preso
- **Saída Temporária**: Período permitido ao preso se ausentar do presídio

### Referências legais
- Art. 122 da Lei n.º 7.210/84
- Art. 124 da Lei n.º 7.210/84

### Jurisprudência
- HC 489.106/RS
- HC 130883

### Dicas de prova
- Entenda a diferença entre agravo e habeas corpus
- Conheça os requisitos para saída temporária em execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Execução Penal", "legal_refs": ["Art. 122 da Lei n.º 7.210/84", "Art. 124 da Lei n.º 7.210/84"], "jurisprudence": ["HC 489.106/RS", "HC 130883"], "confidence": 0.8, "extracted_at": "2026-05-31T17:27:40.237578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=114", "doc_key": "61d6d0514f184cc1a43148c55afc90ba"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '8902a95e71a71c0a522df2780776ce87dd1b279f493d21ed464606141cecf0c3'),
