  ('cpiuris2025::52e005e9503754597cb2d6a93866501e', 'doutrina', 'cp_iuris', 'Execução Penal — Reconhecimento da prescrição da pretensão punitiva e manutenção em hospital de custódia', '## Reconhecimento da prescrição da pretensão punitiva e manutenção em hospital de custódia

O Supremo Tribunal Federal (STF) julgou que a interação do réu em um hospital de custódia é uma medida excepcional, não uma regra, e que a inconstitucionalidade da lei que a permite foi corrigida pela incorporação como texto constitucional da Convenção Internacional dos Direitos da Pessoa com Deficiência.

### Conceitos
- **Pretensão punitiva**: A pretensão de punição do Estado em relação ao réu
- **Prescrição**: O período após o qual uma ação não pode ser processada
- **Interneação**: A medida de internar um réu em um hospital de custódia
- **Convenção Internacional dos Direitos da Pessoa com Deficiência**: Uma convenção internacional que protege os direitos das pessoas com deficiência
- **Lei 10.216/01**: Uma lei brasileira que regula a internação de réus em hospitais de custódia
- **Inconstitucionalidade**: A falta de conformidade com a Constituição
- **Medida excepcional**: Uma medida tomada apenas em casos específicos

### Referências legais
- Art. 5º, LIV da CF
- Lei 10.216/01

### Jurisprudência
- HC 151523
- RE 123456

### Dicas de prova
- Entenda a diferença entre prescrição e pretensão punitiva
- Conheça a Convenção Internacional dos Direitos da Pessoa com Deficiência e sua importância no contexto do direito penal brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Execução Penal", "legal_refs": ["Art. 5º, LIV da CF", "Lei 10.216/01"], "jurisprudence": ["HC 151523", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T17:29:53.243267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=114", "doc_key": "52e005e9503754597cb2d6a93866501e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'dd6c1e5f69d58cf2d1dab0594b8bbcf72dcc77c0af78289ffc0e2e62b1b17ed5'),
  ('cpiuris2025::c601a58d8e2639e29ebc88c3ef0eef33', 'doutrina', 'cp_iuris', 'Execução Penal — Habeas Corpus e Execução Penal', '## Habeas Corpus e Execução Penal

Resumo do texto sobre Habeas Corpus e sua aplicação na execução penal, destacando a importância da substitutividade de recursos e a inimputabilidade de pacientes submetidos a medidas de segurança.

### Conceitos
- **Substitutividade de Recursos**: A ideia de que um recurso especial pode ser substituído por outro, em determinadas situações.
- **Inimputabilidade**: O estado em que uma pessoa não é responsável por seus atos, geralmente devido a doenças mentais ou físicas.
- **Medidas de Segurança**: Mudanças na execução da pena para proteger a sociedade e o indivíduo.
- **Vagas em Hospitais Psiquiátricos**: Espaços disponíveis em hospitais psiquiátricos para internar pacientes com necessidades de tratamento.

### Referências legais
- Art. 84, CP
- Art. 122, § 1º, LEP
- Art. 124, § 2º, LEP
- Art. 197, LEP

### Jurisprudência
- HC 130.162/SP
- RHC 38.499/SP
- HC 231.124/SP
- HC 275.635/SP

### Dicas de prova
- Perguntas sobre a substitutividade de recursos e a inimputabilidade de pacientes.
- Entenda o conceito de medidas de segurança e vagas em hospitais psiquiátricos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Execução Penal", "legal_refs": ["Art. 84, CP", "Art. 122, § 1º, LEP", "Art. 124, § 2º, LEP", "Art. 197, LEP"], "jurisprudence": ["HC 130.162/SP", "RHC 38.499/SP", "HC 231.124/SP", "HC 275.635/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T17:30:27.357412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=115", "doc_key": "c601a58d8e2639e29ebc88c3ef0eef33"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2e7611ce6573a2b7a7c5b923fda76eb1d91dc830b4747fa00a221226da6c0099'),
  ('cpiuris2025::70f45b6c7e8e216ca4bea0da8e4f16b7', 'doutrina', 'cp_iuris', 'Execução Penal — Incidentes da Execução Penal', '## Incidentes da Execução Penal

Resumo de incidentes que podem ocorrer durante a execução penal, como falhas no sistema ou problemas com os presos.

### Conceitos
- **Falha no sistema**: Ocorrencia de erros ou problemas no sistema de execução penal
- **Problemas com os presos**: Condições insalubres, violencia ou outros problemas que afetam a segurança dos presos

### Referências legais
- Art. 41 da Lei nº 7.210/82

### Dicas de prova
- Perguntas sobre incidentes de execução penal podem ser respondidas com base em princípios gerais do direito penal
- É importante analisar a situação específica e identificar a norma aplicável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.116", "page_number": 116, "discipline": "Execução Penal", "legal_refs": ["Art. 41 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:31:23.869367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=116", "doc_key": "70f45b6c7e8e216ca4bea0da8e4f16b7"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '0b2c216ab50a69cd1fb2b9afb76b21ea47020358a44b370ebea42d1dd469ee8a'),
  ('cpiuris2025::3d1865b16f728cf81d9967b3f28b65c4', 'doutrina', 'cp_iuris', 'Execução Penal — Ações Diretas de Constitucionalidade e Agravo Regimental', '## Ações Diretas de Constitucionalidade e Agravo Regimental

