- **Pacote Anticrime**: Lei que estabelece medidas para reduzir a reincidência criminosa
- **Regras de Mandela**: Princípios utilizados na execução penal para garantir os direitos dos presos
- **Princípios de Yogyakarta**: Princípios utilizados na execução penal para garantir a dignidade e os direitos humanos dos presos

