  ('cpiuris2025::52fbb2bd03d40996f475f0cc907f3605', 'doutrina', 'cp_iuris', 'Execução Penal — Referências Bibliográficas', '## Referências Bibliográficas

Lista de livros relacionados à Execução Penal para estudo e referência.

### Conceitos
- **Avena, Norberto**: Autor do livro "Execução Penal: esquematizado"
