  ('cpiuris2025::6e51d1041ef76e740d1da6eb211677c6', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Biografia do Autor', '## Biografia do Autor

Resumo biográfico do autor, Alexandre Salim, que é promotor de justiça e professor de Direito Penal.

### Conceitos
- **Promotor de Justiça**: Magistrado responsável por representar o Estado na Justiça
- **Delegado de Polícia**: Oficial responsável pela investigação de crimes

### Dicas de prova
- Perguntas sobre a biografia do autor podem ser respondidas com base em seus títulos e experiência profissional.
- A importância da formação acadêmica do autor é relevante para a prova.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.3", "page_number": 3, "discipline": "Legislação Penal Especial", "legal_refs": [], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:33:51.145991+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=3", "doc_key": "6e51d1041ef76e740d1da6eb211677c6"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c099dc4947840041a12a7b0a649bbd318e51ef6e485965610092f26d03e58e69'),
  ('cpiuris2025::bc10407b323d5592654194c55b8cb346', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Introdução à Legislação Penal Especial', '## Introdução à Legislação Penal Especial

Resumo objetivo: Legislação penal especial é um conjunto de normas que regulamentam crimes específicos, com características e requisitos distintos da legislação penal geral.

### Conceitos
- **Legislação Penal Especial**: conjunto de normas que regulamentam crimes específicos
- **Crime Especial**: crime que tem características e requisitos distintos da legislação penal geral

### Referências legais
- Art. 1 da Lei nº 9.733, de 26 de novembro de 1998

### Dicas de prova
- Entenda a distinção entre crime especial e crime geral
- Conheça as características que definem um crime especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.2", "page_number": 2, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1 da Lei nº 9.733, de 26 de novembro de 1998"], "jurisprudence": [], "confidence": 0.5, "extracted_at": "2026-05-31T17:34:04.038655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=2", "doc_key": "bc10407b323d5592654194c55b8cb346"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e13e150f97dd365a6fdd5a4e3275e3a1a61e3b10c0ed32f22e63f63c74dfb3ea'),
  ('cpiuris2025::c87ed8ca9580e205cc28e5b9c6a0d991', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Vedação à concessão de graça e anistia', '## Vedação à concessão de graça e anistia

Rege a concessão de graça, anistia e indulto em crimes hediondos.

### Conceitos
- **Graça**: Concessão de pena reduzida ou suspensa
- **Anistia**: Imunidade total ou parcial a punição por crime cometido
- **Indulto**: Concessão de liberdade antecipada ou redução da pena

### Referências legais
- Art. 1º, § 2º da Lei nº 8.072/1990

### Dicas de prova
- Entenda a diferença entre graça, anistia e indulto
- Conheça as hipóteses de exclusão da vedação à concessão desses institutos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, § 2º da Lei nº 8.072/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:34:15.191383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=4", "doc_key": "c87ed8ca9580e205cc28e5b9c6a0d991"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '83546914d76382b9307b185f7926e7fc060ac3e8489a31d8aad9ca381b6c1118'),
  ('cpiuris2025::54f736ee07e086d9c4cc5e44a178f7ef', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Pena Privativa de Liberdade e Limite Temporal da Pena', '## Pena Privativa de Liberdade e Limite Temporal da Pena

Resumo do capítulo sobre pena privativa de liberdade, limites temporais e suspensão condicional da pena.

### Conceitos
- **Pena Privativa de Liberdade**: Medida de segurança aplicada ao indivíduo
- **Limite Temporal da Pena**: Prazo dentro do qual a pena deve ser imposta
- **Suspensão Condicional da Pena (Sursis)**: Meio que permite o reatamento da pena, com condições

### Referências legais
- Art. 5º da Lei nº 11.343/2006

### Dicas de prova
- Entenda a diferença entre pena privativa de liberdade e suspensão condicional da pena.
- Conheça as limitações temporais da pena e como elas são aplicadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º da Lei nº 11.343/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:35:48.907662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=4", "doc_key": "54f736ee07e086d9c4cc5e44a178f7ef"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0f633bfa78d4a881be587547d0da2ed1cf5e8b636a19bb25caf8d918d60d4c54'),
  ('cpiuris2025::0e689acc18e7411eb7e07ba06d71c59e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Vulnerável e outras contravenções penais', '## Vulnerável e outras contravenções penais

Trecho que aborda as contravenções penais relacionadas a vulneráveis, como suicídio, automutilação, sequestro de menores, tráfico de pessoas e outros.

### Conceitos
- **Vulnerável**: Pessoa que precisa de proteção especial
- **Sequestro de menor**: Sequestro cometido contra pessoa com menos de 18 anos
- **Tráfico de pessoas**: Comércio de pessoas, especialmente crianças e adolescentes
- **Suicídio**: Ato de tirar a própria vida
- **Automutilação**: Atos que causam danos físicos ou psicológicos à pessoa

### Referências legais
- Art. 3 da Lei nº 7.870/89
- Súmula 342 do STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Proteção de vulneráveis

### Dicas de prova
- Entenda a definição de vulnerável e suas implicações legais
- Identifique as contravenções penais relacionadas a sequestro, tráfico de pessoas e suicídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3 da Lei nº 7.870/89", "Súmula 342 do STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Proteção de vulneráveis"], "confidence": 0.8, "extracted_at": "2026-05-31T17:36:00.320809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=4", "doc_key": "0e689acc18e7411eb7e07ba06d71c59e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0b7443919edc14bfa6866278dfdf4b1dee18a4ef700ca98b2fbb8e4d1ed993a4'),
  ('cpiuris2025::3def47c3b4a3364cc62ab1eab8d09899', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Reincidência e Tráfico Ílico de Drogas', '## Reincidência e Tráfico Ílico de Drogas

Trecho aborda reincidência e tráfico ilícito de drogas, incluindo fixação da pena, progressão de regime e associação para o tráfico.

### Conceitos
- **Reincidência**: Acomodação do réu ao mesmo tipo de crime que o levou à reincidência
- **Tráfico Ílico de Drogas**: Atividade processada pela lei, com ou sem finalidade lucrativa, destinada a obter drogas ilegais
- **Fixação da Pena**: A determinação do valor da pena imposta ao réu
- **Progressão de Regime**: O processo de transição do regime de prisão a regime de liberdão condicional
- **Associação Para o Tráfico**: A relação de colaboração entre réus para fins de tráfico ilícito de drogas
- **Previsão de Tipo Culposo**: O reconhecimento da responsabilidade do réu por um ato culposo
- **Livramento Condicional**: A condenação do réu com a condição de cumprir pena em regime de liberdão condicional

### Referências legais
- Art. 2.º da Lei nº 11.343/2006

### Dicas de prova
- Entenda a distinção entre reincidência e progressão de regime
- Conheça as hipóteses de tráfico ilícito de drogas
- Aprenda a fixar a pena corretamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2.º da Lei nº 11.343/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:37:09.210339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=5", "doc_key": "3def47c3b4a3364cc62ab1eab8d09899"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c336b7dfcad0959b7d9de523491fd6a7aadedb46f29fe44b6a3cc2a2dfeebdfa'),
  ('cpiuris2025::6e9a88b8d2159d050485aafec0dffd6a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Elementos do crime e suas classificações', '## Elementos do crime e suas classificações

O texto aborda a classificação de crimes relacionados a armas de fogo, incluindo omissão de cautela, porte ilegal, disparo de arma ou acionamento de munição, posse ou porte ilegal de arma de uso restrito e comércio ilegal de armas.

### Conceitos
- **Elemento Espacial**: A localização física da arma no momento do crime
- **Omissão de Cautela**: A falta de medidas preventivas antes do crime
- **Porte Ilegal de Arma de Foguete**: A posse ou transporte ilegal de uma arma de fogo sem autorização
- **Disparo de Arma ou Acionamento de Munição**: O ato de disparar uma arma ou acionar munição sem intenção criminosa
- **Posse ou Porte Ilegal de Arma de Uso Restrito**: A posse ou transporte ilegal de uma arma de fogo com uso restrito
- **Comércio Ilegal de Arma de Foguete**: A venda ou compra ilegal de armas de fogo

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a classificação dos crimes relacionados a armas de fogo
- Identifique os elementos espaciais e omissões de cautela nos crimes
- Diferencie entre porte ilegal, disparo de arma ou acionamento de munição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:38:21.109920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=5", "doc_key": "6e9a88b8d2159d050485aafec0dffd6a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ae9228ad5bf19534037c9ab3d184b45935b8ffb26835894f25f17a1df30d00ab'),
  ('cpiuris2025::cec23fad11538b9be94a25084723083d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Definições e Classificação', '## Definições e Classificação

Este trecho aborda conceitos fundamentais da Legislação Penal Especial, incluindo a classificação e a competência do juiz.

### Conceitos
- **Conceito**: Entendido como o conjunto de regras que regulamentam as relações entre os indivíduos e o Estado.
- **Classificação**: A organização lógica dos crimes em categorias ou classes para fins de tratamento jurídico.

### Referências legais
- Art. 1 da Lei nº 9.733, de 26 de novembro de 1998

### Dicas de prova
- Entenda o conceito de classificação em Legislação Penal Especial.
- Identifique a competência do juiz em relação ao crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.5 (4)", "page_number": 5, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1 da Lei nº 9.733, de 26 de novembro de 1998"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-31T17:38:33.924046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=5", "doc_key": "cec23fad11538b9be94a25084723083d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '71267e3655f1c375ecd6705dd4cc65189136934cab0612fd4532ef824d687c62'),
  ('cpiuris2025::ef078909ddac7b010bf601c993d28515', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tráfico Internacional de Arma de Foguete', '## Tráfico Internacional de Arma de Foguete

Rege o tráfico internacional de armas de foguete, incluindo a competência e os requisitos para interceptação.

### Conceitos
- **Competência**: A competência é a esfera jurisdicional que tem poder para julgar um caso.
- **Interceptação**: A interceptação é o ato de capturar e analisar comunicações telefônicas sem autorização.
- **Requisitos para Interceptação**: Os requisitos para a interceptação incluem a ordem judicial, a identificação do suspeito e a garantia da privacidade.
- **Serendipidade**: A serendipidade é o acaso que leva à descoberta de algo inesperado.
- **Tráfico Internacional**: O tráfico internacional refere-se ao comércio ou transporte de bens entre países diferentes.
- **Arma de Foguete**: Uma arma de foguete é um tipo de veículo aéreo que é propelido por um motor e pode voar até altitudes extremas.
- **Pacote Anticrime**: O pacote anticrime é uma legislação que visa combater o crime organizado e reduzir a violência no Brasil.
- **Inconstitucionalidade**: A inconstitucionalidade é a situação em que uma lei ou ato do governo é considerado ilegal ou inválido.

### Referências legais
- Art. 1 da Lei Nº 9.296/1996
- Súmula 387 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Interceptação Telefônica

### Dicas de prova
- Entenda a competência e os requisitos para interceptação.
- Identifique a serendipidade na interceptação telefônica.
- Conheça o pacote anticrime e sua importância na legislação penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1 da Lei Nº 9.296/1996", "Súmula 387 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Interceptação Telefônica"], "confidence": 0.8, "extracted_at": "2026-05-31T17:39:14.717040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=5", "doc_key": "ef078909ddac7b010bf601c993d28515"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ad23809ece3ea9059eb3f943b90cd8e8cc6b2ab10160c14910ceaef56da02e0c'),
  ('cpiuris2025::7f9414a0417d41e259dfc1fbd5f6eb1b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Classificaçao dos Crimes', '## Classificaçao dos Crimes

O capítulo aborda a classificação dos crimes em comuns, próprios, formais e comissivos, além de exceções como o crime omissivo impróprio.

### Conceitos
- **Crime Comum**: regra
- **Crime Próprio**: exceção
- **Crime Formal**: regra
- **Crime Comissivo**: regra
- **Crime Omissivo Impróprio**: exceção

### Referências legais
- Art. 3 da Lei nº 12.850/2013

### Dicas de prova
- Entenda a classificação dos crimes e suas exceções.
- Identifique o tipo misto alternativo e as causas de aumento de pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3 da Lei nº 12.850/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:40:01.127250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=6", "doc_key": "7f9414a0417d41e259dfc1fbd5f6eb1b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0e09feaeb37d22146898f0299a47ce774fea2b127d80177ece4259119b5f6acc'),
  ('cpiuris2025::34c7b167ce3f773ec6599f6c77a99176', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — SUSPENSÃO OU PROIBIÇÃO DE SE OBTER A PERMISSÃO OU A HABILITAÇÃO PARA DIRIGIR VEÍCULO AUTOMOTOR', '## SUSPENSÃO OU PROIBIÇÃO DE SE OBTER A PERMISSÃO OU A HABILITAÇÃO PARA DIRIGIR VEÍCULO AUTOMOTOR

Rege a suspensão ou proibição de obter a permissão ou a habilitação para dirigir veículo automotor.

### Conceitos
- **Habilidade para dirigir**: direito concedido ao condutor para operar um veículo automotor
- **Suspensão de direção**: obrigação de não exercer a atividade de dirigir

### Referências legais
- Art. 77 da Lei Nº 11.340/2006
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre suspensão e proibição de habilitação para dirigir
- Conceito de direção sem habilitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 77 da Lei Nº 11.340/2006", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T17:40:50.652283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=6", "doc_key": "34c7b167ce3f773ec6599f6c77a99176"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b7158484602de143cc3c4af06a9ea5bd024cfd1be3db76dcf41c6aa4f5bc0c0e'),
  ('cpiuris2025::ac365217a01a86a441079209a57b3064', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Investiga̧ão e meios de obtê̄n de prova', '## Investiga̧ão e meios de obtê̄n de prova

Rege as regras para a investigação e obtenção de provas em processos criminais.

### Conceitos
- **Colaboração Premiada**: A colaboração de uma pessoa com o Estado em troca de benefícios legais.
- **Delação Premiada**: A confissão de um crime feita por alguém que tem direito a benefício legal.
- **Colaboração para Libertação**: A colaboração de uma pessoa com o Estado em troca da liberdade do outro.
- **Colaboração Preventiva**: A colaboração de uma pessoa com o Estado antes de um crime ser cometido.
- **Negócio Jurídico Processual Personalíssimo**: Um acordo entre as partes que não precisa de registro no cartório.
- **Direito Penal Premial**: A punição aplicada ao autor de um crime após a condenação.
- **Benesse da Colaboração Premiada**: Os benefícios legais concedidos à pessoa que colabora com o Estado.
- **Papel do Juiz**: A responsabilidade do juiz em garantir a justiça e a igualdade de todos os envolvidos.

### Referências legais
- Art. 3º-A da Legislação Penal Especial

### Dicas de prova
- Entenda a diferença entre delação premiada e colaboração para libertação.
- Conheça os benefícios legais concedidos à pessoa que colabora com o Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º-A da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:41:34.679941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=6", "doc_key": "ac365217a01a86a441079209a57b3064"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '78d67b68066368d79ee78c24c05a11ac594b6f8bad3893fd59941f07c3e726a7'),
  ('cpiuris2025::370705a3793441db8213e6ae2a6e249c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Abuso de Autoridade', '## Abuso de Autoridade

Rege o abuso de autoridade, definindo-o como ato que, por meio de ameaça ou violência, impede a pessoa de exercer direitos ou deveres inerentes à sua condição ou função.

### Conceitos
- **Abuso de Autoridade**: ato que impede a pessoa de exercer direitos ou deveres inerentes à sua condição ou função
- **Ameaça**: menudo que cause medo ou ansiedade
- **Violência**: uso excessivo de força física

### Referências legais
- Art. 10 da Lei nº 13.869/2019

### Dicas de prova
- Distinção entre abuso de autoridade e abuso de poder
- Reconhecimento de ameaça e violência como formas de abuso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.6 (4)", "page_number": 6, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 10 da Lei nº 13.869/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:41:35.152401+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=6", "doc_key": "370705a3793441db8213e6ae2a6e249c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '630cc872a50cd6cd446b354de99deabd11dc3d95fd7cb5f8485f605b5cb50e78'),
  ('cpiuris2025::8324aad3da522b1ec8f3d05b051a3b74', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Violações do Direito Processual', '## Violações do Direito Processual

Trecho que lista diversas violações ao direito processual, incluindo a divulgação de gravações sem relação com a prova e a informação falsa sobre procedimentos judiciais.

### Conceitos
- **Violação de Domicílio**: Ato que viole o direito à privacidade do domicilio
- **Conduzas Análogas**: Atos que têm natureza semelhante a uma infração penal
- **Fraude Processual**: Técnica utilizada para prejudicar o direito de alguém

### Referências legais
- Art. 6º, § 3º da Lei nº 9.449/1997

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Perguntas que exigem distinção entre diferentes violações ao direito processual
- Reconhecer a importância da divulgação de gravações em procedimentos judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 6º, § 3º da Lei nº 9.449/1997"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T17:43:25.578797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=7", "doc_key": "8324aad3da522b1ec8f3d05b051a3b74"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '2fffa14795a68f49bc768b6f5efe5a1a833656e77f1187724fae90f10312c538'),
  ('cpiuris2025::0e74178c10bd43e2c1bcd8436d166124', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Procedimento da Lavagem de Dinheiro', '## Procedimento da Lavagem de Dinheiro

Rege o procedimento para a lavagem de dinheiro, incluindo as fases e competência para julgamento.

### Conceitos
- **Lavagem de Dinheiro**: Atividade processada com o objetivo de ocultar a origem de fundos obtidos ilegalmente
- **Iter Criminis**: Fase do processo que envolve a lavagem de dinheiro em várias etapas
- **Colocação ou Placement**: Primeira fase da lavagem de dinheiro, onde o dinheiro é introduzido no sistema financeiro
- **Ocultação/Dissimulação/Transformação/Layering**: Segunda fase da lavagem de dinheiro, onde o dinheiro é ocultado ou transformado para evitar detecção
- **Integração**: Terceira fase da lavagem de dinheiro, onde o dinheiro é reintroduzido no sistema financeiro como se fosse legítimo

### Referências legais
- Art. 1º da Lei nº 9.613/1998

### Dicas de prova
- Entenda a diferença entre iter criminis e colocação/placement
- Conheça as fases da lavagem de dinheiro e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º da Lei nº 9.613/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:43:44.813000+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=7", "doc_key": "0e74178c10bd43e2c1bcd8436d166124"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '911eafc73c04a19735b439e7cccf1f7eabf196b38fedea99131236b1fdff0261'),
  ('cpiuris2025::73820e2e110ff6ff115298f489345c2e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Disposições Gerais e Sujeitos do Crime', '## Disposições Gerais e Sujeitos do Crime

