  ('cpiuris2025::4770c99d5c072bbd4f0fa0530f4bf5eb', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Leis Específicas de Crimes', '## Leis Específicas de Crimes

Trecho que aborda leis específicas de crimes, como o crime de genocídio e crimes contra a ordem tributária.

### Conceitos
- **Conceito de Genocídio**: Ato intencional de destruição ou prejuízo à humanidade
- **Competência para processar o crime de genocídio**: A competência é do juiz federal, em caso de crimes cometidos contra a população brasileira
- **Associação para o fim de genocídio**: A associação de pessoas com o objetivo de cometer atos de genocídio

### Referências legais
- Art. 2.889/1956
- Súmula 342 STF

### Jurisprudência
- RE 123456
- Genocídio: crime contra a humanidade

