  ('cpiuris2025::55d067d7d04060f264c79fa9663b49e1', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Leis e Capítulos específicos da Legislação Penal Especial', '## Leis e Capítulos específicos da Legislação Penal Especial

