  ('cpiuris2025::6d49aed26de4093480ad1d4d9fdc2f27', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Lei N.º 9.605/1998 - Crimes Ambientais', '## Lei N.º 9.605/1998 - Crimes Ambientais

Rege-se a responsabilidade por crimes ambientais, definindo o conceito de crime ambiental e estabelecendo as sanções para os mesmos.

### Conceitos
- **Crime Ambiental**: Ato ou omissão que viole a ordem ecologicamente correta
- **Responsabilidade Penal**: O Estado se torna responsável pela infração cometida

