  ('cpiuris2025::28e4ee06a01d96d7eddc8f771b81e821', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Definição de crimes ambientais e competência', '## Definição de crimes ambientais e competência

O texto define a competência para os crimes ambientais, destacando a importância da legislação penal especial.

### Conceitos
- **Meio Ambiente**: A natureza ou o ambiente em que as pessoas vivem.
- **Competência**: O direito de julgar um crime é do juiz competente.
- **Crimes contra a Fauna**: Crimes cometidos contra animais ou espécies.
- **Crime Ambiental**: Crimes cometidos com dano ao meio ambiente.

### Referências legais
- Art. 1 da Lei nº 9.605/1998

### Dicas de prova
- Entenda a competência para os crimes ambientais.
- Identifique as espécies de crimes ambientais definidos na legislação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1 da Lei nº 9.605/1998"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-31T17:47:23.965901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=9", "doc_key": "28e4ee06a01d96d7eddc8f771b81e821"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '53d782aeeda8332aa768d80c85669d052b48a8f627bf8ad12128543aa19762ae'),
  ('cpiuris2025::19408755a28fc382d46488e4afa1e227', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Penas e Medidas de Segurança', '## Penas e Medidas de Segurança

Trecho que detalha as diferentes fases da aplicação das penas, incluindo a pena-base, pena-provisória, multa, restrições de direitos e medidas despenalizadoras.

### Conceitos
- **Pena-base**: parte fundamental da pena
- **Pena-provisória**: pena aplicada em caso de não cumprimento das condições da pena-base
- **Multa**: forma de pena que não envolve privação de liberdade
- **Restrições de direitos**: medidas que limitam os direitos do réu
- **Suspensão Condicional da Pena**: pene aplicada em caso de cumprimento das condições estabelecidas
- **Medidas Despenalizadoras**: medidas que reduzem a gravidade do crime

### Referências legais
- Art. 12 da Lei nº 9.735, de 26 de fevereiro de 1998

### Dicas de prova
- Entenda a diferença entre pena-base e pena-provisória
- Conheça as diferentes formas de penas (multa, restrições de direitos, etc.)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 12 da Lei nº 9.735, de 26 de fevereiro de 1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:48:08.249193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=9", "doc_key": "19408755a28fc382d46488e4afa1e227"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ddd02b5b9a9d8442b600472aa9bfb92b93ea0aae4dbf619090114c5a404f23a7'),
