  ('cpiuris2025::a703741dcef5875b242f3584ca04d823', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Lei dos Crimes Resultantes de Preconceito de Raçă ou de Cor', '## Lei dos Crimes Resultantes de Preconceito de Raçă ou de Cor

Rege-se a lei aos crimes resultantes de preconceito de raça ou de cor, com fundamentos constitucionais e histórico apresentados.

### Conceitos
- **Preconceito**: Atitude de desigualdade ou discriminação
- **Racismo**: Atitude de desrespeito ou preconceito contra uma raça ou etnia
- **Discriminação**: Ação de tratar alguém de forma diferente por causa de características físicas ou étnicas
- **Homofobia**: Atitude de desrespeito ou preconceito contra pessoas LGBTQ+
- **Transfobia**: Atitude de desrespeito ou preconceito contra pessoas transgêneros

### Referências legais
- Art. 7 da Lei nº 7.716/1989

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de preconceito e como ele está relacionado com o racismo e a discriminação.
- Conheça as diferentes formas de discriminação, incluindo homofobia e transfobia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 7 da Lei nº 7.716/1989"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T17:50:46.119681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=10", "doc_key": "a703741dcef5875b242f3584ca04d823"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'dab76170cfcf9ded02c64db8fcd388759ce7382f6cdf72f0c497a37548b5683e'),
  ('cpiuris2025::6828e7f0af6b5e324b3e9e34e86ba01b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Injúria racial e definições de bem jurídico, sujeito e elementos do tipo', '## Injúria racial e definições de bem jurídico, sujeito e elementos do tipo

Trecho que apresenta as definições de injúria racial, bem jurídico, sujeito e elementos do tipo, bem como a consumação.

### Conceitos
- **Injúria racial**: Ato que veda o discurso racista
- **Bem jurídico**: Direito ou interesse de terceiro
- **Sujeito**: Pessoa física ou jurídica responsável por um ato
- **Elementos do tipo**: Características que definem o tipo de crime
- **Consumação**: Ocorrencia do fato que configura o crime

### Referências legais
- Art. 2º-A da Legislação Penal Especial

### Dicas de prova
- Perguntas sobre a definições de injúria racial e bem jurídico podem ser respondidas com base nas definições apresentadas no texto.
- A distinção entre sujeito e elementos do tipo é fundamental para responder corretamente às perguntas
- A consumação é um elemento essencial para a configuração do crime de injúria racial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.10 (3)", "page_number": 10, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º-A da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:50:54.478685+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=10", "doc_key": "6828e7f0af6b5e324b3e9e34e86ba01b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '36f627bce4df61459ca8303eeffbdf3fb4e29273abc3e03e84804793254b6ebf'),
