  ('cpiuris2025::c2f4bb919a441999863dbbdce6279d8f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acesso a estabelecimento comercial e outros locais', '## Acesso a estabelecimento comercial e outros locais

