  ('cpiuris2025::a7cbbdf089bb389b551caf38900d87f9', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Bem jurídico, sujeito e elementos do tipo', '## Bem jurídico, sujeito e elementos do tipo

