  ('cpiuris2025::07be765460bf33064290ddfe17f7a87e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Definição de Crime e Tipos Penais', '## Definição de Crime e Tipos Penais

O texto apresenta as disposições iniciais da Legislação Penal Especial, abordando a definição de crime e os tipos penais.

### Conceitos
- **Bem jurídico**: Objeto do direito penal
- **Sujeitos**: Pessoas que cometem ou são responsáveis por um crime
- **Elementos do tipo**: Características necessárias para a configuração de um crime
- **Consumação**: O ato de completar o crime

### Referências legais
- Art. 21 da Legislação Penal Especial

