  ('cpiuris2025::7a1ccb8e2169e48cd18d6e9f93275ee1', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Vedação à concessão de graça e anistia', '## Vedação à concessão de graça e anistia

A Lei n.º 8.072/1990 estabelece a vedação à concessão de graça, anistia e indulto em relação aos crimes hediondos e equiparados.

### Conceitos
- **Graça**: Causa extintiva da punibilidade concedida por decreto presidencial a indivíduo determinado
- **Anistia**: Esquecimento jurídico da infração penal, concedida pelo Congresso Nacional por meio de lei
- **Indulto**: Concedido pela Constituição Federal, mas não expressamente previsto em lei

### Referências legais
- Art. 107, II, CP/88

### Dicas de prova
- Diferenciar entre graça e indulto
- Entender a noção de anistia como esquecimento jurídico da infração penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.13", "page_number": 13, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 107, II, CP/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:55:23.744191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=13", "doc_key": "7a1ccb8e2169e48cd18d6e9f93275ee1"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ab7c71203868e1239f00995b606a79deef0999499d452640db4be5526d21b538'),
  ('cpiuris2025::ddb6d9d8c12916ccd43af495fb5a0090', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Indulto e Graça nos Crimes Hediondos', '## Indulto e Graça nos Crimes Hediondos

O indulto e a graça são vedados aos crimes hediondos, de acordo com o entendimento do STF, que interpreta a Constituição extensivamente.

### Conceitos
- **Indulto**: Clemência concedida a um grupo indeterminado de indivíduos
- **Graça**: Chamado "indulto individual"
- **Crimes hediondos**: Prática da tortura, tráfico ilícito de entorpecentes e drogas afins e terrorismo
- **Anistia**: Concessão de liberdade a um indivíduo sem punição
- **Comutação de pena**: Diminuição ou indulto parcial da pena

### Referências legais
- Art. 2º, I, da Lei n.º 8.072/1990

### Jurisprudência
- Súmula 697 do STF

### Dicas de prova
- Entenda o conceito de indulto e graça nos crimes hediondos
- Conheça a lista de crimes hediondos e seus equiparados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, I, da Lei n.º 8.072/1990"], "jurisprudence": ["Súmula 697 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T17:55:44.801904+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=14", "doc_key": "ddb6d9d8c12916ccd43af495fb5a0090"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3d93158ab08f88ca098fbfe31b6fd3a97c3534feb1b046b8213f5c27b07aeb96'),
  ('cpiuris2025::847fb01e594787ec9efc6c92228ffc62', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes Hediondos', '## Crimes Hediondos

O rol dos crimes hediondos é fechado e não admite interpretação extensiva, sendo considerados os crimes tipificados no Código Penal consumados ou tentados.

### Conceitos
- **Crime Hediondo**: Pessoa que cometeu um crime típico de dano à sociedade
- **Código Penal**: Lei que regula os crimes e penalidades
- **Consumado ou Tentado**: O crime foi completado ou não

### Referências legais
- Art. 1º da Lei n.º 8.072/1990

### Dicas de prova
- Distinção entre crimes hediondos e outros crimes
- Reconhecimento do rol fechado dos crimes hediondos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º da Lei n.º 8.072/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:56:48.660592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=14", "doc_key": "847fb01e594787ec9efc6c92228ffc62"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b25c88e6d4ef2f3b4074be153d8381824e90763f5aa9be749fc26639f503e96a'),
  ('cpiuris2025::50708d8463cd995ce11bb90b7791ce12', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Proteção contra autoridades e familiares', '## Proteção contra autoridades e familiares

Art. 129, § 2º: Proteção contra autoridades e familiares em casos de lesão corporal ou à saúde.

### Conceitos
- **Lesão Corporal**: Dano físico a outrem
- **Proteção Legal**: Direito que assegura proteção contra danos

### Referências legais
- Art. 129, § 2º do Código Penal

### Dicas de prova
- Distinção entre lesão corporal e saúde
- Importância da proteção legal em casos de autoridade ou familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 129, § 2º do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:57:04.085144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=15", "doc_key": "50708d8463cd995ce11bb90b7791ce12"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3723a569623d948af8d4c30abcd25881419c019c09d60d1eca7b355de188b7cd'),
  ('cpiuris2025::84b084649b66f5dd15ede22d3b57356a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Homicídio e Lesões Corporais Hediondas', '## Homicídio e Lesões Corporais Hediondas

O homicídio simples é hediondo apenas quando praticado em atividade típica de grupo de extermínio. Além disso, o crime de homicídio qualificado é sempre considerado hediondo. As lesões corporais dolosas de natureza gravíssima e seguidas de morte contra autoridades ou parentes consanguíneos também são hediondas.

### Conceitos
- **Homicídio**: ato que resulta na morte de outra pessoa
- **Lesão Corporal Dolosa**: lesão causada por ação ou omissão criminosa
- **Gravíssima**: de grande intensidade ou severidade
- **Hediondo**: considerado hediondo pela lei, devido à sua natureza repugnante
- **Atividade Típica de Grupo de Extermínio**: atividade caracterizada por um grupo de pessoas que cometem crimes em conjunto

### Referências legais
- Art. 121, caput do CP; Art. 121, § 6º, CP; Art. 129, §2º e §3º; Lei nº 14.994, de 2024

### Dicas de prova
- Entenda a noção de ''atividade típica de grupo de extermínio'' e como ela afeta a classificação do homicídio como hediondo.
- Conheça as diferenças entre o homicídio simples, qualificado e hediondo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 121, caput do CP; Art. 121, § 6º, CP; Art. 129, §2º e §3º; Lei nº 14.994, de 2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T17:58:24.714792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=15", "doc_key": "84b084649b66f5dd15ede22d3b57356a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '19c504e2a37a71bb449176d1b30b0f3c0b39c0e4f57c9c59eab9f456bb7f120f'),
  ('cpiuris2025::23674f2f80a5bc8b9cb99c0493ce01bc', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime Hediondo e Segurança Pública', '## Crime Hediondo e Segurança Pública

A lei estabelece que os crimes hediondos são aqueles que resultam em lesão corporal grave ou morte, especialmente quando cometidos por agentes de segurança pública. A segurança pública é um dever do Estado, direito e responsabilidade de todos, exercida através de vários órgãos.

### Conceitos
- **Crime Hediondo**: Lesão corporal grave ou morte resultante de crime cometido por agente de segurança pública
- **Segurança Pública**: Derever do Estado, direito e responsabilidade de todos, exercida para preservação da ordem pública e incolumidade das pessoas e do patrimônio
- **Lesão Corporal Grave**: Lesão que resulta em perda ou inutilização do membro, sentido ou função
- **Morte**: Falecimento de uma pessoa

### Referências legais
- Art. 142 da CF/88
- Art. 144 da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de segurança pública e seus órgãos
- Conheça os crimes hediondos e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.16", "page_number": 16, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 142 da CF/88", "Art. 144 da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T17:59:27.368967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=16", "doc_key": "23674f2f80a5bc8b9cb99c0493ce01bc"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c43cfe61607d34084ee008fb2aca16547d8c03eb4bfa56e6bc8e68bfa59d985c'),
  ('cpiuris2025::71379f81767479e056753e9d321acdff', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes Hediondos', '## Crimes Hediondos

Resumo do artigo 157 e 159 do Código Penal, destacando as alterações promovidas pelo Pacote Anticrime.

### Conceitos
- **Feminicídio**: Crime autônomo previsto no art. 121-A do Código Penal
- **Roubo**: Crimes hediondos considerados em decorrência da Lei n.º 8.072/1990
- **Extorsão**: Crimes hediondos considerados em decorrência da Lei n.º 8.072/1990
- **Sequestro**: Crime hediondo previsto no art. 159 do Código Penal

