- Art. 157, § 2º-A, inciso I, do CP; Art. 157, § 3º, do CP; Art. 158, § 3º, do CP; Art. 159, caput e §§ 1º, 2º e 3º

### Jurisprudência
- RE 123456
- Tema repetitivo: Crimes Hediondos

