  ('cpiuris2025::87566852cf05cf11440e491e7a0b8516', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Estupro e Estupro de Vulnerável', '## Estupro e Estupro de Vulnerável

O artigo 213 do Código Penal estabelece que o estupro é considerado hediondo, com pena de reclusão de 6 a 10 anos. Além disso, o artigo 217-A estabelece que o estupro de vulnerável é considerado hediondo, com pena de reclusão de 8 a 15 anos.

### Conceitos
- **Hediondo**: Crime que tem natureza de horror e repulsa social
- **Estupro**: Constranger alguém a ter conjunção carnal ou praticar outro ato libidinoso
- **Vulnerável**: Pessoa menor de 14 anos ou com deficiência mental que não pode oferecer resistência
- **Consentimento**: Não é necessário para a punibilidade do crime

### Referências legais
- Art. 213, caput e §§ 1º e 2º, Código Penal; Art. 217-A, CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre estupro e estupro de vulnerável
- Importância do consentimento na punibilidade do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.18", "page_number": 18, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 213, caput e §§ 1º e 2º, Código Penal; Art. 217-A, CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:00:49.938164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=18", "doc_key": "87566852cf05cf11440e491e7a0b8516"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ead7b6bbf735f1c8ec20652798578b1f48f3ea33e2ebd4dd4c26093c43f507b5'),
  ('cpiuris2025::546a341f9e4e5223e193ea5ce03f2731', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Exploração sexual de criança ou adolescente', '## Exploração sexual de criança ou adolescente

Pena para favorecimento da prostituição ou exploração sexual de vulneráveis, com reclusão de 4 a 10 anos.

### Conceitos
- **Vulnerável**: Pessoa com deficiência ou enfermidade que não tem o necessário discernimento para a prática do ato
- **Conjunção carnal**: Ato libidinoso entre pessoas de idade diferente

### Referências legais
- Art. 218-B, caput e §§ 1º e 2º do Código Penal

### Dicas de prova
- Distinção entre exploração sexual e consentimento
- Importância da idade mínima de 14 anos para a aplicação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 218-B, caput e §§ 1º e 2º do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:01:21.512478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=19", "doc_key": "546a341f9e4e5223e193ea5ce03f2731"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'affe40a34f33b4ad4f87504354c546fdc0e5d5c8200f81a9ebba90e795934ab8'),
  ('cpiuris2025::088e61d5eb04bb535c63e554aa924455', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Falsificação, Corrupção, Adulteração ou Alteração de Produto Destinado a Fins Terapêuticos ou Medicinais', '## Falsificação, Corrupção, Adulteração ou Alteração de Produto Destinado a Fins Terapêuticos ou Medicinais

Art. 273 do Código Penal estabelece pena de reclusão de 10 a 15 anos e multa para falsificar, corromper, adulterar ou alterar produto destinado a fins terapêuticos ou medicinais.

### Conceitos
- **Falsificação**: Ação de criar ou modificar um produto para fazer com que pareça ser outro
- **Corrupção**: Ação de alterar a natureza de um produto para torná-lo mais valioso
- **Adulteração**: Ação de misturar algo com outro material sem autorização
- **Alteração**: Mudança feita em um produto sem autorização
- **Produto destinado a fins terapêuticos ou medicinais**: Substância ou medicamento projetado para tratar uma doença ou condição médica
- **Código Penal**: Lei que estabelece as regras para a punição dos crimes no Brasil

### Referências legais
- Art. 273 do Código Penal
- Lei nº 8.072/1990

### Jurisprudência
- RE 979962/RS, j. 24/03/2021

### Dicas de prova
- Entenda a definição de falsificação e como ela se relaciona com o artigo em questão
- Conheça as diferentes formas de alteração de produto destinado a fins terapêuticos ou medicinais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 273 do Código Penal", "Lei nº 8.072/1990"], "jurisprudence": ["RE 979962/RS, j. 24/03/2021"], "confidence": 0.8, "extracted_at": "2026-05-31T18:02:33.626239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=19", "doc_key": "088e61d5eb04bb535c63e554aa924455"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '2bab46d906929aed32259e28f94cd31e84e862470e29416ea9941a4c101aec09'),
  ('cpiuris2025::e7092c0ad5d63893c3f006655cb6238c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes Hediondos e Regime Inicial', '## Crimes Hediondos e Regime Inicial

Resumo do texto sobre crimes hediondos, regime inicial e alterações legais.

### Conceitos
- **Crime Hediondo**: Pena mais leve para certos crimes
- **Regime Inicial**: Pena cumprida em regime fechado ou diverso
- **Anistia**: Imunidade a punição por crime hediondo
- **Fiança**: Não cumprimento da pena por crime hediondo

### Referências legais
- Art. 2º da Lei n.º 8.072/1990

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de crime hediondo e regime inicial
- Conheça as alterações legais recentes nos crimes hediondos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei n.º 8.072/1990"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:03:03.715886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=21", "doc_key": "e7092c0ad5d63893c3f006655cb6238c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6bd07a814a393bf4389cfc175e0572f86d64cdc5115195e3177760580f91ac16'),
  ('cpiuris2025::230419839786fd736cea2809067ac8e3', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes Hediondos', '## Crimes Hediondos

Lei que define crimes hediondos, incluindo furto qualificado com explosivos, induzimento a suicídio ou automutilação e sequestro de menores.

### Conceitos
- **Furto Qualificado**: Uso de explosivos ou artefatos análogos para causar perigo comum
- **Induzimento a Suicídio**: Apoio, incentivo ou facilitação de suicídio por meio de tecnologia
- **Sequestro de Menor**: Cárcere privado de menor de 18 anos
- **Tráfico de Pessoas**: Comércio ilegal de crianças ou adolescentes

### Referências legais
- Art. 1º, Lei n.º 8.072/90
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Pacote Anticrime

### Dicas de prova
- Entenda a definição de crimes hediondos e seus exemplos
- Conheça as novas inclusões na Lei dos Crimes Hediondos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.20", "page_number": 20, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, Lei n.º 8.072/90", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Pacote Anticrime"], "confidence": 0.8, "extracted_at": "2026-05-31T18:03:16.939832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=20", "doc_key": "230419839786fd736cea2809067ac8e3"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e22ff4aca51803c3415527bd54fe044b0eec8aa68d059baa60585c2469f50e53'),
  ('cpiuris2025::e57c0f8dc61c398def280ac1379b8d88', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Progressão de Regime', '## Progressão de Regime

A progressão de regime não é motivada pela opinião do julgador sobre a gravidade em abstrato do crime. A Lei Anticrime revogou o § 2º do artigo 2º da Lei dos Crimes Hediondos.

### Conceitos
- **Progressão de Regime**: Mecanismo que permite ao condenado cumprir pena em regime aberto após um período determinado
- **Pacote Anticrime**: Lei que revogou o § 2º do artigo 2º da Lei dos Crimes Hediondos
- **Lei dos Crimes Hediondos**: Lei que estabelece penas mais severas para certos crimes
- **Apenado**: Pessoa condenada por um crime

### Referências legais
- Art. 2º, § 2º, Lei n.º 8.072/90

### Jurisprudência
- Súmula 718/STF

### Dicas de prova
- Entenda a diferença entre opinião do julgador e motivação idônea para regime mais severo
- Conheça o Pacote Anticrime e sua relação com a Lei dos Crimes Hediondos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, § 2º, Lei n.º 8.072/90"], "jurisprudence": ["Súmula 718/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T18:04:51.150786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=21", "doc_key": "e57c0f8dc61c398def280ac1379b8d88"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '00cd2a85da60a3cc82e4f85a32077818f9fa91b57d54b23b45a1ac44440dc6ea'),
  ('cpiuris2025::58fd034384588515bd2b92ea4db4c6e2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Progressão no regime de cumprimento da pena', '## Progressão no regime de cumprimento da pena

Regras para progressão do preso, incluindo requisitos e exceções.

### Conceitos
- **Progressão no regime**: Mudança do regime de cumprimento da pena
- **Benefício previsto no § 3º**: Concessão de progressão para preso com bom comportamento carcerário
- **Falta grave**: Comportamento inadequado que pode ser punido com multa ou perda de direitos
- **Hediondo**: Crime considerado grave e punível com pena mais severa

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

