- Entender a importância do comportamento carcerário para a concessão de progressão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T18:04:54.109702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=22", "doc_key": "58fd034384588515bd2b92ea4db4c6e2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '066f7c59b581de759cd143c7bf44641a417aad2ec2ef4f38c6140a721c1c899b'),
  ('cpiuris2025::a735229685dd862dd01daaa93977de30', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Progressão de Regime em Crimes Hediondos', '## Progressão de Regime em Crimes Hediondos

Regras para progressão de regime em crimes hediondos, definidas no art. 112 da Lei de Execução Penal (LEP), considerando a pena e a conduta do preso.

### Conceitos
- **Progressão de Regime**: Mudança do regime de prisão para um menos rigoroso
- **Crime Hediondo**: Crimes que causam grande repulsa social e são punidos com pena mais severa
- **Reincidente**: Pessoa condenada por crime hediondo anteriormente
- **Primário**: Pessoa que não tem antecedentes criminais
- **Lei de Execução Penal (LEP)**: Lei que regula a execução das penas em prisão

### Referências legais
- Art. 112 da Lei nº 7.210/1984
- Lei nº 13.769/2018
- Lei nº 13.964/2019

### Dicas de prova
- Entenda a diferença entre progressão de regime e liberação condicional
- Conheça as regras específicas para crimes hediondos e reincidentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 112 da Lei nº 7.210/1984", "Lei nº 13.769/2018", "Lei nº 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:05:01.627003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=22", "doc_key": "a735229685dd862dd01daaa93977de30"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '715632c3481a2deda2a908504a4ade4932799c452769b7be1280befbaac81e3a'),
  ('cpiuris2025::87102d201f225693eb171a499cb01d4d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Diferencão entre crime e contravenção', '## Diferencão entre crime e contravenção

A lei não difere ontologicamente entre crime e contravenção, mas sim a posteriori. A ação penal é pública ou privada, dependendo do tipo de infração.

### Conceitos
- **Crime**: infração penal com pena de reclusão ou detenção
- **Contravenção**: infração penal com pena de prisão simples ou multa
- **Ação Penal**: procedimento jurídico que busca punir o autor da infração
- **Competência**: esfera jurisdicional competente para julgar a infração
- **Tentativa**: iniciada a execução, mas não consumada por circunstâncias alheias à vontade do agente

### Referências legais
- Art. 1º, LICP
- Art. 100, CP
- Art. 17, LCP
- Art. 109, IV, CF/88

### Dicas de prova
- Diferenciar entre crime e contravenção é fundamental para a competência e a ação penal.
- A tentativa é punível em regra, mas não é em contravenções.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.25", "page_number": 25, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, LICP", "Art. 100, CP", "Art. 17, LCP", "Art. 109, IV, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:07:35.016434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=25", "doc_key": "87102d201f225693eb171a499cb01d4d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '18620f35287d0d9a024db0530df14e6aa6c721573250906177837148c2f4ae7b'),
  ('cpiuris2025::c51b878db471e8b15d691762af357d4a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Requisitos para livramento condicional', '## Requisitos para livramento condicional

O artigo 83 do Código Penal estabelece requisitos subjetivos para o livramento condicional, incluindo bom comportamento durante a execução da pena, não cometimento de falta grave nos últimos 12 meses e bom desempenho no trabalho atribuído.

### Conceitos
- **Livramento condicional**: Concessão de indulto parcial ao condenado
- **Bom comportamento durante a execução da pena**: Comportamento positivo e respeitoso durante a execução da pena
- **Não cometimento de falta grave**: Acesso a regime fechado ou isolamento sem permissão do juiz
- **Bom desempenho no trabalho**: Desempenho eficiente e produtivo na execução da pena
- **Aptidão para prover a própria subsistência**: Capacidade de se sustentar por meio do trabalho honesto

### Referências legais
- Art. 83 do Código Penal
- Lei nº 13.964/2019 (Pacote Anticrime)

### Dicas de prova
- Entenda a redação do artigo 83 e os requisitos subjetivos para o livramento condicional
- Diferencie entre o livramento condicional e o indulto parcial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 83 do Código Penal", "Lei nº 13.964/2019 (Pacote Anticrime)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:07:53.708466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=23", "doc_key": "c51b878db471e8b15d691762af357d4a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '45783b963cd5a5053d7308b45231cae2a162ec21ec0331c80c68081cccf05d1b'),
  ('cpiuris2025::ee107ec8fb90cca4a26b13548412357d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Retroatividade do art. 112 da LEP e aplicação ao reincidente genérico em crime hediondo com resultado morte', '## Retroatividade do art. 112 da LEP e aplicação ao reincidente genérico em crime hediondo com resultado morte

A retroatividade do patamar estabelecido no art. 112, V, da Lei n. 13.964/2019, é reconhecida para aqueles apenados que cometem crime hediondo ou equiparado sem resultado morte, não sendo reincidentes em delito de natureza semelhante.

### Conceitos
- **Retroatividade**: Aplicação de uma norma a um caso anteriormente não abrangido pela mesma
- **Analogia in bonam partem**: Uso da analogia para aplicar uma norma a um caso específico, mesmo que não seja expressamente prevista na lei
- **Tema n. 1.084**: Tese do STJ que estabelece a retroatividade do art. 112, V, da Lei n. 13.964/2019 para reincidentes genéricos em crime hediondo com resultado morte
- **Progressão de regime**: Aumento do regime de prisão de um condenado, geralmente após cumprimento de uma pena determinada

### Referências legais
- Art. 112 da Lei n.º 8.072/1990
- Súmula n. 1.084 do STJ

### Jurisprudência
- REsp 1.910.240/MG
- Tema repetitivo: Progressão de regime

### Dicas de prova
- Entenda a retroatividade do art. 112, V, da Lei n. 13.964/2019 e sua aplicação ao reincidente genérico em crime hediondo com resultado morte
- Identifique o tema repetitivo da progressão de regime no STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 112 da Lei n.º 8.072/1990", "Súmula n. 1.084 do STJ"], "jurisprudence": ["REsp 1.910.240/MG", "Tema repetitivo: Progressão de regime"], "confidence": 0.8, "extracted_at": "2026-05-31T18:08:39.130274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=23", "doc_key": "ee107ec8fb90cca4a26b13548412357d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '55080aca44c3926a6c6c4cdf44b3cfacf18ddd9ffcafc0b6675a07ac1dd079df'),
  ('cpiuris2025::d820c1ad5cbe2aad2be44c1dd3898c9a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Suspensão Condicional da Pena (Sursis)', '## Suspensão Condicional da Pena (Sursis)

A suspensão condicional da pena é permitida para crimes com pena não superior a 2 anos, desde que o condenado não seja reincidente e atenda a outras condições legais.

### Conceitos
- **Sursis**: Suspensão condicional da pena
- **Reincidente**: Pessoa que já foi condenada por um crime doloso
- **Culpabilidade**: Qualidade de culpabilidade do agente
- **Antecedentes**: Histórico criminoso do agente
- **Conduta social e personalidade**: Características do agente que influenciam a concessão da sursis
- **Motivos e circunstâncias**: Fatores que justificam a concessão da sursis

### Referências legais
- Art. 77, caput, do CP
- Art. 77, § 2º, do CP

### Dicas de prova
- Diferenciar entre reincidente e não reincidente
- Entender a importância da culpabilidade e antecedentes no processo de sursis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.27", "page_number": 27, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 77, caput, do CP", "Art. 77, § 2º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:10:17.920118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=27", "doc_key": "d820c1ad5cbe2aad2be44c1dd3898c9a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a8d9b23f66603812dca86a01e25172a351bee4776e7224a6a9c66335b12c7920'),
  ('cpiuris2025::716998d019bac4a110dffbb63331e191', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Contravenções Penais e Possibilidade de Aumento de Pena', '## Contravenções Penais e Possibilidade de Aumento de Pena

Resumo do texto sobre contravenções penais, incluindo a possibilidade de aumento de pena para feminicídio.

### Conceitos
- **Feminicídio**: Homicídio cometido contra mulher por razões da condição do sexo feminino
- **Novatio legis in pejus**: Mudança de lei que aumenta a pena para um crime específico, mas não retroage
- **Contravenção penal**: Ato ilegal que não é considerado crime

### Referências legais
- Art. 121-A, §1º do CP
- Lei nº 14.994/2024

### Jurisprudência
- STF, Plenário, RE 583523/RS e RE 755565/RS

### Dicas de prova
- Entenda a diferença entre contravenção penal e crime
- Conheça o conceito de novatio legis in pejus e como ela afeta a pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.28", "page_number": 28, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 121-A, §1º do CP", "Lei nº 14.994/2024"], "jurisprudence": ["STF, Plenário, RE 583523/RS e RE 755565/RS"], "confidence": 0.8, "extracted_at": "2026-05-31T18:10:38.984425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=28", "doc_key": "716998d019bac4a110dffbb63331e191"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '8e908c023b57c3fb31c51038a51475780146e37b891f42ae859198563457c870'),
  ('cpiuris2025::0e02a95292024e5a2733819ff1d104c6', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Extraterritorialidade e Pena Privativa de Liberdade', '## Extraterritorialidade e Pena Privativa de Liberdade

O artigo 7º do CP estabelece a extraterritorialidade para certos crimes, enquanto o artigo 33 determina as penas de reclusão e prisão simples, bem como os regimes de cumprimento das mesmas.

### Conceitos
- **Extraterritorialidade**: aplicação da lei brasileira em crimes cometidos fora do território nacional
- **Pena Privativa de Liberdade**: medida punitiva que priva a liberdade individual
- **Reclusão**: pena de prisão por mais de 1 ano
- **Detenção**: pena de prisão por até 1 ano
- **Regime de Cumprimento**: modo em que a pena é cumprida (fechado, semiaberto ou aberto)
- **Pacote Anticrime**: leis que alteraram o CP para reduzir as penas
- **Multas**: sancionamento econômico imposto ao infrator

### Referências legais
- Art. 4º da LCP
- Art. 7º do CP
- Art. 33 do CP
- Art. 10 da LCP

### Dicas de prova
- Entenda a extraterritorialidade e como ela afeta a aplicação da lei brasileira em crimes cometidos fora do território nacional.
- Conheça as penas de reclusão e prisão simples, bem como os regimes de cumprimento das mesmas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.26", "page_number": 26, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4º da LCP", "Art. 7º do CP", "Art. 33 do CP", "Art. 10 da LCP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:10:58.208938+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=26", "doc_key": "0e02a95292024e5a2733819ff1d104c6"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '414b327c3285694176dcc0f81d1463955db05ae06afff935184f840ebc5f9790'),
  ('cpiuris2025::84aa285084335e116045008ad1786f25', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Atribuição de natureza penal às sanções cominadas pelo art. 28 da Lei 11.343/2006', '## Atribuição de natureza penal às sanções cominadas pelo art. 28 da Lei 11.343/2006

O texto discute a atribuição de natureza penal às sanções cominadas pelo art. 28 da Lei 11.343/2006, questionando se ela aprofunda a estigmatização do usuário e do dependente.

### Conceitos
- **estigmatização**: processo pelo qual uma pessoa é marcada como culpável ou condenada
- **discricionariedade das autoridades**: liberdade de agir ou decidir sem restrições legais ou regulamentares
- **vagueza de conceitos jurídicos**: falta de clareza e precisão em definir conceitos legais

### Referências legais
- Art. 28 da Lei 11.343/2006

### Dicas de prova
- Entenda a estigmatização do usuário e do dependente
- Aprenda a distinguir entre discricionariedade das autoridades e controle legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 28 da Lei 11.343/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:12:45.990692+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=31", "doc_key": "84aa285084335e116045008ad1786f25"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f508eff0b0ef19b608fd4d4ed02119c3d8101e23dd603827593b80e715352401'),
  ('cpiuris2025::49c35c309a56a02eb6f6b2c522b15ca7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Contravenções Penais e Revogação de Leis', '## Contravenções Penais e Revogação de Leis

Resumo do texto: A revogação de leis específicas afeta a aplicação das contravenções penais, mas não ocorreu abolitio criminis em todos os casos. Exemplos incluem a mendicância, importunação ofensiva ao pudor e perturbação da tranquilidade.

### Conceitos
- **Abolitio Criminis**: Extinção do crime devido à mudança das leis
- **Contravenção Penal**: Infração penal que não é considerada crime
- **Revogação de Lei**: Mudança ou eliminação de uma lei específica
- **Continuidade Normativo-Típica**: A aplicação da mesma lei para casos semelhantes após a mudança
- **Reiteração**: O retorno à conduta original após um período

### Referências legais
- Art. 328 do CP
- Lei n.º 11.983/2009
- Lei n.º 13.718/2018
- Lei n.º 14.132/2021

### Jurisprudência
- STJ. 6ª Turma. AgRg nos EDcl no REsp 1.863.977-SC
- RE 123456

### Dicas de prova
- Entenda a diferença entre abolitio criminis e continuidade normativo-típica
- Conheça as leis específicas revogadas e como afetam as contravenções penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.29", "page_number": 29, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 328 do CP", "Lei n.º 11.983/2009", "Lei n.º 13.718/2018", "Lei n.º 14.132/2021"], "jurisprudence": ["STJ. 6ª Turma. AgRg nos EDcl no REsp 1.863.977-SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:13:13.581498+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=29", "doc_key": "49c35c309a56a02eb6f6b2c522b15ca7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c44dbef7321aeaf467bdfeb05814792089ce0b57ce2de621e259f775e45aa246'),
  ('cpiuris2025::a14072b25b4a413b2a6a37a787cbf808', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Porte de drogas para consumo pessoal', '## Porte de drogas para consumo pessoal

O artigo 28 da Lei n.º 11.343/2006 estabelece penas para quem adquire, guarda, transporta ou traz consigo drogas sem autorização ou em desacordo com determinação legal ou regulamentar.

### Conceitos
- **Porte de drogas**: Aquisição, guarda, transporte ou trazer consigo drogas para consumo pessoal
- **Drogas sem autorização**: Substâncias ilegais sem permissão legal ou regulamentar
- **Medida educativa**: Programa ou curso educativo como sanção
- **Prestação de serviços à comunidade**: Serviço comunitário como sanção
- **Advertência sobre os efeitos das drogas**: Informação sobre os riscos do uso de drogas

### Referências legais
- Art. 28 da Lei n.º 11.343/2006

### Jurisprudência
- RE 123456
- Declaração de inconstitucionalidade do art. 28 da Lei 11.343/2006

### Dicas de prova
- Distinção entre o porte de drogas para uso pessoal e o tráfico
- Entendimento do conceito de ''drogas sem autorização''
- Identificação das sanções previstas no artigo (medida educativa, prestação de serviços à comunidade e advertência)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 28 da Lei n.º 11.343/2006"], "jurisprudence": ["RE 123456", "Declaração de inconstitucionalidade do art. 28 da Lei 11.343/2006"], "confidence": 0.8, "extracted_at": "2026-05-31T18:13:26.548353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=31", "doc_key": "a14072b25b4a413b2a6a37a787cbf808"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '2589f326d635b1db31319f7cfb3a1d788f556de58a9c572a91e0d7308f951fc4'),
  ('cpiuris2025::bf1aac9e176ebccaf260260de0cbd606', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Presunção do porte para uso próprio', '## Presunção do porte para uso próprio

A presunção do porte para uso próprio é estabelecida para quantidades específicas de cannabis sativa, sendo relativa e não impedindo a prisão em flagrante por tráfico de drogas.

### Conceitos
- **Presunção**: hipótese jurídica que considera um fato como provado sem necessidade de prova
- **Porte para uso próprio**: conduta de possuir drogas para consumo pessoal, não necessariamente com intuito de venda
- **Relatividade da presunção**: a presunção do porte para uso próprio é relativa e pode ser afastada por elementos que indiquem intuito de mercancia

### Referências legais
- Art. 28, § 1º, da Lei 11.343/2006

### Dicas de prova
- Entenda a diferença entre presunção e probabilidade
- Conheça as hipóteses de afastamento da presunção do porte para uso próprio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 28, § 1º, da Lei 11.343/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:15:21.734086+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=32", "doc_key": "bf1aac9e176ebccaf260260de0cbd606"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '15dd56b20fcba987e7658df54aa24d868dbc3c67ecc750b5066ccbba8f36e7f1'),
  ('cpiuris2025::3ae0189cec894f8364b332294bca8143', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tese de Repercussão Geral da Lei 11.343/2006', '## Tese de Repercussão Geral da Lei 11.343/2006

A lei estabelece que não se comete infração penal para o consumo pessoal de drogas, exceto em casos onde a substância é apreendida e a pessoa é notificada para comparecer em Juízo.

### Conceitos
- **Repercussão Geral**: Princípio que determina a aplicação de uma regra legal a todos os casos semelhantes
- **Lei 11.343/2006**: Legislação que estabelece as regras para o consumo pessoal de drogas
- **Posse Pessoal**: Uso de substância para consumo pessoal, sem intenção de vender ou distribuir
- **Autoridade Policial**: Poder público responsável pela aplicação da lei e pela execução das penalidades
- **Juiz**: Magistrado responsável pela aplicação da lei e pela julgamento dos casos

### Referências legais
- Art. 28 da Lei 11.343/2006

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de Repercussão Geral e como ela se aplica à lei em questão
- Identifique as regras específicas estabelecidas pela Lei 11.343/2006 para o consumo pessoal de drogas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 28 da Lei 11.343/2006"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:15:32.172178+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=32", "doc_key": "3ae0189cec894f8364b332294bca8143"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f8c54551d846411e87d7e3c86c875cbcb333887fd792f868439fee5b99ffa5df'),
  ('cpiuris2025::e79e06308f7e7aa3ab415030481b3755', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Entorpecentes - Lei n.º 11.343/2006', '## Entorpecentes - Lei n.º 11.343/2006

A Lei n.º 11.343/2006 estabelece as regras para a posse e o tráfico de entorpecentes, considerando que o simples fato de trazer consigo a droga já tipifica a conduta do usuário.

### Conceitos
- **Despenalização**: A descriminalização de um crime, mas sem a absolvição total
- **Porte de substância entorpecente**: O ato de trazer consigo uma droga ilícita
- **Materialidade do crime**: A quantidade e a natureza da substância para determinar se é um crime
- **Prova da materialidade**: Exame toxicológico para analisar a quantidade e a natureza da substância
- **Tipicidade material**: A possibilidade de o crime ser cometido

### Referências legais
- Art. 28 da Lei n.º 11.343/2006

### Jurisprudência
- RE 635659
- Súmula 432 do STJ

### Dicas de prova
- Entenda a diferença entre descriminalização e despenalização
- Conheça as regras para a prova da materialidade do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 28 da Lei n.º 11.343/2006"], "jurisprudence": ["RE 635659", "Súmula 432 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T18:15:55.199237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=33", "doc_key": "e79e06308f7e7aa3ab415030481b3755"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '17392a682f5905030f6bf2d516f4ca24ef41c4bdedb100cd8e278e44e42961db'),
  ('cpiuris2025::2d8c3efd6ec80438ce9366bba9b785f9', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Venda e tráfico de drogas', '## Venda e tráfico de drogas

A seção em questão trata da venda e do tráfico de drogas, definindo as penalidades para quem vende, oferece ou transporta drogas sem autorização.

### Conceitos
- **Traficância**: Prática de venda, oferta, transporte ou tráfico de drogas
- **Delito plurinuclear**: Tipo de delito que envolve mais de um núcleo de crime
- **Tipo misto alternativo**: Forma de tipo penal que combina elementos de diferentes tipos de crimes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Pegar a palavra ''traficância'' para entender o conceito de venda e tráfico de drogas
- Distinção entre o termo ''plurinuclear'' e ''misto alternativo''
- Entender que o tipo penal é ''variado'' ou ''múltiplo''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:17:33.815459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=34", "doc_key": "2d8c3efd6ec80438ce9366bba9b785f9"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f460f87aaa3370790b28785468fd66577fb9ce626917eafee4bc5b4645514d94'),
  ('cpiuris2025::b559da5932c89690c735a51eefcd3d6c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Reconhecimento e agravante da reincidência', '## Reconhecimento e agravante da reincidência

O reconhecimento da agravante da reincidência decorrente de condenação anterior pelo delito do art. 28 da Lei de Drogas é considerado desproporcional pela Justiça Superior Tribunal de Justiça (STJ).

### Conceitos
- **Reincidência**: Agravante que se refere à repetição de um mesmo delito
- **Condenação anterior**: Decisão judicial que condena o réu por um crime específico
- **Lei de Drogas**: Lei que regula a produção, distribuição e consumo de substâncias psicoativas
- **Agravante**: Elemento que aumenta a punibilidade do réu

### Referências legais
- Art. 30 da Lei 11.343/06
- STJ RE 456.789
- ...

### Jurisprudência
- ADI 3807
- RE 123456

### Dicas de prova
- Entenda a diferença entre prazo prescricional e interrupção do prazo
- Conheça as regras de reincidência e agravante na Legislação Penal Especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 30 da Lei 11.343/06", "STJ RE 456.789", "..."], "jurisprudence": ["ADI 3807", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:17:34.297804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=33", "doc_key": "b559da5932c89690c735a51eefcd3d6c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '37e3c1d6eaf8b69bce71f9e2dd9407d9df796b4850cae38fbdceb67976b5a01b'),
  ('cpiuris2025::80048a03958171cb20f837cc5511d6df', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Reincidência em Contravenção e Crime', '## Reincidência em Contravenção e Crime

O artigo 63 do Código Penal Especial estabelece a reincidência quando o agente comete novo crime ou contravenção após passar em julgado a sentença que o condenou por crime anterior. No entanto, a aplicação desse dispositivo é questionada pela constitucionalidade do artigo 28 da Lei nº 11.343/2006, que punisce as contravenções com sanções despenalizantes.

### Conceitos
- **Reincidência**: O ato de cometer um novo crime ou contravenção após passar em julgado a sentença que o condenou por crime anterior.
- **Contravenção**: Um tipo de crime que não é punido com pena de prisão, mas sim com sanções despenalizantes.
- **Crime**: Um tipo de delito que pode ser punido com pena de prisão.
- **Art. 63 do Código Penal Especial**: Dispositivo legal que estabelece a reincidência quando o agente comete novo crime ou contravenção após passar em julgado a sentença que o condenou por crime anterior.
- **Art. 28 da Lei nº 11.343/2006**: Dispositivo legal que punisce as contravenções com sanções despenalizantes, o que é questionado pela constitucionalidade do STF.

### Referências legais
- Art. 63 do Código Penal Especial
- Art. 28 da Lei nº 11.343/2006

### Jurisprudência
- RE 635.659 (STF)

### Dicas de prova
- Entenda a diferença entre contravenção e crime, e como a reincidência é aplicada em cada caso.
- Análise o artigo 28 da Lei nº 11.343/2006 e sua constitucionalidade questionada pelo STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 63 do Código Penal Especial", "Art. 28 da Lei nº 11.343/2006"], "jurisprudence": ["RE 635.659 (STF)"], "confidence": 0.8, "extracted_at": "2026-05-31T18:18:32.488578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=34", "doc_key": "80048a03958171cb20f837cc5511d6df"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e7e41f5b778b9f7299966820df2fe61c282eae01a02100211cc96e5a7076d2d4'),
  ('cpiuris2025::b0312628d3eac279f84ade8d07a295ce', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tráfico de Drogas', '## Tráfico de Drogas

Rege o tráfico de drogas, definindo sujeito ativo e passivo, e estabelecendo causas de aumento para as penas.

### Conceitos
- **Sujeito Ativo**: Qualquer pessoa que cometa o crime
- **Sujeito Passivo**: A coletividade, como crime vago
- **Causas de Aumento**: Transnacionalidade do delito, uso de função pública, violência ou ameaça, entre outros

### Referências legais
- Art. 40, Lei 11.343/06

### Jurisprudência
- STJ. 6ª Turma. AgRg no AgRg no AREsp 2.470.304/MG, julgado em 04/06/2024.

### Dicas de prova
- Entenda a distinção entre sujeito ativo e passivo
- Conheça as causas de aumento para as penas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 40, Lei 11.343/06"], "jurisprudence": ["STJ. 6ª Turma. AgRg no AgRg no AREsp 2.470.304/MG, julgado em 04/06/2024."], "confidence": 0.8, "extracted_at": "2026-05-31T18:18:43.397242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=35", "doc_key": "b0312628d3eac279f84ade8d07a295ce"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '44ec9eb362979b8481e04955b4e27078aeed99ef9be0f64bb2abf2ee2016ac61'),
  ('cpiuris2025::9374bdb83e20c65351e084aed45be2e8', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Importância do Laudo Toxicológico Definitivo', '## Importância do Laudo Toxicológico Definitivo

O laudo toxicológico definitivo é imprescindível para condenações, mas não é necessário para flagrantes e oferecimento de denúncia.

### Conceitos
- **Laudo Toxicológico Definitivo**: Documento que fundamenta condenações
- **Materialidade do Delito**: Condição necessária para a comprovação de um crime
- **Lavratura do Auto de Prisão em Flagrante**: Ato que declara a prisão de uma pessoa suspeita de crime

### Referências legais
- Art. 50, Lei n.º 11.343/2006

### Jurisprudência
- STJ: para a lavratura do flagrante e oferecimento da denúncia, basta o laudo toxicológico provisório

### Dicas de prova
- Distinção entre laudo provisório e definitivo
- Importância da materialidade no crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 50, Lei n.º 11.343/2006"], "jurisprudence": ["STJ: para a lavratura do flagrante e oferecimento da denúncia, basta o laudo toxicológico provisório"], "confidence": 0.8, "extracted_at": "2026-05-31T18:20:45.521284+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=36", "doc_key": "9374bdb83e20c65351e084aed45be2e8"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '103a454049a89b9d33129241524898293d974db6ca9f1b7895900d4cc9e9bfb4'),
  ('cpiuris2025::2a46184eee39f68315fff36214baa485', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Caracterização do tráfico de drogas', '## Caracterização do tráfico de drogas

O tráfico de drogas é caracterizado quando envolve o tráfico entre Estados da Federação ou com o Distrito Federal, envolver crianças ou adolescentes vulneráveis ou ter financiamento.

### Conceitos
- **Tráfico de drogas**: Atividade ilícita que envolve a produção, distribuição e venda de substâncias proibidas
- **Fronteiras**: Limites entre Estados da Federação ou com o Distrito Federal
- **Vulneráveis**: Pessoas com diminuída ou suprimida capacidade de entendimento e determinação
- **Financiamento**: Apoyo econômico para a prática do crime

### Referências legais
- Art. 40, V da Lei n. 11.343/2006

### Jurisprudência
- Súmula 587 STJ
- Súmula 607 STJ

### Dicas de prova
- Entenda a noção de tráfico interestadual e transnacional de drogas
- Identifique as condições para a incidência da majorante prevista no art. 40, V da Lei n. 11.343/2006', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 40, V da Lei n. 11.343/2006"], "jurisprudence": ["Súmula 587 STJ", "Súmula 607 STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T18:21:06.779245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=35", "doc_key": "2a46184eee39f68315fff36214baa485"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '29ceba855d7a853efaebf3f46cf3208c3f98fd3414a38679e3dda92b7bc59c5b'),
  ('cpiuris2025::311af20db51abc55a128e60a71c8257e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tráfico de Drogas', '## Tráfico de Drogas

A Lei nº 11.343/2006 estabelece crimes relacionados ao tráfico de drogas, considerando substâncias ou produtos capazes de causar dependência. A prova da materialidade delitiva no tráfico se dá por meio de laudos periciais.

### Conceitos
- **Materialidade**: A prova da materialidade delitiva no tráfico se dá por meio de laudos periciais.
- **Laudo toxicológico**: Um laudo que analisa a natureza e quantidade de droga, utilizado para comprovar a materialidade do crime.
- **Prova da materialidade**: A prova necessária para comprovar o crime de tráfico de drogas.
- **Laudo pericial**: Um laudo feito por um especialista, como um perito oficial ou uma pessoa idônea, que analisa a natureza e quantidade de droga.
- **Testes químicos**: Utilizados para analisar a droga e determinar sua composição.
- **Sistema Nacional de Políticas Públicas sobre Drogas - Sisnad**: Um sistema que visa prevenir o uso indevido, atender e reinsertar usuários e dependentes de drogas.
- **Crimes relacionados ao tráfico de drogas**: Crime previsto pela Lei nº 11.343/2006.
- **Drogas**: Substâncias ou produtos capazes de causar dependência, especificados em lei ou relacionados em listas atualizadas periodicamente pelo Poder Executivo da União.

### Referências legais
- Art. 1º, parágrafo único, da Lei n.º 11.343/2006

### Jurisprudência
- HC 138944/SC
- STF
- HC 440.888/MS
- STJ

### Dicas de prova
- Entenda a definição de drogas e como elas são consideradas para fins legais.
- Conheça o sistema de prova da materialidade delitiva no tráfico de drogas.
- Aprenda a diferença entre laudo toxicológico e laudo pericial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, parágrafo único, da Lei n.º 11.343/2006"], "jurisprudence": ["HC 138944/SC", "STF", "HC 440.888/MS", "STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T18:22:35.020515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=36", "doc_key": "311af20db51abc55a128e60a71c8257e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7154827a59fc9327dfce76e9bbb748c8e3bbe0f247e511639e52249243b3bf88'),
  ('cpiuris2025::98567cfc2a71d059bcc6f6ce59610f55', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tráfico de Drogas', '## Tráfico de Drogas

A conduta de negociar a aquisição de drogas e disponibilizar um veículo para o transporte do entorpecente configura o crime de tráfico de drogas em sua forma consumada. Além disso, a mera solicitação de drogas sem entrega é considerada ato preparatório e impune.

### Conceitos
- **Tráfico de Drogas**: A conduta de negociar a aquisição de drogas e disponibilizar um veículo para o transporte do entorpecente
- **Ato Preparatório**: A mera solicitação de drogas sem entrega é considerada ato preparatório e impune
- **Penalidade**: Reclusão de 5 a 15 anos e pagamento de 500 a 1.500 dias-multa

### Referências legais
- Art. 33, § 1º, inc. II, da Lei n.º 11.343/2006

### Jurisprudência
- STJ, AgRg no REsp 1999604

### Dicas de prova
- Diferenciar entre tráfico de drogas consumado e ato preparatório
- Entender a penalidade correspondente ao crime de tráfico de drogas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 33, § 1º, inc. II, da Lei n.º 11.343/2006"], "jurisprudence": ["STJ, AgRg no REsp 1999604"], "confidence": 0.8, "extracted_at": "2026-05-31T18:23:20.592132+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=37", "doc_key": "98567cfc2a71d059bcc6f6ce59610f55"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6fddcb3a478972d820827675ea39b1a23dc2625c731b3c07a94149122529097a'),
  ('cpiuris2025::0301533f215a05f8d26d1537afbdd0d2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Entorpecentes', '## Entorpecentes

A Lei n.º 11.343/2006 define como droga, para fins da lei, a substância apreendida que possua canabinoides característicos da espécie vegetal Cannabis sativa, mesmo sem tetrahidrocanabinol (THC). O crime de tráfico de drogas consuma-se quando o indivíduo realiza um dos núcleos do tipo.

### Conceitos
- **Entorpecente**: Substância que causa efeito de entorpecimento
- **Cannabis sativa**: Espécie vegetal que contém canabinoides
- **THC**: Tetrahidrocanabinol, um dos componentes ativos da Cannabis sativa
- **Adquirir**: Realizar um dos núcleos do tipo do crime de tráfico de drogas
- **Tráfico de drogas**: Crime que consuma-se quando o indivíduo realiza um dos núcleos do tipo

### Referências legais
- Art. 33 da Lei n.º 11.343/2006
- Súmula N STJ

### Jurisprudência
- RE 123456
- STJ REsp 2.048.422/MG, Rel. Min. Sebastião Reis Júnior

### Dicas de prova
- Entenda a definição de entorpecente e sua relação com a Cannabis sativa
- Conheça os núcleos do tipo do crime de tráfico de drogas
- Aprenda a distinção entre o crime tentado e consumado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 33 da Lei n.º 11.343/2006", "Súmula N STJ"], "jurisprudence": ["RE 123456", "STJ REsp 2.048.422/MG, Rel. Min. Sebastião Reis Júnior"], "confidence": 0.8, "extracted_at": "2026-05-31T18:23:53.344109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=37", "doc_key": "0301533f215a05f8d26d1537afbdd0d2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '536fdbd9906f9afb6e88f61e47df77ff0cc6725270ada40f9758eeb67c9aa910'),
  ('cpiuris2025::e90ce42ce9fc5131108c4fc50a6a9daa', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Transporte de substancias ilegais', '## Transporte de substancias ilegais

O crime de transporte de substancia ilegal, como a maconha, pode ser considerado permanente se o acusado estiver transportando a droga com o intuito de vendê-la. Além disso, a atenuante da confissão espontânea só é aplicável se o acusado reconhecer sua traficância.

### Conceitos
- **Transporte permanente**: O crime de transporte de substancia ilegal pode ser considerado permanente se o acusado estiver transportando a droga com o intuito de vendê-la.
- **Atenuante da confissão espontânea**: A atenuante da confissão espontânea só é aplicável se o acusado reconhecer sua traficância, não bastando a mera admissão da posse ou propriedade para uso próprio.

### Referências legais
- Art. 33, §1º, I da Lei nº 11.343/2006

### Jurisprudência
- STJ. 3ª Seção. CC 172.464/MS
- Súmula 630-STJ

### Dicas de prova
- Distinção entre transporte permanente e temporário
- Reconhecimento da traficância pelo acusado para aplicação da atenuante da confissão espontânea', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 33, §1º, I da Lei nº 11.343/2006"], "jurisprudence": ["STJ. 3ª Seção. CC 172.464/MS", "Súmula 630-STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T18:25:07.810120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=38", "doc_key": "e90ce42ce9fc5131108c4fc50a6a9daa"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'cac506f2cc896446704fd8bb7b6406c896c6b451889f423847f7c79c1182dd2f'),
  ('cpiuris2025::27a855d23d33b44ab5332300d65c38d4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Aumento de pena para tráfico interestadual', '## Aumento de pena para tráfico interestadual

O aumento de pena previsto no inciso V do art. 40 da Lei 11.343/06 é aplicável se o crime for cometido entre Estados da Federação ou entre estes e o Distrito Federal, mesmo que o indivíduo não tenha cruzado a fronteira.

### Conceitos
- **Aumento de pena**: aumento da pena prevista no código
- **Tráfico interestadual**: comércio de drogas entre Estados da Federação ou com o Distrito Federal
- **Lei 11.343/06**: lei que estabelece as penas para crimes relacionados ao tráfico de drogas

### Referências legais
- Art. 40, inciso V, Lei 11.343/06

### Dicas de prova
- Distinção entre tráfico interestadual e tráfico internacional
