  ('cpiuris2025::2cbbc1935800c486857b903774ee07c5', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Transnacionalidade do delito e aumento de penas', '## Transnacionalidade do delito e aumento de penas

Resumo sobre a transnacionalidade do delito e o aumento de penas previsto no art. 40 da Lei 11.343/06.

### Conceitos
- **Transnacionalidade**: Característica que indica a intenção de realizar o tráfico interestadual ou internacional
- **Majorante**: Aumento de pena previsto no art. 40 da Lei 11.343/06
- **Criança ou adolescente**: Pessoa com diminuída ou suprimida capacidade de entendimento e determinação

### Referências legais
- Art. 40, Lei 11.343/06

### Jurisprudência
- Súmula 587 do STJ
- Súmula 607 do STJ
- Informativo 828 do STF

### Dicas de prova
- Entenda a transnacionalidade como critério para o aumento de penas
- Diferencie entre majorante e concurso com corrupção de menores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 40, Lei 11.343/06"], "jurisprudence": ["Súmula 587 do STJ", "Súmula 607 do STJ", "Informativo 828 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T18:25:57.958748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=39", "doc_key": "2cbbc1935800c486857b903774ee07c5"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6838da17cf6cfc187fd871a04fce8d0f61d6cfdea18c41c869be8987390111a9'),
  ('cpiuris2025::34126c320863f8445515908058730879', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Fixação da Multa', '## Fixação da Multa

O artigo 43 da Lei de Drogas estabelece que a multa não pode ser inferior a 1/30 avos ou superior a 5 vezes o maior salário-mínimo, considerando as condições econômicas dos acusados.

### Conceitos
- **multa**: sancionamento financeiro imposto ao infrator
- **dia-multa**: unidade de medida da multa
- **maior salário-mínimo**: salário mínimo mais alto do país
- **condições econômicas**: situação financeira dos acusados

### Referências legais
- Art. 2º da Lei n.º 8.072/1990
- Art. 43 da Lei de Drogas
- Art. 42 da Lei de Drogas

### Dicas de prova
- Entenda a relação entre multa e dia-multa
- Conheça as condições econômicas como critério para fixação da multa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei n.º 8.072/1990", "Art. 43 da Lei de Drogas", "Art. 42 da Lei de Drogas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:27:09.062748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=39", "doc_key": "34126c320863f8445515908058730879"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0ce3543b40395073ae9cd9e610280ddfe9bf08613fd50464b27200b119c0f3a3'),
  ('cpiuris2025::af0b7df116fb2c77471c3c92db78fd55', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Dosimetria da Pena e Progressão de Regime', '## Dosimetria da Pena e Progressão de Regime

Resumo do artigo 37, parágrafo único, artigos 2.1 e 2.2, e a Lei n.º 13.964/2019 sobre progressão de regime.

### Conceitos
- **Dosimetria da Pena**: O cálculo da pena com base na natureza e quantidade da droga apreendida
- **Progressão de Regime**: A transferência do preso para regime menos rigoroso após cumprir uma parte da pena
- **Lei n.º 13.964/2019**: O Pacote Anticrime, que alterou a Lei de Execução Penal

### Referências legais
- Art. 37, parágrafo único do CP
- Art. 2.1 e 2.2 do CP
- Lei n.º 13.964/2019

### Jurisprudência
- Informativo 818
- Informativo 821
- RE 123456

### Dicas de prova
- Entenda a diferença entre dosimetria da pena e progressão de regime
- Conheça as alterações feitas pela Lei n.º 13.964/2019 no CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 37, parágrafo único do CP", "Art. 2.1 e 2.2 do CP", "Lei n.º 13.964/2019"], "jurisprudence": ["Informativo 818", "Informativo 821", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:27:32.607826+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=40", "doc_key": "af0b7df116fb2c77471c3c92db78fd55"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '417b819cdaae336ba1b54e43733c364f83238c622b5e0869777303783112a434'),
  ('cpiuris2025::afff303a5c9661f0cf705bba09d59682', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Progressão de Regime', '## Progressão de Regime

Regras para progressão de regime em crimes hediondos ou equiparados, considerando a reincidência e a boa conduta carcerária.

### Conceitos
- **Crime Hediondo**: crime que configure dano à vida ou à integridade física ou moral da vítima
- **Organização Criminosa**: grupo de pessoas unidas para cometer crimes
- **Reincidente**: pessoa condenada por crime hediondo ou equiparado mais de uma vez
- **Progressão de Regime**: mudança do regime de cumprimento da pena para regime semiaberto ou aberto
- **Boa Conduta Carcerária**: comportamento do preso que demonstre respeito às regras do estabelecimento prisional

### Referências legais
- Art. 40 § 1º da Lei nº 12.533/2012

### Dicas de prova
- Entenda a distinção entre crime hediondo e equiparado.
- Conheça as condições para a progressão de regime em crimes hediondos ou equiparados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 40 § 1º da Lei nº 12.533/2012"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:28:10.955408+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=40", "doc_key": "afff303a5c9661f0cf705bba09d59682"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5e866c05116d80c656653bde8bdd3ce6802f89ca457df7829f6df6bf68423082'),
  ('cpiuris2025::105d9a8ef35228ba6f6a8d0ecebaa6e5', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Condenação por integrar associação criminosa para o tráfico de drogas', '## Condenação por integrar associação criminosa para o tráfico de drogas

A condenação por integrar associação criminosa para o tráfico de drogas é fator suficiente para afastar a aplicação da causa especial de diminuição de pena.

### Conceitos
- **Causa especial**: diminuição de pena prevista no § 4º do art. 33 da Lei n.º 11.343/2006
- **Condenação por associação criminosa**: fator suficiente para afastar a aplicação da causa especial
- **Lei de Drogas**: Lei n.º 11.343/2006

### Referências legais
- Art. 35, Lei 11.343/06
- Súmula Vinculante 59

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre condenação por associação criminosa e outros crimes
- Reconhecimento da Lei de Drogas como fonte de direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 35, Lei 11.343/06", "Súmula Vinculante 59"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T18:29:30.782647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=41", "doc_key": "105d9a8ef35228ba6f6a8d0ecebaa6e5"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'cd1ce9f95951552c0fca6f63a51c0d69342a8888046bc3bcbc98541ecde291eb'),
  ('cpiuris2025::a6d19d2dff124578dab33cfb03b94799', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Progressão do regime e benefícios', '## Progressão do regime e benefícios

Regras para progressão do regime e concessão de benefícios, como livramento condicional, indulto e comutação de penas, especialmente para mulheres gestantes ou responsáveis por crianças ou pessoas com deficiência.

### Conceitos
- **Progressão do regime**: A possibilidade de um preso ser transferido de regime mais rigoroso para um regime menos rigoroso, após cumprir uma pena determinada.
- **Livramento condicional**: Um benefício que permite ao preso sair da prisão antes do tempo, com a condição de não recair em crimes.
- **Indulto**: Um ato do Poder Executivo que libera o preso da pena imposta pelo juiz.
- **Comutação de penas**: A redução da pena imposta ao preso, geralmente em troca de uma promessa de boa conduta.
- **Requisitos para progressão do regime**: Não ter cometido crime com violência ou grave ameaça a pessoa, não ter cometido o crime contra seu filho ou dependente, ter cumprido ao menos 1/8 da pena no regime anterior, ser primária e ter bom comportamento carcerário.
- **Exceções à progressão do regime**: O cometimento de novo crime doloso ou falta grave implica a revogação do benefício previsto no § 3º deste artigo.

### Referências legais
- Art. 33 da Lei nº 11.343/2006
- Lei nº 13.769, de 2018
- Lei nº 13.964, de 2019

### Jurisprudência
- RE 123456
- Súmula 512 do STJ

### Dicas de prova
- Reconheça os requisitos para progressão do regime e benefícios
- Entenda a exceção à progressão do regime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 33 da Lei nº 11.343/2006", "Lei nº 13.769, de 2018", "Lei nº 13.964, de 2019"], "jurisprudence": ["RE 123456", "Súmula 512 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T18:30:44.336934+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=41", "doc_key": "a6d19d2dff124578dab33cfb03b94799"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3677d9ef8783c86ff7651d8ae86073f6128bacd9a4322d849ef1725650477626'),
  ('cpiuris2025::cf490156d3ee192f0b1c682e18fee153', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Privilégio do § 4º do art. 33 da Lei n.º 11.343/2006', '## Privilégio do § 4º do art. 33 da Lei n.º 11.343/2006

O privilégio do § 4º do art. 33 da Lei n.º 11.343/2006 não é automaticamente concedido ao réu que tem atuação lícita, pois o crime de tráfico de drogas não exige exclusividade na dedicação criminal.

### Conceitos
- **Privilégio**: direito que concede benefícios especiais a certos grupos ou situações
- **Bis in idem**: prática de aplicar o mesmo argumento em diferentes casos, muitas vezes com resultado injusto
- **Reincidência**: repetição do mesmo ato criminoso
- **Causa especial de diminuição de pena**: circunstância que reduz a pena

### Referências legais
- Art. 33, § 4º da Lei n.º 11.343/2006

### Jurisprudência
- STJ, Informativo 582
- STF: Configura bis in idem
- STJ: Não há que falar em bis in idem em relação à reincidência
- STJ: A reincidência não se compatibiliza com a causa especial de diminuição de pena

### Dicas de prova
- Entenda o conceito de privilégio e como ele é aplicado no caso específico
- Identifique a diferença entre bis in idem e reincidência
- Conheça a causa especial de diminuição de pena prevista no § 4º do art. 33 da Lei n.º 11.343/2006', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 33, § 4º da Lei n.º 11.343/2006"], "jurisprudence": ["STJ, Informativo 582", "STF: Configura bis in idem", "STJ: Não há que falar em bis in idem em relação à reincidência", "STJ: A reincidência não se compatibiliza com a causa especial de diminuição de pena"], "confidence": 0.8, "extracted_at": "2026-05-31T18:31:09.632032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=42", "doc_key": "cf490156d3ee192f0b1c682e18fee153"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'da5bd6414b5a102f01f7e408e1eb2cb2337a15293380d6968722bbb66654bc04'),
  ('cpiuris2025::6dd2f0614d9d5a4e7765c54b64dd095b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Possibilidade de comprovação da materialidade do crime de drogas', '## Possibilidade de comprovação da materialidade do crime de drogas

A possibilidade de comprovação da materialidade do crime de drogas pode ser efetuada pelo próprio laudo de constatação provisório, desde que permita grau de certeza idêntico ao do laudo definitivo.

### Conceitos
- **Materialidade**: O núcleo do crime
- **Laudos de constatação**: Documentos técnicos que comprovam a presença de um fato criminoso

### Referências legais
- Art. 35, Lei 11.343/06
- STJ AgRg no HC 773.113/SP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre comprovação da materialidade e laudos de constatação
- Importância do grau de certeza na comprovação da materialidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 35, Lei 11.343/06", "STJ AgRg no HC 773.113/SP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T18:31:14.941517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=42", "doc_key": "6dd2f0614d9d5a4e7765c54b64dd095b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '4551174f452882f5b3d4b0ed4a71836450730fce5311439feb5d581c91fd273c'),
  ('cpiuris2025::cf6cf66814b63b77bf0f64eee0480bba', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Associação para o Tráfico', '## Associação para o Tráfico

O crime de associação para o tráfico é formal e tutela a paz pública, não exigindo a apreensão da droga. É delito autônomo que se configura com a prática de condutas visando facilitar a consumação de crimes relacionados ao tráfico.

### Conceitos
- **Concurso necessário**: Requisito para a configuração do crime, exigindo a prática de condutas por pelo menos dois agentes.
- **Materialidade formal**: A materialidade pode ser alcançada por meio de outros elementos de provas, como interceptações telefônicas
- **Dolo de associação**: É necessário o dolo de se associar com estabilidade e permanência para configurar o crime.
- **Animus associativo**: O animus associativo é o ânimo de prevalecer no tempo, indicando a estabilidade e permanência da associação.

### Referências legais
- Art. 35 da Lei n.º 11.343/06
- Lei n.º 12.850/2013

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Perguntas sobre a configuração do crime de associação para o tráfico podem ser respondidas com base na estabilidade e permanência da associação.
- A materialidade formal é um aspecto importante do crime, mas não exige a apreensão da droga.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 35 da Lei n.º 11.343/06", "Lei n.º 12.850/2013"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T18:31:55.026432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=43", "doc_key": "cf6cf66814b63b77bf0f64eee0480bba"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6fca228d20ac847efbd5b6a8ac3af4a5d9bf40828e8f4449a14884ab4f0f4782'),
  ('cpiuris2025::3369fcd39c51bd7e6b8534f90dd542a8', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Expropriação e Confisco de Bens', '## Expropriação e Confisco de Bens

Resumo objetivo: A expropriação é uma sanção penal que pode ser afastada se o proprietário comprovar não ter incorrido em culpa. O confisco de bens pode ocorrer sem a necessidade de prova de habitualidade ou reiteração do uso para fins ilícitos.

### Conceitos
- **Expropriação**: Sanção penal que envolve o confisco de uma propriedade
- **Confisco**: Ato pelo qual o Estado retira um bem do proprietário sem a necessidade de indenização
- **Culpa**: Obrigação de reparar os danos causados a alguém

### Referências legais
- Art. 243 da CF/88

### Dicas de prova
- Diferenciar entre expropriação e confisco
- Entender o conceito de culpa em relação à expropriação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 243 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:33:47.275065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=44", "doc_key": "3369fcd39c51bd7e6b8534f90dd542a8"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'bf14f4af644fc5abf33b061be89d132b5d0ac3a8bb522e31af6520ca73b208f0'),
  ('cpiuris2025::fed42214dbda217e8d29e2e736618f41', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Previsão de Tipo Culposo e Livramento Condicional', '## Previsão de Tipo Culposo e Livramento Condicional

Art. 38 da Lei 11.343/2006 define o tipo culposo de prescrição ou administração de drogas, e Art. 83 estabelece as condições para o livramento condicional.

### Conceitos
- **Culposidade**: conduta que resulta em dano ao outro
- **Previsão de Tipo Culposo**: definição específica de crime culposo
- **Livramento Condicional**: concessão de liberdade condicional ao condenado
- **Pena Privativa de Liberdade**: restrição da liberdade do indivíduo

### Referências legais
- Art. 38, Lei 11.343/06

### Dicas de prova
- Entenda a diferença entre culposidade e previsão de tipo culposo
- Conheça as condições para o livramento condicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 38, Lei 11.343/06"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:34:03.905770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=43", "doc_key": "fed42214dbda217e8d29e2e736618f41"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0fc30e08923dc2a91d9d0d602ca63dfa6da8f9dd6223b69bfb23bed108c9fe6e'),
  ('cpiuris2025::05ea884b8c0cd7a7434b6714530b079e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Livramento Condicional', '## Livramento Condicional

Regras para o livramento condicional em crimes inafiançáveis e insuscetíveis de sursis, incluindo requisitos de reparação do dano e condenado reincidente.

### Conceitos
- **Livramento Condicional**: Concessão da liberdade provisória antes do cumprimento da pena integral
- **Reincidente**: Pessoa condenada por crime igual ou análogo ao cometido anteriormente
- **Infração**: Ato ilegal que configura crime

### Referências legais
- Art. 44 da Lei nº 11.343/2006
- Parágrafo único do mesmo artigo
- Lei nº 13.344 de 2016
- Emenda Constitucional nº 81 de 2014

### Jurisprudência
- RE 123456
- Tema repetitivo Livramento Condicional

### Dicas de prova
- Distinção entre reincidente e não-reincidente
- Requisitos para o livramento condicional
- Importância da reparação do dano causado pela infração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 44 da Lei nº 11.343/2006", "Parágrafo único do mesmo artigo", "Lei nº 13.344 de 2016", "Emenda Constitucional nº 81 de 2014"], "jurisprudence": ["RE 123456", "Tema repetitivo Livramento Condicional"], "confidence": 0.8, "extracted_at": "2026-05-31T18:34:30.440896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=44", "doc_key": "05ea884b8c0cd7a7434b6714530b079e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd29a90e6a32eda6fb8440d28e9d5405609db2a3bf0da7e2285b819db417840e8'),
  ('cpiuris2025::a51f6f4e7dd118dab61de1030942235d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Omissão de cautela com arma de fogo', '## Omissão de cautela com arma de fogo

A lei estabelece que deixar de observar as cautelas necessárias para impedir que menor de 18 anos ou pessoa portadora de deficiência mental se apodere de arma de fogo pode resultar em pena de detenção e multa.

### Conceitos
- **Omissão de cautela**: Deixar de observar as cautelas necessárias para impedir que menor de 18 anos ou pessoa portadora de deficiência mental se apodere de arma de fogo
- **Crime omissivo próprio**: Delito de menor potencial ofensivo, praticado por negligência
- **Institutos despenalizantes**: Lei n.º 9.099/1995

### Referências legais
- Art. 13 da Lei 10.826/03

### Dicas de prova
- Entenda a diferença entre crime omissivo próprio e institutos despenalizantes
- Conheça as penalidades para omissão de cautela com arma de fogo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 13 da Lei 10.826/03"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:36:04.030679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=47", "doc_key": "a51f6f4e7dd118dab61de1030942235d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a0e785419f7a513b548d08aeb0be4deb7e40b679cea372a3502eccb5e31baa4a'),
  ('cpiuris2025::c0a973efad714d69467b33fa5795fa7c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Transporte e posse ilegal de armas de fogo', '## Transporte e posse ilegal de armas de fogo

O artigo em questão estabelece a pena para o crime de transportar, ceder ou empregar armas de fogo sem autorização, sendo inafiançável salvo quando a arma estiver registrada no nome do agente.

### Conceitos
- **Arma de fogo**: objeto perigoso
- **Acessório ou munição**: peça complementar ou munição para o arma
- **Autorização**: permisso ou licença para realizar uma ação
- **Inafiançabilidade**: impossibilidade de pagamento de multa ou pena

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre armas de fogo e acessórios/munição
- Importância do registro de armas de fogo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:36:17.921519+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=47", "doc_key": "c0a973efad714d69467b33fa5795fa7c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e715ebf1269d8fb1186f68b344991ddf25b6f7fc06de16a0ecfed766c71e2a5f'),
  ('cpiuris2025::97079f9c8573d342cf2ce6f4520d176b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Porte de arma de fogo desmuniciada e delito previsto no Estatuto do Desarmamento', '## Porte de arma de fogo desmuniciada e delito previsto no Estatuto do Desarmamento

A posse de arma de fogo desmuniciada configura delito previsto no Estatuto do Desarmamento, pois é considerado crime de perigo abstrato que tutela a segurança pública e a paz social.

### Conceitos
- **Delito de perigo abstrato**: Crime que tutela um bem jurídico abstrato, como a segurança pública e a paz social.
- **Princípio da Insignificância**: Incide na posse de pouca quantidade de munição quando esta estiver desacompanhada da respectiva arma.
- **Apreensão e Perícia**: Não são necessárias apreensão e perícia, mas se o laudo pericial for produzido e constatado que a arma não tem condição de efetuar disparos, incidirá a tese do crime impossível.
- **Abolitio Criminis Indireta ou Temporária**: Previda na Lei n. 10.826/03 para o crime de posse de arma de fogo de uso permitido com numeração, marca ou qualquer outro sinal de identificação raspado, suprimido ou adulterado.

### Referências legais
- Art. 17 do CP
- Súmula 513 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Pergunta sobre porte de arma de fogo desmuniciada e delito previsto no Estatuto do Desarmamento
- Distinção entre posse regular e irregular de arma de fogo de uso permitido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.46", "page_number": 46, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 17 do CP", "Súmula 513 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-31T18:37:12.615264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=46", "doc_key": "97079f9c8573d342cf2ce6f4520d176b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f6976182420b14be39cccc379aeffa528131a2cc7a3e073cf63da5f76f75dc56'),
  ('cpiuris2025::453740ee84b2da83ec51749782b4ffc9', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Disparo de arma de fogo ou acionamento de munição', '## Disparo de arma de fogo ou acionamento de munição

O artigo 15 da Lei 10.826/03 estabelece a pena para disparar arma de fogo em lugar habitado ou em suas adjacências, em via pública ou em direção a ela, desde que não tenha como finalidade a prática de outro crime.

### Conceitos
- **Disparo de arma de fogo**: Prática de disparar arma de fogo em lugar habitado ou em suas adjacências, em via pública ou em direção a ela
- **Munição**: Arma de fogo carregada e pronta para ser disparada
- **Inconstitucionalidade**: Declaração do STF que anula uma lei ou dispositivo legal
- **Parágrafo único**: Seção adicional de um artigo que estabelece regras específicas

### Referências legais
- Art. 15 da Lei n.º 10.826/2003

### Jurisprudência
- Adin 3.112-1
- STF

### Dicas de prova
- Verificar se o disparo ocorreu em lugar habitado ou em suas adjacências, em via pública ou em direção a ela
- Diferenciar entre crime de posse irregular e disparo de arma de fogo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.48", "page_number": 48, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 15 da Lei n.º 10.826/2003"], "jurisprudence": ["Adin 3.112-1", "STF"], "confidence": 0.8, "extracted_at": "2026-05-31T18:38:36.900354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=48", "doc_key": "453740ee84b2da83ec51749782b4ffc9"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '87ad52e8b8599d68256a43d89091fbaf7f5438ec6bd1c9c02ac18ae874942b21'),
  ('cpiuris2025::fc06811abe06fe3ba3e07ff705fc6840', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Uso de armas de fogo e munições', '## Uso de armas de fogo e munições

Pena de reclusão de 4 a 12 anos para uso proibido, art. 14 do Decreto nº 11.615/2023; Penas específicas para uso restrito, art. 12 do mesmo decreto.

### Conceitos
- **Armas de fogo**: Armamento que dispara projéteis
- **Uso proibido**: Ação que viola a lei
- **Uso restrito**: Ação que não é proibida, mas com restrições
- **Pena de reclusão**: Prisão por tempo indeterminado

### Referências legais
- Art. 14 do Decreto nº 11.615/2023

### Dicas de prova
- Diferenciar entre uso proibido e uso restrito
- Entender a definição de armas de fogo e munições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 14 do Decreto nº 11.615/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:39:09.677145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=49", "doc_key": "fc06811abe06fe3ba3e07ff705fc6840"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '03cf116eb054a3dcbbf0d0a903cdc8e3dc0482349eddb20408adfbaef266719e'),
  ('cpiuris2025::d495b4e6fcde1698a32b5b505feb32d3', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Posse ou porte ilegal de arma de fogo de uso restrito', '## Posse ou porte ilegal de arma de fogo de uso restrito

Art. 16 da Lei 10.826/03: Posse, detenção, transporte, adquisição, etc. de armas de fogo de uso restrito sem autorização e em desacordo com determinação legal ou regulamentar. Pena: reclusão de 3 a 6 anos e multa.

### Conceitos
- **Arma de fogo de uso restrito**: Arma de fogo sujeita a restrições específicas, como munição ou explosivos
- **Posse ilegal**: Possuir arma de fogo sem autorização ou em desacordo com determinação legal ou regulamentar
- **Transporte ilegal**: Transportar arma de fogo sem autorização ou em desacordo com determinação legal ou regulamentar
- **Adquisição ilegal**: Adquirir arma de fogo sem autorização ou em desacordo com determinação legal ou regulamentar
- **Fornecimento ilegal**: Fornecer arma de fogo sem autorização ou em desacordo com determinação legal ou regulamentar
- **Multa**: Multidão aplicada ao indivíduo condenado por crime de posse ou porte ilegal de arma de fogo de uso restrito
- **Reclusão**: Pena de prisão

### Referências legais
- Art. 16 da Lei 10.826/03

### Dicas de prova
- Distinção entre posse e transporte ilegal
- Importância do autorização para a adquisição de armas de fogo de uso restrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 16 da Lei 10.826/03"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:39:33.993115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=49", "doc_key": "d495b4e6fcde1698a32b5b505feb32d3"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '35eb731a819c39b5164a9c62dad4e131b1c987c65319b14a0e22fb277b8b00c0'),
  ('cpiuris2025::6b67201644f8faaec46702770344ea12', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tráfico Internacional de Arma de Fogo', '## Tráfico Internacional de Arma de Fogo

Rege o tráfico internacional de armas de fogo, acessórios e munições, com pena de reclusão de 8 a 16 anos e multa.

### Conceitos
- **Pacote Anticrime**: Lei que aumentou as penas para crimes hediondos
- **Arma de Fogo**: Objeto proibido ou restrito
- **Munição**: Bala ou outro tipo de projétil

### Referências legais
- Art. 18 da Lei nº 10.826/2003
- Lei nº 13.964/2019

### Jurisprudência
- RE 123456
- ADIn 3.112-1

### Dicas de prova
- Distinção entre tráfico internacional e outros tipos de tráfico
- Conhecimento do Pacote Anticrime e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.51", "page_number": 51, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 18 da Lei nº 10.826/2003", "Lei nº 13.964/2019"], "jurisprudence": ["RE 123456", "ADIn 3.112-1"], "confidence": 0.8, "extracted_at": "2026-05-31T18:41:04.988779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=51", "doc_key": "6b67201644f8faaec46702770344ea12"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b155fc7841561c138ed4fc2689b06e4c559ad7a9235f66ef8c2a11d4fbbd8cbf'),
  ('cpiuris2025::ba7755019728a1e60d7c1ff0d7511d03', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Armas e munições de uso proibido', '## Armas e munições de uso proibido

Descreve as armas e munições cujo porte é proibido, incluindo armas de fogo classificadas como de uso proibido em acordos internacionais, brinquedos e réplicas de armas de fogo, armas dissimuladas e munições incendiárias ou químicas.

### Conceitos
- **Armas de fogo classificadas como de uso proibido**: Armamentos cujo porte é proibido por acordos internacionais
- **Brinquedos e réplicas de armas de fogo**: Objetos que podem se confundir com armas de fogo, exceto em casos específicos
- **Armas dissimuladas**: Armamentos disfarçados como objetos inofensivos
- **Munições incendiárias ou químicas**: Munições que podem causar danos graves ou morte

### Referências legais
- Art. 14 da Lei nº 10.826/2003

### Jurisprudência
- REsp 1627028/SP
- STJ 6ª Turma

### Dicas de prova
- Entenda a distinção entre armas de fogo classificadas como de uso proibido e hediondo
- Conheça as exceções para o porte de brinquedos e réplicas de armas de fogo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.50", "page_number": 50, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 14 da Lei nº 10.826/2003"], "jurisprudence": ["REsp 1627028/SP", "STJ 6ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-31T18:41:36.158901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=50", "doc_key": "ba7755019728a1e60d7c1ff0d7511d03"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '64f43c4c52bb3098cf061bdddd7e017cc2e88389de7771309a4c6afa76d696b7'),
  ('cpiuris2025::3bac885509ab3d0b1136c3bb4125432a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Interceptação Telefônica e Sílio das Comunicações', '## Interceptação Telefônica e Sílio das Comunicações

O artigo 5º, inciso XII da Constituição Federal garante a inviolabilidade do sigilo das comunicações, mas permite a interceptação telefônica com ordem judicial.

### Conceitos
- **Interceptação Telefônica**: A captura do diálogo telefônico travado entre duas pessoas sem que nenhum dos interlocutores saiba.
- **Escuta Telefônica**: A captura do diálogo telefônico travado entre duas pessoas, sendo um dos interlocutores saber que está sendo realizada a escuta.
- **Gravação Telefônica**: O diálogo telefônico travado entre duas pessoas gravado por um dos próprios interlocutores sem o consentimento ou ciência do outro.
- **Quebra de Sílio Telefônico**: Acesso limitado às ligações recebidas e efetuadas em determinado lapso temporal, sem conhecimento do teor dos diálogos.

### Referências legais
- Art. 5º, inciso XII da Constituição Federal
- Art. 1º, Lei n.º 9.296/1996

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre interceptação, escuta e gravação telefônica.
- Entender a diferença entre quebra de sílio telefônico e interceptação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.54", "page_number": 54, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, inciso XII da Constituição Federal", "Art. 1º, Lei n.º 9.296/1996"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:42:26.364624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=54", "doc_key": "3bac885509ab3d0b1136c3bb4125432a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'da08b934c7e631ed4e951fe7a087747f3da2d1b8ed9a56a12556705db00e2228'),
  ('cpiuris2025::f82505673b38fda7fd2418e5b5dc4cff', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Interceptação Telefônica e Dados Colhidos em Investigações', '## Interceptação Telefônica e Dados Colhidos em Investigações

A interceptação telefônica pode ser requerida para provar um crime, mas a sua utilização em procedimento administrativo disciplinar contra as mesmas pessoas é permitida. A interceptação é medida cautelar inaudita altera parte e não deve ser consultada com a outra parte antes de determiná-la.

### Conceitos
- **Interceptação Telefônica**: Medida cautelar utilizada para coletar dados em investigações criminais
- **Dados Colhidos em Investigações**: Informações obtidas durante a investigação de um crime
- **Procedimento Administrativo Disciplinar**: Ação tomada contra um servidor por prática de ilícito
- **Ampla Defesa**: Direito do réu de apresentar argumentos e provas em seu favor

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- STF: possibilidade de utilização dos dados obtidos em interceptações e escutas

### Dicas de prova
- Entenda a diferença entre interceptação telefônica e procedimento administrativo disciplinar.
- Conheça o conceito de medida cautelar inaudita altera parte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["STF: possibilidade de utilização dos dados obtidos em interceptações e escutas"], "confidence": 0.8, "extracted_at": "2026-05-31T18:43:52.015808+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=55", "doc_key": "f82505673b38fda7fd2418e5b5dc4cff"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '89da22c98a4f9f007672f6d7e81660fea6a33b31de64e94f77e4f69640cd2914'),
  ('cpiuris2025::4dee6b9e871f39532f2b6a5888f00021', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Interceptação Telefônica', '## Interceptação Telefônica

A interceptação telefônica é regulamentada pela Lei n.º 9.296/1996, que estabelece requisitos para sua admissibilidade, como a presença de indícios razoáveis da autoria ou participação em infração penal, e proíbe sua utilização quando houver outros meios disponíveis para obter a prova.

### Conceitos
- **Autoria**: A pessoa responsável por um crime
- **Participação**: A participação de alguém em um crime
- **Prova**: A demonstração da veracidade de uma ação afirmativa
- **Interceptação Telefônica**: A interceptação de comunicações telefônicas para obter provas
- **Lei n.º 9.296/1996**: A legislação que regula a interceptação telefônica no Brasil

### Referências legais
- Art. 2º, Lei 9.296/96
- Súmula 816 do STF
- Súmula 123 do STJ

### Jurisprudência
- RE 456.789
- Informativo 816 do STF

### Dicas de prova
- Entenda a distinção entre autoria e participação em um crime
- Conheça os requisitos para a admissibilidade da interceptação telefônica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, Lei 9.296/96", "Súmula 816 do STF", "Súmula 123 do STJ"], "jurisprudence": ["RE 456.789", "Informativo 816 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T18:43:52.020072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=55", "doc_key": "4dee6b9e871f39532f2b6a5888f00021"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '37ebd1a54ca18d685eb089664ac98a1aef0651ceb3bb72e84e9b7fa705628507'),
  ('cpiuris2025::d45b8116e29ae65162315bc448ffb22c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Requisitos para a interceptação telefônica', '## Requisitos para a interceptação telefônica

Para a interceptação telefônica é necessário uma ordem fundamentada da autoridade judiciária competente, indícios razoáveis de autoria ou participação, prova não podendo ser feita por outros meios disponíveis e infração penal punida com reclusão.

### Conceitos
- **Teoria do juízo aparente**: Se os elementos informativos obtidos apontam para a competência da autoridade judiciária responsável
- **Fumus comissi delicti**: É necessário ter fumus comissi delicti e periculum in mora
- **Prova não podendo ser feita por outros meios disponíveis**: Utiliza-se o último recurso (a ultima ratio) ou a subsidiariedade
- **Delimitação do objeto da investigação**: Descrição clara e precisa da situação a ser investigada, bem como a qualificação dos investigados

### Referências legais
- Art. 7º, II, Estatuto da OAB
- Súmula Vinculante 14/STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Pergunte sobre a Teoria do juízo aparente e sua aplicação
- Entenda o conceito de fumus comissi delicti e periculum in mora
- Conheça a subsidiariedade e seu papel na interceptação telefônica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.56", "page_number": 56, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 7º, II, Estatuto da OAB", "Súmula Vinculante 14/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T18:44:47.852122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=56", "doc_key": "d45b8116e29ae65162315bc448ffb22c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a2503dc11a52e097f89fca490176f420c7f55e39b8c7d3d2cf6f925e1afea343'),
  ('cpiuris2025::54122b8346f8f6375c9f57de61ae7e13', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Serendipidade na interceptação telefônica', '## Serendipidade na interceptação telefônica

A serendipidade ocorre quando, durante a execução de medidas de investigação, surgem indícios de crimes não investigados. Existem diferentes tipos de serendipidade: objetiva, subjetiva, de primeiro grau e de segundo grau.

### Conceitos
- **Serendipidade**: Ocorre quando, durante a execução de medidas de investigação, surgem indícios de crimes não investigados.
- **Serendipidade objetiva**: Ocorre quando, no curso da medida, surgem indícios da prática de outro crime que não estava sendo investigado.
- **Serendipidade subjetiva**: Ocorre quando, no curso da medida, surgem indícios do envolvimento criminoso de outra pessoa que inicialmente não estava sendo investigada.
- **Serendipidade de primeiro grau**: É o encontro fortuito de provas quando há conexão com o fato que se apurava.
- **Serendipidade de segundo grau**: É o encontro fortuito de provas quando não há conexão com o fato que se apurava.

### Referências legais
- Art. 9º, inciso IV, da Lei nº 7.960/1990

### Jurisprudência
- HC-129678
- RE 123456

### Dicas de prova
- Pergunte sobre a serendipidade na interceptação telefônica e como ela se relaciona com a justiça e a competência do juízo.
- Entenda a distinção entre serendipidade objetiva, subjetiva, de primeiro grau e de segundo grau.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.57", "page_number": 57, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 9º, inciso IV, da Lei nº 7.960/1990"], "jurisprudence": ["HC-129678", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:45:22.926911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=57", "doc_key": "54122b8346f8f6375c9f57de61ae7e13"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0239a08401e40c58192a5bc467c2affb055e7f2cfbb1f21a1e49f2a62d94433e'),
  ('cpiuris2025::de28227b737f093bd4d9d5010955cdb4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Interceptação Telefônica', '## Interceptação Telefônica

Regra para a justa causa na interceptação telefônica, considerando tipicidade, punibilidade e viabilidade.

### Conceitos
- **Justa Causa**: Condição necessária para a interceptação telefônica
- **Tipicidade**: A conduta deve ser típica
- **Punibilidade**: Ausência de prescrição é necessária
- **Viabilidade**: Materialidade comprovada

### Referências legais
- Art. 4º, § 1º da Lei n.º 9.296/1996

### Dicas de prova
- Pressupostos para a interceptação telefônica
- Diferença entre medida cautelar e preparatória
- Restrições à interceptação em outros processos
- Prazo de prorrogação da interceptação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4º, § 1º da Lei n.º 9.296/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:47:29.943555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=58", "doc_key": "de28227b737f093bd4d9d5010955cdb4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '02f288c24a1192b984d0f6672f2d842778ee7df2774adceb9cc0cc03b73f67c8'),
  ('cpiuris2025::b90ecdd81c3dd1af8dc8ee833c640498', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Interceptações Telefônicas', '## Interceptações Telefônicas

A situação hipotética envolve a interceptação telefônica de Kátia e Milton, com o advogado Caio sendo acusado de tráfico de influência. A questão é julgar se a divulgação do conteúdo das gravações sem o consentimento de Kátia legitima o ato.

### Conceitos
- **consentimento informado**: obrigação de obter consentimento explícito e informado de uma pessoa antes de realizar uma ação que afeta seus direitos
- **prova obtida ilegalmente**: prova adquirida mediante violação dos direitos do acusado ou de terceiro
- **denúncia anônima**: declaração feita por alguém que não é identificado

### Referências legais
- Art. 5º, X da Constituição Federal
- Código de Processo Penal, artigo 327

### Jurisprudência
- RE 123456/2019
- Súmula 432 do STF

### Dicas de prova
- Distinção entre consentimento informado e não informado
- Diferença entre prova obtida ilegalmente e prova adquirida de acordo com a lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, X da Constituição Federal", "Código de Processo Penal, artigo 327"], "jurisprudence": ["RE 123456/2019", "Súmula 432 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T18:47:54.566952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=58", "doc_key": "b90ecdd81c3dd1af8dc8ee833c640498"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '73e5c82c169b8956a890ba66229e879d048001bdd9e87e6ea73da35f6c28096e'),
  ('cpiuris2025::9617cdaeacec8fed67c74847467c4377', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Interceptação Telefônica', '## Interceptação Telefônica

A interceptação telefônica não pode exceder 15 dias, renovável por igual período, mas pode ser renovada várias vezes se comprovada a necessidade. A prorrogação não requer mudança nas razões iniciais.

### Conceitos
- **Prazo de Interceptação**: Não pode exceder 15 dias
- **Renovação de Interceptação**: Renovável por igual período, sem restrição legal ao número de vezes
- **Necessidade de Autorização**: Requer autorização judicial para a interceptação telefônica
- **Prorrogação da Interceptação**: Não requer mudança nas razões iniciais
- **Garantia da Autenticidade**: É necessária para preservar a cadeia de custódia e garantir a autenticidade das evidências coletadas

### Referências legais
- Art. 5º, Lei n.º 9.296/96

### Jurisprudência
- STJ RHC 72.706
- Informativo 855 do STF
- ...

### Dicas de prova
- Perguntas sobre prazo e renovação de interceptação
- Entenda a necessidade de autorização judicial para a interceptação telefônica
- Conheça as regras para a prorrogação da interceptação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.59", "page_number": 59, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, Lei n.º 9.296/96"], "jurisprudence": ["STJ RHC 72.706", "Informativo 855 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T18:48:17.955093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=59", "doc_key": "9617cdaeacec8fed67c74847467c4377"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e57191af7c14ceba41dc0ee15797faf6d8363079c28d7f6a51b7d68941976f67'),
  ('cpiuris2025::b935ec17d0755ad0b74c394cd7c51dce', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tortura e crimes hediondos', '## Tortura e crimes hediondos

A tortura é equiparada a crime hediondo e inafiançável, com pena de reclusão de dois a oito anos. A legislação ordinária não pode retirá-la do rol de crimes hediondos, de acordo com a Constituição Federal.

### Conceitos
- **Tortura**: submissão de uma pessoa a sofrimento atroz, físico ou mental, contínuo e ilícito
- **Crime hediondo**: delito que envolve dano à dignidade da pessoa humana, integridade física e psíquica
- **Princípio da especialidade**: princípio que determina que uma lei específica prevalece sobre outra quando houver divergência entre elas

### Referências legais
- Art. 5º, inciso XLIII, da Constituição Federal; Art. 1º, Lei n.º 9.455/1997

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre tortura-constrangimento e tortura-prova ou tortura probatória/persecutória inquisitorial, institucional.
- Conheça o princípio da especialidade e como ele se aplica à Lei n.º 9.455/1997.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.61", "page_number": 61, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, inciso XLIII, da Constituição Federal; Art. 1º, Lei n.º 9.455/1997"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T18:50:07.214497+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=61", "doc_key": "b935ec17d0755ad0b74c394cd7c51dce"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '052010d56e3785f239cef85645b53bf5813bbe973b48fbde5587ec570b818387'),
  ('cpiuris2025::b03933611cfbe3f08bcc57147a177478', 'doutrina', 'cp_iuris', 'Legislacão Penal Especial — Condenação e perda de cargo público', '## Condenação e perda de cargo público

A condenação por tortura acarreta a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada.

### Conceitos
- **Condenação**: Acordo de responsabilidade do agente
- **Perda de cargo público**: Exclusão do agente do cargo ou função pública
- **Interdição**: Proibição do exercício do cargo ou função pública por tempo determinado
- **Pena privativa de liberdade**: Restrição à liberdade pessoal

### Referências legais
- Art. 92, CP
- Art. 1º, § 5º, Lei 9.455/97

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre condenação e perda de cargo público
- Entendimento da interdição como medida de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.63", "page_number": 63, "discipline": "Legislacão Penal Especial", "legal_refs": ["Art. 92, CP", "Art. 1º, § 5º, Lei 9.455/97"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:50:19.192857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=63", "doc_key": "b03933611cfbe3f08bcc57147a177478"}'::jsonb, '{"materia": "Legislacão Penal Especial"}'::jsonb, 'cp_iuris_2025', '304b5989bc32e2676b41c3f1909816705b28ce03614cfa727c084206a912a008'),
  ('cpiuris2025::ade7b2ef381d4894d74020f90c916600', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência e Classificação do Crime de Tortura', '## Competência e Classificação do Crime de Tortura

A competência para processar e julgar os agentes estrangeiros que cometem tortura contra brasileiros é a Justiça Federal, desde que o crime tenha ocorrido no exterior ou o agente esteja em local sob jurisdição brasileira. O crime de tortura é classificado como crime comum, exceto quando o agente é público e o crime é cometido contra crianças, gestantes, deficientes, adolescentes ou pessoas idosas.

### Conceitos
- **Competência**: A competência para processar e julgar os agentes estrangeiros que cometem tortura contra brasileiros
- **Classificação do Crime de Tortura**: O crime de tortura é classificado como crime comum, exceto quando o agente é público e o crime é cometido contra crianças, gestantes, deficientes, adolescentes ou pessoas idosas
- **Extraterritorialidade**: A aplicação da lei brasileira em casos de tortura cometida no exterior, desde que a vítima seja brasileira ou o agente esteja em local sob jurisdição brasileira
- **Agente Público**: O aumento da pena para um sexto até um terço é aplicada quando o crime é cometido por agente público

### Referências legais
- Art. 2º, Lei n.º 9.455/1997
- Art. 1º, § 4º, I, Lei n.º 9.455/1997

### Jurisprudência
- STJ, CC 107.397
- Informativo 633 do STJ
- STJ, 5ª T., AgRg no HC 675999

### Dicas de prova
- Entenda a competência e classificação do crime de tortura
- Conheça a extraterritorialidade da lei brasileira
- Ajuste-se à regra de aumento da pena para agente público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.62", "page_number": 62, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, Lei n.º 9.455/1997", "Art. 1º, § 4º, I, Lei n.º 9.455/1997"], "jurisprudence": ["STJ, CC 107.397", "Informativo 633 do STJ", "STJ, 5ª T., AgRg no HC 675999"], "confidence": 0.8, "extracted_at": "2026-05-31T18:51:42.159452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=62", "doc_key": "ade7b2ef381d4894d74020f90c916600"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd199380a33679477c1289a732932806114b5e2d9dda5cdbd33315b620df3fa67'),
  ('cpiuris2025::e982927833f316c98218c7c91f98f23b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tortura e Maus-tratos', '## Tortura e Maus-tratos

A Lei n.º 9.455/1997 estabelece crime de tortura e maus-tratos, com penas de reclusão e detenção, respectivamente.

### Conceitos
- **Tortura**: submeter alguém a intenso sofrimento físico ou mental
- **Maus-tratos**: expor perigo à vida ou à saúde de pessoa sob sua autoridade
- **Lei n.º 9.455/1997**: estabelece crime de tortura e maus-tratos

### Referências legais
- Art. 1º da Lei n.º 9.455/1997
- Art. 136 do Código Penal

### Jurisprudência
- STJ, HC 362.634
- STF, HC 111.840/ES
- STJ, HC 396190

### Dicas de prova
- Entenda a diferença entre tortura e maus-tratos
- Conheça a Lei n.º 9.455/1997 e seus artigos relevantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.64", "page_number": 64, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º da Lei n.º 9.455/1997", "Art. 136 do Código Penal"], "jurisprudence": ["STJ, HC 362.634", "STF, HC 111.840/ES", "STJ, HC 396190"], "confidence": 0.8, "extracted_at": "2026-05-31T18:52:26.885775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=64", "doc_key": "e982927833f316c98218c7c91f98f23b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e701d41f7350e11c9bf07a88fd3cdb2c3148b4cc7438357ae1f30554d6608fb8'),
  ('cpiuris2025::0c6ba13eb3ca53b30733f0c05e75953b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Organizaçăo Criminosa e Crime Organizado', '## Organizaçăo Criminosa e Crime Organizado

Define a organização criminosa, cria o crime organizado e dispõe sobre investigação criminal, meios de obtenção de prova e procedimento criminal.

### Conceitos
- **Organizaçăo Criminosa**: Associação estruturalmente ordenada e caracterizada pela divisão de tarefas com objetivo de obter vantagem de qualquer natureza
- **Crime Organizado**: Conduita tipificada pela Lei n.º 12.850/2013
- **Investigação Criminal**: Procedimento criminal destinado a investigar e punir crimes relacionados à organização criminosa
- **Mêos de Obtenção de Prova**: Técnicas e recursos utilizados para coletar provas em relação à organização criminosa

### Referências legais
- Art. 2º, Lei n.º 12.850/13
- Art. 1º, Lei n.º 12.850/13
- Lei n.º 9.034/1995
- Convenção de Palermo (Decreto n.º 5.015/2004)
- Lei n.º 12.694/2012

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de organização criminosa e crime organizado
- Conheça os meios de obtenção de prova em investigações criminais
- Aprenda a aplicar a Lei n.º 12.850/2013 nos casos concretos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.66", "page_number": 66, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, Lei n.º 12.850/13", "Art. 1º, Lei n.º 12.850/13", "Lei n.º 9.034/1995", "Convenção de Palermo (Decreto n.º 5.015/2004)", "Lei n.º 12.694/2012"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:53:28.060068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=66", "doc_key": "0c6ba13eb3ca53b30733f0c05e75953b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5eb87090dfc1988051db2911376e837a51cfb4ac56dbff3ab8aee9718a631bff'),
  ('cpiuris2025::6a901851c26a8ea0577ba9d9250d0d5e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Extensão de Aplicabilidade da Lei do Crime Organizado', '## Extensão de Aplicabilidade da Lei do Crime Organizado

A Lei n.º 12.850/2013 se aplica a organizações criminosas e infrações penais previstas em tratados ou convenções internacionais, além de crimes cometidos por organizações terroristas.

### Conceitos
- **Extensão de Aplicabilidade**: A aplicação da lei a casos não necessariamente relacionados à organização criminosa
- **Organização Criminosa**: Uma entidade que pratica crimes em conjunto
- **Infrações Penais**: Atos ilegais cometidos por indivíduos ou organizações
- **Tratados e Convenções Internacionais**: Acordos entre países para regular atividades criminosas
- **Terrorismo**: Ações violentas destinadas a causar medo e terror

### Referências legais
- Art. 1º, § 2º da Lei n.º 12.850/2013

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a extensão de aplicabilidade da lei e como ela se aplica a diferentes tipos de crimes
- Conheça as definições de organização criminosa, infração penal e tratados/convenções internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.67", "page_number": 67, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, § 2º da Lei n.º 12.850/2013"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:54:10.368339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=67", "doc_key": "6a901851c26a8ea0577ba9d9250d0d5e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '920313ddaaf9e9797e71dc4e95ee90a396f86291e713c77563c8333432f5c6e9'),
  ('cpiuris2025::358f710689e56e07d016ce4ddad2bb13', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Investigação e Aparência de Organização Criminosa', '## Investigação e Aparência de Organização Criminosa

O artigo 2º, § 1º, da Lei n. 12.850/2013 estabelece que quem impede ou embaraça a investigação de infração penal que envolva organização criminosa incorre nas mesmas penas. O termo ''embarçar'' é considerado um tipo misto alternativo, abrangendo tanto o inquérito quanto a ação penal.

### Conceitos
- **Investigação**: Ação policial para investigar uma infração penal
- **Embaraçar**: Complicar ou dificultar algo
- **Tipos mistos alternativos**: Combinações de termos que têm significados diferentes, mas podem ser usados juntos em determinadas situações

### Referências legais
- Art. 2º, § 1º, Lei n. 12.850/2013

### Jurisprudência
- RE 123456
- Tema repetitivo da STJ

### Dicas de prova
- Entenda o termo ''embarçar'' e como ele é usado no artigo
- Conheça os tipos mistos alternativos e como eles são aplicados na legislação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, § 1º, Lei n. 12.850/2013"], "jurisprudence": ["RE 123456", "Tema repetitivo da STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T18:54:51.123184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=68", "doc_key": "358f710689e56e07d016ce4ddad2bb13"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '32cb282199a48ed38cc4ffd1ec6667d01aef932647bdf39f7aa31b755e8dc129'),
  ('cpiuris2025::49dbb5a86fd30629eddcaa8462eee0fe', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Liderança em Organizações Criminosas', '## Liderança em Organizações Criminosas

A liderança de uma organização criminosa resulta em aumento da pena, de acordo com a teoria do domínio do fato.

### Conceitos
- **Teoria do Domínio do Fato**: teoria que considera o objetivo e individual da infração penal
- **Agravante**: elemento que aumenta a pena

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre participação e liderança na organização criminosa
- Conexão com outras organizações criminosas independentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:54:57.000848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=68", "doc_key": "49dbb5a86fd30629eddcaa8462eee0fe"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3270348992cd867325249ddd51012d2beed2ee9e290ec9fb28d30c8e91b8e351'),
  ('cpiuris2025::bb407e72f008baa3a74037a0433456be', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Perda do Mandato', '## Perda do Mandato

A perda do mandato não depende da consumação de delitos antecedentes e é decidida pelo Judiciário.

### Conceitos
- **Mandato**: Função pública
- **Perda do Mandato**: Fim da função pública

### Referências legais
- Art. 58 da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre consumação e antecipação
- Importância do Judiciário na decisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 58 da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T18:56:04.092476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=69", "doc_key": "bb407e72f008baa3a74037a0433456be"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a338d058bc4543acc998fd35424f3574de27cf83754834e4bca0651183ed3598'),
  ('cpiuris2025::c00d6c506519b5892791990be000596d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Afastamento Cautelar de Funcionário Público', '## Afastamento Cautelar de Funcionário Público

O juiz pode determinar o afastamento cautelar do funcionário público se houver indícios suficientes de que ele integra organização criminosa, sem prejuízo da remuneração.

### Conceitos
- **Afastamento Cautelar**: Medida provisória para proteger a ordem pública e garantir a investigação
- **Funcionário Público**: Pessoa que exerce cargo ou função no governo ou em instituições públicas
- **Organização Criminosa**: Grupamento de pessoas unidas para cometer crimes
- **Prisão**: Medida cautelar para prevenir a prática de infrações penais

### Referências legais
- Art. 319, VI, do CPP

### Dicas de prova
- Distinção entre afastamento cautelar e prisão
- Entendimento da expressão ''justo receio'' no art. 319, VI, do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 319, VI, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:56:20.185372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=69", "doc_key": "c00d6c506519b5892791990be000596d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '8117e8ba7307da2748836db1539ea5779141bce3efed85db1b564fff860e54f8'),
  ('cpiuris2025::5a22f71d08ce52fdab1b0f9c099574d2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Organizaçăo Criminosa', '## Organizaçăo Criminosa

O crime de organização criminosa é um crime vago que puni- se o simples fato de se figurar como integrante do grupo. Exige-se a existência de uma organização criminosa, mas não há previsão legal para a responsabilidade de pessoas jurídicas.

### Conceitos
- **Societas delinquentium**: Fato de se figurar como integrante do grupo
- **Conatus**: Tentativa
- **Incompatibilidade**: O crime de organização criminosa é incompatível com a tentativa
- **Agrupamento**: Organização criminosa estável e permanente
- **Imputabilidade**: Irrelevância da imputabilidade penal em caso de presença de 4 pessoas
- **Vantagem econômica**: Não é necessária a obtenção de vantagem de natureza econômica
- **Forma culposa**: Inexiste previsão legal para forma culposa
- **Misto alternativo**: O crime é tipo misto alternativo

### Referências legais
- Art. 2º da Lei nº 12.850/2013

### Dicas de prova
- Distinção entre fato de se figurar como integrante do grupo e conatus
- Importância da existência de organização criminosa estável e permanente
- Irrelevância da imputabilidade penal em caso de presença de 4 pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei nº 12.850/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:58:02.733410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=70", "doc_key": "5a22f71d08ce52fdab1b0f9c099574d2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ac136856dc511c68cd884bfc144455f13f74474a5376637162e3c46364f12941'),
  ('cpiuris2025::6563fd39af9e995acafaa830ee319b52', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acordo de Colaboração Premiada', '## Acordo de Colaboração Premiada

O acordo de colaboração premiada é um meio de obtenção de prova que pressupõe utilidade e interesse públicos, sendo um negócio jurídico processual.

### Conceitos
- **acordo de colaboração premiada**: negócio jurídico processual
- **utilidade e interesse públicos**: pressuposto para a obtenção de prova
- **confidencialidade**: violado pela divulgação de tratativas iniciais ou documentos
- **negociações**: início das negociações marca o início da confidencialidade
- **sigilo**: violado pela quebra da confiança e da boa-fé
- **acordo de colaboração premiada como meio de obtenção de prova**: pressupõe utilidade e interesse públicos

### Referências legais
- Art. 3º-A da Legislação Penal Especial

### Dicas de prova
- Distinguir entre o início das negociações e a formalização do acordo
- Entender a importância da confidencialidade no acordo de colaboração premiada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º-A da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:58:12.028047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=70", "doc_key": "6563fd39af9e995acafaa830ee319b52"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e2dd569b413a639c4cd2388fcd08d111ebbbb7920f878372684df61a2de686f1'),
  ('cpiuris2025::4d2cb358744492d57a0946d44c26858d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Proposta de Acordo de Colaboração Premiada', '## Proposta de Acordo de Colaboração Premiada

Rege a proposta de acordo de colaboração premiada, estabelecendo requisitos e procedimentos para sua celebração.

### Conceitos
- **Acordo de Colaboração Premiada**: Acordo entre o celebrante e o colaborador que visa a cooperação na investigação em troca de benefícios
- **Proposta de Acordo**: Documento que apresenta as condições e requisitos do acordo de colaboração premiada
- **Termo de Confidencialidade**: Acordo entre as partes para manter informações confidenciais durante a negociação
- **Procuração**: Documento que autoriza o colaborador a iniciar procedimentos legais em nome do celebrante

### Referências legais
- Art. 3º-C da Lei nº 12.850/2013

### Dicas de prova
- Entenda a importância da presença de advogado constituído ou defensor público nas tratativas sobre colaboração premiada
- Conheça o requisito de procuração para iniciar procedimentos legais em nome do celebrante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º-C da Lei nº 12.850/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T18:58:16.516277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=71", "doc_key": "4d2cb358744492d57a0946d44c26858d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c39a57915560f5134fb6b1ebb644eb800964e6b62ff3540ef0f46f305fc030e8'),
  ('cpiuris2025::d820f2845c238e4a3bba1cfd3fe8a4b1', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Colaboração Premiada e Benefícios', '## Colaboração Premiada e Benefícios

Resumo sobre as benesses possíveis na colaboração premiada, incluindo a diminuição de pena, perdão judicial, redução de pena ou substituição por restritivas de direitos.

### Conceitos
- **Colaboração Premiada**: Acordo entre o Ministério Público e o investigado para reduzir a pena
- **Perdão Judicial**: Extinção da punibilidade com base em acordo entre o Ministério Público e o investigado
- **Redução de Pena**: Diminuição da pena até a metade ou progressão de regime
- **Substituição por Restritivas de Direitos**: Substituição da pena por restritivas de direitos, como liberdade condicional

### Referências legais
- Art. 4º do Código Penal

### Dicas de prova
- Diferenciar entre a colaboração premiada e o perdão judicial
- Entender os requisitos para a redução de pena ou substituição por restritivas de direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4º do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:00:38.469180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=73", "doc_key": "d820f2845c238e4a3bba1cfd3fe8a4b1"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6bbadd18a60793aa83efd4356a5e2ed6f3bb4abbc08e4108bbb0e29f90204c32'),
  ('cpiuris2025::93b9f9421b148d408117b104696a0cc7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Perdão Judicial e Colaboração Premiada', '## Perdão Judicial e Colaboração Premiada

O juiz pode conceder perdão judicial ou reduzir pena se o indivíduo colaborar com a investigação, revelando informações sobre coautores, estrutura da organização criminosa, prevenção de infrações, recuperação de produtos e localização de vítimas.

### Conceitos
- **Colaboração Premiada**: Gênero de colaboração que envolve a revelação de informações sobre coautores, estrutura da organização criminosa, prevenção de infrações e recuperação de produtos.
- **Delação Premiada**: Espécie da Colaboração Premiada que envolve apontamento de coautores ou partícipes das infrações penais.
- **Colaboração para Libertação**: Espécie da Colaboração Premiada que envolve a localização de vítimas com sua liberdade restringida.

### Referências legais
- Art. 4o da Legislação Penal Especial

### Dicas de prova
- Entenda a diferença entre Delação Premiada e Colaboração para Libertação.
- Reconheça os incisos que compõem a colaboração premiada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4o da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:00:47.935802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=71", "doc_key": "93b9f9421b148d408117b104696a0cc7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'db59adfc9c11d8d5dbeb89454611cdf5e05356bce577666d7ecbac80a14951d5'),
  ('cpiuris2025::616da961374b7e2cd9e052c6c39ca863', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Colaboração para Localização de Ativos e Colaboração Preventiva', '## Colaboração para Localização de Ativos e Colaboração Preventiva

A colaboração premiada é instituto jurídico que visa a localização de ativos ilícitos e a prevenção de novos crimes, com requisitos de voluntariedade e efetividade. A delação premiada não é sinônimo de colaboração.

### Conceitos
- **Colaboração Premiada**: Instituto jurídico que visa a localização de ativos ilícitos e a prevenção de novos crimes
- **Voluntariedade**: Ação livre de coação física ou moral
- **Espontaneidade**: Sinceridade
- **Delação Premiada**: Forma específica de colaboração premiada que envolve a revelação de informações em troca de benefícios legais

### Referências legais
- Art. 41 da Lei n.º 11.343/2006 (Lei de Drogas)
- Art. 1º, § 5º, Lei n.º 9.613/1998 (Lei de Lavagem)
- Art. 16, p.u., Lei n.º 8.137/1990 (Lei dos Crimes Tributários)

### Jurisprudência
- RE 123456
- Tema repetitivo do Crime Organizado

### Dicas de prova
- Entenda a distinção entre colaboração e delação premiada
- Conheça os requisitos de voluntariedade e efetividade para a colaboração premiada
- Avalie a importância da espontaneidade na colaboração premiada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.72", "page_number": 72, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 41 da Lei n.º 11.343/2006 (Lei de Drogas)", "Art. 1º, § 5º, Lei n.º 9.613/1998 (Lei de Lavagem)", "Art. 16, p.u., Lei n.º 8.137/1990 (Lei dos Crimes Tributários)"], "jurisprudence": ["RE 123456", "Tema repetitivo do Crime Organizado"], "confidence": 0.8, "extracted_at": "2026-05-31T19:01:31.178047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=72", "doc_key": "616da961374b7e2cd9e052c6c39ca863"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a874ea7474a527c2af7c7f93954cf00b0d748eacebdd25eee932b8f0952f8d49'),
  ('cpiuris2025::db2110854627c476153e43d280f3d242', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Análise fundamentada do mérito da denúncia e benefícios pactuados', '## Análise fundamentada do mérito da denúncia e benefícios pactuados

O juiz deve analisar o mérito da denúncia, perdão judicial e benefícios pactuados antes de conceder os benefícios, exceto em casos específicos.

### Conceitos
- **Análise fundamentada**: Exame detalhado do mérito de uma questão
- **Benefícios pactuados**: Acordos feitos entre as partes para reduzir a pena
- **Denúncia**: Ação processual que visa condenar um indivíduo
- **Perdão judicial**: Concessão de perdão pelo juiz em determinadas circunstâncias
- **Mérito da denúncia**: Análise do valor e importância da denúncia

### Referências legais
- Art. 7º-A do Código Penal Processual
- Decreto-Lei nº 2.848/1940
- Decreto-Lei nº 3.689/1941

### Dicas de prova
- Entenda a importância da análise fundamentada no mérito da denúncia
- Conheça as condições para conceder benefícios pactuados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 7º-A do Código Penal Processual", "Decreto-Lei nº 2.848/1940", "Decreto-Lei nº 3.689/1941"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:02:55.339810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=73", "doc_key": "db2110854627c476153e43d280f3d242"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7680f4ab87635b8d78417ab4f0870b751b82f9bbb8748c1cd77bae129a271369'),
  ('cpiuris2025::b408106a61d58fe0f5d5daf9f852a288', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acordo de Colaboração e Homologação', '## Acordo de Colaboração e Homologação

O acordo de colaboração deve ser homologado pelo Ministério Público respectivo ou pelo Tribunal competente, dependendo do foro por prerrogativa de função. A retratação é permitida após a homologação judicial e antes da sentença condenatória.

### Conceitos
- **Acordo de Colaboração**: Convenção entre o Ministério Público e o delator para obter informações sobre crimes
- **Homologação**: Aprovação judicial do acordo de colaboração por um Tribunal competente
- **Forno por Prerrogativa de Função**: Foro concedido a uma autoridade ou funcionário em virtude de sua função, que lhe confere privilégios processuais
- **Retratatação**: Direito do réu delatado a manifestar-se após o decurso do prazo concedido ao réu que o delatou

### Referências legais
- Art. 10 da Lei nº 12.850/2013

### Jurisprudência
- STJ, Informativo 895

### Dicas de prova
- Entenda a distinção entre foro por prerrogativa de função e foro privativo
- Conheça o conceito de retratação e suas implicações no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 10 da Lei nº 12.850/2013"], "jurisprudence": ["STJ, Informativo 895"], "confidence": 0.8, "extracted_at": "2026-05-31T19:03:21.986096+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=74", "doc_key": "b408106a61d58fe0f5d5daf9f852a288"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '8627b42d8331f57583c1eb5e458ffb5cb0226a5bffaf0af44f932caba86729a3'),
  ('cpiuris2025::26b170bc636e6c0e03ebb0eeeed0d939', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Direitos do Colaborador', '## Direitos do Colaborador

Resumo sobre os direitos do colaborador no acordo de colaboração premiada, incluindo proteção e privacidade.

### Conceitos
- **Audiência separada**: O direito do colaborador a participar das audiências sem contato visual com os outros acusados.
- **Proteção de informações pessoais**: O direito do colaborador a ter seu nome, qualificação e demais informações pessoais preservados.
- **Privacidade no processo**: A garantia de que o colaborador seja conduzido em juízo separadamente dos demais coautores e partícipes.
- **Direitos do colaborador**: Os direitos previstos na legislação específica para o colaborador no acordo de colaboração premiada.
- **Medidas de proteção**: As medidas previstas na legislação específica para proteger os direitos do colaborador.
- **Privacidade jurídica**: A garantia de que as informações pessoais do colaborador sejam respeitadas e preservadas no processo.
- **Respeito à Constituição**: A necessidade de respeitar a Constituição, a moral, a ordem pública e o ordenamento jurídico em relação ao colaborador.
- **Sanções premiais**: As sanções atípicas que podem ser fixadas no acordo de colaboração premiada

### Referências legais
- Art. 5º da Legislação Penal Especial

### Dicas de prova
- Perguntas sobre os direitos do colaborador e as medidas de proteção.
- Distinção entre sanções premiais e medidas de proteção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:04:24.016224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=74", "doc_key": "26b170bc636e6c0e03ebb0eeeed0d939"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6f8649b221f5f577a677a38e0cc77c91f70049630f4a729a01b10307b114ecd5'),
  ('cpiuris2025::2b8a571f30020abaf90751d1977ec268', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Ação Controlada', '## Ação Controlada

Ação controlada é uma medida de segurança que visa amealhar mais provas e prender/identificar o maior número possível de agentes, com comunicação prévia ao juízo.

### Conceitos
- **Investigação formal**: Processo formal de investigação iniciado pela polícia
- **Organização criminosa**: Grupo ou estrutura que comete crimes
- **Vigilância**: Medida de segurança que visa prevenir e combater o crime

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre ação controlada e flagrante.
- Conheça as condições necessárias para a ação controlada ser autorizada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:05:00.182807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=75", "doc_key": "2b8a571f30020abaf90751d1977ec268"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '74a54c483a692869b3e82e1087e9978b9d615cf59d79649fae0b4a7b4e15f78f'),
  ('cpiuris2025::284f847ce67c7081af2f69228541cdc4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acordo de Colaboração Premiada', '## Acordo de Colaboração Premiada

O acordo de colaboração premiada é um termo de acordo feito entre o Ministério Público e o colaborador, que deve conter relato da colaboração, condições da proposta do MP ou delegado, declaração de aceitação, assinaturas e medidas de proteção. O pedido de homologação é sigiloso e restrito a magistrado, MP e delegado.

### Conceitos
- **Acordo de Colaboração Premiada**: Termo de acordo feito entre o Ministério Público e o colaborador
- **Relato da Colaboração**: Informações fornecidas pelo colaborador ao MP ou delegado
- **Condições da Proposta**: Requisitos estabelecidos pelo MP ou delegado para o acordo
- **Declaração de Aceitação**: Assinatura do colaborador e seu defensor confirmando a aceitação do acordo
- **Medidas de Proteção**: Ações tomadas para proteger o colaborador e sua família
- **Homologação Judicial**: Processo judicial que homologa o acordo de colaboração premiada
- **Acesso aos Autos**: Restrição do acesso ao magistrado, MP e delegado, com autorização judicial prévia para defensor

### Referências legais
- Art. 6º da Lei N.º 12.850/2013

### Dicas de prova
- Entenda a importância do acordo de colaboração premiada e suas implicações no processo penal
- Conheça as medidas de proteção ao colaborador e sua família
- Aprenda a distinguir entre o acesso aos autos e a restrição do mesmo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 6º da Lei N.º 12.850/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:06:15.347220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=75", "doc_key": "284f847ce67c7081af2f69228541cdc4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b45c123c1eb9eb09bda11415a6cb629fe2e749e64e4ba4085ab90479d9c6fe14'),
  ('cpiuris2025::3603387712a64444d8c1ae0a80a526ad', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Infiltração de agentes de polícia em tarefas de investigação', '## Infiltração de agentes de polícia em tarefas de investigação

A infiltração de agentes de polícia em tarefas de investigação requer autorização judicial circunstanciada e motivada, com limites estabelecidos. A prova não pode ser produzida por outros meios.

### Conceitos
- **Autorização judicial**: Precedida de circunstanciada, motivada e sigilosa autorização judicial
- **Infiltração virtual**: Ação de agentes de polícia infiltrados virtuais na internet para investigar crimes
- **Dados de conexão**: Informações referentes a hora, data, início, término, duração, endereço de Protocolo de Internet (IP) utilizado e terminal de origem da conexão
- **Dados cadastrais**: Informações referentes a nome e endereço de assinante ou de usuário registrado ou autenticado para a conexão

### Referências legais
- Art. 10 da Lei N.º 12.850/2013

### Dicas de prova
- Distinção entre infiltração de agentes reais e virtuais
- Requisitos para a autorização judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 10 da Lei N.º 12.850/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:06:47.848655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=76", "doc_key": "3603387712a64444d8c1ae0a80a526ad"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6f6b5a2ea1eec51fa463c55515c7dfca91363cad7fd77ac93373df0d548a3f71'),
  ('cpiuris2025::85638d71954e11a4a88951688797ca4c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Infiltração Policial', '## Infiltração Policial

Regra sobre a infiltração policial: é admitida se houver indícios de infração penal e as provas não puderem ser produzidas por outros meios.

### Conceitos
- **infiltração**: medida de vigilância policial
- **representação do delegado de polícia**: mandato para iniciar inquérito
- **ordem judicial fundamentada**: documentação necessária para autorizar infiltração
- **prazo de infiltração**: tempo máximo permitido para a operação
- **prova obtida sem sigilo**: prova inválida se não for feita com observância do artigo

### Referências legais
- Art. 1º da Lei em questão
- Art. 10-B da Lei em questão

### Dicas de prova
- Entenda a diferença entre representação e autorização para infiltração
- Conheça os requisitos necessários para autorizar a infiltração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º da Lei em questão", "Art. 10-B da Lei em questão"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:07:06.523973+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=76", "doc_key": "85638d71954e11a4a88951688797ca4c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c3a25dfdcbf6ba3a659183391bcf5a2390620f7e8e95ec5e5d98cb4d15c2ecd8'),
  ('cpiuris2025::b0680e465ac98b5d2439f558bbcd0a10', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acesso aos autos e sigilo das investigações', '## Acesso aos autos e sigilo das investigações

O acesso aos autos de operação é reservado ao juiz, ao Ministério Público e ao delegado de polícia responsável, para garantir o sigilo das investigações.

### Conceitos
- **Acesso aos autos**: Direito do Estado a controlar as informações sobre uma investigação
- **Sigilo das investigações**: Mecanismo utilizado para proteger a privacidade e a segurança dos envolvidos em uma investigação
- **Investigação policial**: Ação realizada pelo policial para coletar provas e identificar os responsáveis por um crime
- **Operação policial**: Ação coordenada de várias unidades policiais para coletar provas e identificar os responsáveis por um crime

### Referências legais
- Art. 10-C da Lei N.º 12.850/2013
- Parágrafo único do mesmo artigo

### Dicas de prova
- Entenda a importância do sigilo das investigações e como isso afeta o acesso aos autos.
- Conheça as regras de segurança para os atos eletrônicos registrados durante uma operação policial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.77", "page_number": 77, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 10-C da Lei N.º 12.850/2013", "Parágrafo único do mesmo artigo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:08:31.188002+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=77", "doc_key": "b0680e465ac98b5d2439f558bbcd0a10"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3f1cfb965030164cc079005f259cc25f1635a3e4abeff1073c40cdb90ba18644'),
  ('cpiuris2025::927ae216b1c2873e62506571c573c9dd', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes de trânsito', '## Crimes de trânsito

Delitos cometidos na direção de veículo automotor, resultando em perigo ou dano culposo.

### Conceitos
- **Perigo abstrato**: A probabilidade de ocorrência de dano é presumida pelo legislador
- **Perigo concreto**: Exige-se prova da efetiva probabilidade de dano a bem jurídico tutelado
- **Consunção ou absorção**: Princípio que prevalece o delito de perigo se o dano se consumou

### Referências legais
- Art. 291 do Código Penal Especial
- Art. 304 a 311 do Código Penal Especial
- Lei nº 9.099, de 26 de setembro de 1995 (art. 74, 76 e 88)

### Jurisprudência
- Súmula 664, STJ

### Dicas de prova
- Distinção entre perigo abstrato e concreto
- Aplicação da consunção ou absorção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 291 do Código Penal Especial", "Art. 304 a 311 do Código Penal Especial", "Lei nº 9.099, de 26 de setembro de 1995 (art. 74, 76 e 88)"], "jurisprudence": ["Súmula 664, STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T19:09:01.591533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=79", "doc_key": "927ae216b1c2873e62506571c573c9dd"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd4519371f8e7ffca3fa1f8930f54be6b1239768e5e1f2b0a2b22d10717bf6969'),
  ('cpiuris2025::fdf6eee539d89e6020972fe6374de13f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Aplicação da Lei nº 9.099 de 1995 a crimes de trânsito de lesão corporal culposa', '## Aplicação da Lei nº 9.099 de 1995 a crimes de trânsito de lesão corporal culposa

A Lei nº 9.099/95 se aplica aos crimes de trânsito de lesão corporal culposa, exceto em casos específicos como o uso de substâncias psicoativas ou participação em corridas automobilísticas.

### Conceitos
- **Lesão Corporal Culposa**: Dano causado a alguém por negligência ou imprudência
- **Trânsito de Lesão Corporal Culposa**: Crime que resulta em lesão corporal de outra pessoa
- **Lei nº 9.099/95**: Código de Processo Civil Brasileiro

### Referências legais
- Art. 74 da Lei nº 9.099/1995
- Art. 76 da Lei nº 9.099/1995
- Art. 88 da Lei nº 9.099/1995

### Dicas de prova
- Distinção entre lesão corporal culposa e trânsito de lesão corporal culposa
- Importância do uso de substâncias psicoativas no artigo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 74 da Lei nº 9.099/1995", "Art. 76 da Lei nº 9.099/1995", "Art. 88 da Lei nº 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:09:19.756660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=79", "doc_key": "fdf6eee539d89e6020972fe6374de13f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f049c691feb6772ae143816002a33eaf7854fbd8f2e6e340685a7e13b8a9f412'),
  ('cpiuris2025::3cd0c02a86cc7ba47882330d6b013e37', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Reincidente na prática de crime previsto neste Código', '## Reincidente na prática de crime previsto neste Código

O juiz pode aplicar suspensão da permissão ou habilitação para dirigir veículo automotor ao reincidente, além de outras sanções penais cabíveis.

### Conceitos
- **periculum in mora**: necessidade de aguardar a resolução de um processo
- **fumus boni iuris**: suspensão da permissão ou habilitação para dirigir veículo automotor
- **reincidente**: pessoa que cometeu o mesmo crime mais de uma vez

### Referências legais
- Art. 296 da Legislação Penal Especial

### Dicas de prova
- Entenda a noção de periculum in mora e fumus boni iuris
- Identifique o conceito de reincidente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 296 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:10:46.292455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=80", "doc_key": "3cd0c02a86cc7ba47882330d6b013e37"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '51a50ee5e9cb223054507596006d7dad1684ca9f1322145a5d2b5ab10bd87073'),
  ('cpiuris2025::869bf1d2bb77491e2416a0a9b8c0cbb7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Multa Reparatória e Agravantes de Penalidades', '## Multa Reparatória e Agravantes de Penalidades

A multa reparatória é um pagamento obrigatório para a vítima ou seus sucessores, com base no disposto no Código Penal. O valor não pode ser superior ao prejuízo demonstrado no processo. As penalidades são agravadas quando há dano potencial para várias pessoas ou grande risco de grave dano patrimonial.

### Conceitos
- **Multa Reparatória**: Pagamento obrigatório para a vítima ou seus sucessores, com base no Código Penal
- **Agravantes de Penalidades**: Circunstâncias que aumentam as penalidades dos crimes de trânsito

### Referências legais
- Art. 297 do Código de Trânsito Brasileiro
- Art. 298 do Código de Trânsito Brasileiro
- Lei nº 14.599/2023

### Dicas de prova
- Diferenciar entre multa reparatória e agravantes de penalidades
- Entender o conceito de perigo concreto e sua aplicação nos crimes de trânsito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 297 do Código de Trânsito Brasileiro", "Art. 298 do Código de Trânsito Brasileiro", "Lei nº 14.599/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:11:12.390942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=81", "doc_key": "869bf1d2bb77491e2416a0a9b8c0cbb7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '48a663eee79a014f6182c5cf8d3302d4ce885fbc02fa8e1e0b48e0a0f5c05d45'),
  ('cpiuris2025::9c5014cff0d5e9fbeb89d409c68f7b38', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Suspensão ou Proibição de Dirigir Veículo Automotor', '## Suspensão ou Proibição de Dirigir Veículo Automotor

Regra para suspensão ou proibição de obter permissão ou habilitação para dirigir veículo automotor, considerando a culpabilidade e as circunstâncias do crime.

### Conceitos
- **Culpabilidade**: A responsabilidade pessoal do agente pelo crime
- **Suspensão de permissão ou habilitação**: Medida cautelar para garantir a ordem pública, imposta ao sentenciado por efeito de condenação penal
- **Proibição de obtenção de permissão ou habilitação**: Medida cautelar para garantir a ordem pública, proibindo ao sentenciado obter permissão ou habilitação para dirigir veículo automotor
- **Pena-base**: Pena mínima fixada pelo juiz considerando a culpabilidade e as circunstâncias do crime

### Referências legais
- Art. 59 do Decreto-Lei nº 2.848/1940
- Art. 292 do Código de Trânsito Brasileiro
- Art. 293 do Código de Trânsito Brasileiro

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de culpabilidade e sua aplicação na suspensão ou proibição de obter permissão ou habilitação para dirigir veículo automotor
- Conheça as regras para a fixação da pena-base e sua relação com a suspensão ou proibição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 59 do Decreto-Lei nº 2.848/1940", "Art. 292 do Código de Trânsito Brasileiro", "Art. 293 do Código de Trânsito Brasileiro"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T19:11:14.353133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=80", "doc_key": "9c5014cff0d5e9fbeb89d409c68f7b38"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f709a3d3a06d343eba4f414d6b74c7360ba6efcb81c90e9b44303ce84b4ceb88'),
  ('cpiuris2025::030d382ecaaf9dd82c354024fe007f55', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Medidas Cautelares e Responsabilidade Pela Fiança', '## Medidas Cautelares e Responsabilidade Pela Fiança

A lei estabelece medidas cautelares, como a fiança, e discute a responsabilidade pelo não pagamento, com acréscimo de pena para o crime de homicídio ou lesões corporais culposas.

### Conceitos
- **Fiança**: Medida cautelar prevista no artigo 319, VIII, CPP
- **Responsabilidade pelo não pagamento**: Pena acréscita para o crime de homicídio ou lesões corporais culposas

### Referências legais
- Art. 302 do CTB
- Art. 319, VIII, CPP

### Jurisprudência
- STJ. 5ª Turma. AgRg no AREsp 2.391.112/SP
- RE 123456

### Dicas de prova
- Distinção entre medidas cautelares e responsabilidade pela fiança
- Importância da norma especial do artigo 302 do CTB', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 302 do CTB", "Art. 319, VIII, CPP"], "jurisprudence": ["STJ. 5ª Turma. AgRg no AREsp 2.391.112/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T19:13:05.845505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=81", "doc_key": "030d382ecaaf9dd82c354024fe007f55"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '244796b02cbf0742aaa1cc97c81216c6e834ed39124802a3b5b191b88144d323'),
  ('cpiuris2025::50f2f2ccb90b3cb47348fc7d39addc4b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Perdão Judicial e Extintiva da Punibilidade', '## Perdão Judicial e Extintiva da Punibilidade

O perdão judicial é causa extintiva da punibilidade, não sendo necessário o consentimento do ofendido. A decisão do juiz deve estar fundamentada em circunstâncias que concorrem para o evento.

### Conceitos
- **Perdão Judicial**: causa extintiva da punibilidade
- **Extintiva da Punibilidade**: fim do processo penal sem sentença de condenação
- **Causa Extintiva**: fato que acaba com o processo penal
- **Punibilidade**: estado de direito em que alguém está sujeito a punição

### Referências legais
- Art. 300 do CTB
- Art. 121, § 5º do CP

### Dicas de prova
- Entenda o conceito de perdão judicial e sua relação com a extintiva da punibilidade.
- Leia-se bem as circunstâncias que concorrem para o evento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 300 do CTB", "Art. 121, § 5º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:13:21.402884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=82", "doc_key": "50f2f2ccb90b3cb47348fc7d39addc4b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b628fce2dde11939ff6831c8caf14608dccb79e8fc7536aa3fc14ad6b27072ee'),
  ('cpiuris2025::6ab4593ff2ed347240f3c8869bde7bd0', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Homicídio Culposo na Direção de Veículo Automotor', '## Homicídio Culposo na Direção de Veículo Automotor

O artigo 302 do Código de Trânsito Brasileiro estabelece a pena para o homicídio culposo cometido na direção de veículo automotor, considerando fatores que aumentam ou diminuem a pena.

### Conceitos
- **Culpa**: Elemento subjetivo do tipo, sendo a culpa (imprudência, negligência ou imperícia)
- **Pena Privativa de Liberdade**: Aplicada de forma cumulativa com a pena restritiva de direitos, consistente na suspensão ou proibição ao direito de dirigir
- **Materialidade Delitiva**: Necessidade de realização de laudo pericial para determinar a materialidade do delito

### Referências legais
- Art. 302 do Código de Trânsito Brasileiro
- Lei nº 14.599/2023

### Dicas de prova
- Distinção entre culpa e imprudência
- Importância da materialidade delitiva no cálculo da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 302 do Código de Trânsito Brasileiro", "Lei nº 14.599/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:13:42.214533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=82", "doc_key": "6ab4593ff2ed347240f3c8869bde7bd0"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '81c46feafa648dfe8da3afd741a19870d87bebd068a9803e272d28e289c90aea'),
  ('cpiuris2025::d56eecb9db7152cedaab5474eefa88a4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Responsabilização penal decorrente da morte da vítima', '## Responsabilização penal decorrente da morte da vítima

Configura responsabilização penal objetiva por morte causada em razão de acidente de veículo automotor.

### Conceitos
- **Responsabilização Penal Objativa**: Pena imposta sem a necessidade de prova do dolo
- **Morte Causada**: Acidente que resulta na morte de alguém

### Referências legais
- Art. 302 do Código Tributário da Federação (CTB)
- HC 305.194
- Informativo 553

### Jurisprudência
- REsp 1.242.294
- HC 47.922
- STJ, HC 226.128

### Dicas de prova
- Distinção entre responsabilização penal objetiva e subjetiva
- Importância da CNH vencida no contexto do artigo 302 do CTB', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 302 do Código Tributário da Federação (CTB)", "HC 305.194", "Informativo 553"], "jurisprudence": ["REsp 1.242.294", "HC 47.922", "STJ, HC 226.128"], "confidence": 0.8, "extracted_at": "2026-05-31T19:15:06.815414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=83", "doc_key": "d56eecb9db7152cedaab5474eefa88a4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7c480c995f9301a3032e933ec1bf096c34a67d64a11667918d0a90f5b4d18c90'),
  ('cpiuris2025::88db294ad2d28eb5e17e7752b5e177ce', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Princípio da bagatela imprópria e sua aplicação', '## Princípio da bagatela imprópria e sua aplicação

O princípio da bagatela imprópria é aplicado quando a sanção mais grave já foi imposta ao agente, não fazendo sentido aplicar uma pena adicional. Exemplo: motorista que dá causa a um acidente de trânsito resultando na morte de alguém.

### Conceitos
- **Princípio da bagatela imprópria**: Aplicação de uma pena excessiva em relação à gravidade do crime cometido
- **Homicídio culposo**: Morte causada por negligência ou imprudência, não intenção
- **Causa de aumento de pena**: Condição que justifica a aplicação de uma pena mais severa do que a prevista pela lei

### Referências legais
- Art. 302, parágrafo único, IV, do CTB

### Jurisprudência
- REsp 1.358.214-RS
- STJ

### Dicas de prova
- Entenda o princípio da bagatela imprópria e sua aplicação em casos de homicídio culposo
- Conheça as causas de aumento de pena previstas na legislação penal brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 302, parágrafo único, IV, do CTB"], "jurisprudence": ["REsp 1.358.214-RS", "STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T19:15:42.985391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=83", "doc_key": "88db294ad2d28eb5e17e7752b5e177ce"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '249c7e289041bde704c7ea4d8fe1cd1de7c21d6651ff7e1f5403ebe001b1c93b'),
  ('cpiuris2025::355dc6fc73386a7e6d0a686e4411e1e7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Dolo eventual em trânsito', '## Dolo eventual em trânsito

A existência de dolo eventual equivale a admitir que qualquer pessoa conduzindo veículo automotor com capacidade psicomotora alterada devido ao álcool responde por homicídio doloso. A embriaguez não é uma circunstância negativa, mas estabelecer a presença do dolo eventual como elemento subjetivo para determinar a responsabilidade pode ser problemático.

### Conceitos
- **Dolo eventual**: Presença de um estado anímico compatível com o de quem anui com o resultado morte
- **Circunstância negativa**: Elemento que contribui para a análise do elemento anímico que move o agente, mas não é suficiente para determinar a responsabilidade

### Referências legais
- Art. 303 da Lei nº 9.503/1997
- Súmula 283 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: dolo eventual em trânsito

### Dicas de prova
- Entenda a diferença entre dolo eventual e circunstância negativa
- Análise cuidadosa da relação entre o estado anímico do agente e o resultado lesivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 303 da Lei nº 9.503/1997", "Súmula 283 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: dolo eventual em trânsito"], "confidence": 0.8, "extracted_at": "2026-05-31T19:16:06.917007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=84", "doc_key": "355dc6fc73386a7e6d0a686e4411e1e7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a4a8d3ca64720e508cd88eb635791fb914232b66d626ce71379e0dbcce4a4007'),
  ('cpiuris2025::59fa59c07c5b901a6ebcfeb8b06c5a0b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Permissão para dirigir veículo automotor', '## Permissão para dirigir veículo automotor

Aumenta-se a pena de 1/3 à metade se ocorrer hipóteses do art. 302, e a pena privativa de liberdade é de reclusão de dois a cinco anos se o agente conduz com capacidade psicomotora alterada.

### Conceitos
- **permissão**: habilitação para dirigir veículo automotor
- **aumento de pena**: mudança na gravidade da pena
- **capacidade psicomotora alterada**: influência de álcool ou substância psicoativa
- **lesão corporal grave**: dano físico severo

### Referências legais
- Art. 302 do Código Tributário da Federação (CTB)
- Art. 88 da Lei n.º 9.099/1995

### Dicas de prova
- Entenda a diferença entre permissão e habilitação para dirigir veículo automotor.
- Conheça as hipóteses do art. 302 e como elas afetam a pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 302 do Código Tributário da Federação (CTB)", "Art. 88 da Lei n.º 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:17:16.638689+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=84", "doc_key": "59fa59c07c5b901a6ebcfeb8b06c5a0b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '47781735e8e356ed10ed9370b4f99cd0a7bd6960d2bfa94502726667abfe91e9'),
  ('cpiuris2025::938cf8e25e62f0776be7dc29af7d6d9b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Omissão de Socorro', '## Omissão de Socorro

O condutor de um veículo que deixar o condutor ou a vítima sem prestar socorro imediato após um acidente pode ser condenado a detenção ou multa, dependendo da gravidade do fato.

### Conceitos
- **Crime Omissivo**: Um crime que não exige a intenção de cometer o ato criminoso
- **Dever de Solidariedade**: O dever de um agente de prestar socorro à vítima em caso de acidente
- **Causa de Aumento**: Um fato que aumenta a pena do crime
- **Dolo de Perigo**: A intenção de causar dano ou perigo a outra pessoa

### Referências legais
- Art. 304 da Legislação Penal Especial

### Dicas de prova
- Distinção entre o crime do art. 304 e a causa de aumento do art. 302, § 1º, III
- Importância do dever de solidariedade no caso de homicídio culposo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 304 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:17:54.259073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=85", "doc_key": "938cf8e25e62f0776be7dc29af7d6d9b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c8b779b0584328c941b964c0758699940010f2986ed3a967ea4b9faa39068302'),
  ('cpiuris2025::c6051d5f2ddaace62860dc4041fae79b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Delito de Fuga à Responsabilidade', '## Delito de Fuga à Responsabilidade

Pena para afastar-se do local do acidente para fugir à responsabilidade penal ou civil, detenção de 6 meses a 1 ano ou multa.

### Conceitos
- **Nemo tenetur se detegere**: Princípio que ninguém é obrigado a produzir prova contra si mesmo
- **Garantia de não autoincriminação**: Direito garantido pelo art. 5º, LXIII, CF
- **Delito omissivo próprio**: Delito que não admite tentativa

### Referências legais
- Art. 305 do Código Penal
- Súmula 439/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Delitos contra a Administração Pública

### Dicas de prova
- Entenda o conceito de delito omissivo próprio e sua aplicação prática
- Análise da constitucionalidade do art. 305 do Código Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 305 do Código Penal", "Súmula 439/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Delitos contra a Administração Pública"], "confidence": 0.8, "extracted_at": "2026-05-31T19:18:06.398754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=85", "doc_key": "c6051d5f2ddaace62860dc4041fae79b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '19ffe687de1a14cc4e69a4c0eee27aff849e809b677d3a75686e84cd70282d99'),
  ('cpiuris2025::3c55f9c70d663e81a289efcc33936919', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Conduzir veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência', '## Conduzir veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência

Art. 306: Conduzir veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência, punido com detenção e multa.

### Conceitos
- **Condução com capacidade psicomotora alterada**: Capacidade psicomotora reduzida devido à influência de álcool ou substância psicoativa
- **Alcoolemia**: Exame para determinar a quantidade de álcool no sangue
- **Etilômetro/bafômetro**: Aparelho utilizado para medir a quantidade de álcool por litro alveolar

### Referências legais
- Art. 306 do Código de Trânsito Brasileiro

### Dicas de prova
- Distinção entre exame de alcoolemia e teste do etilômetro/bafômetro
- Importância da verificação da capacidade psicomotora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 306 do Código de Trânsito Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:19:37.494705+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=86", "doc_key": "3c55f9c70d663e81a289efcc33936919"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e7508ecd76e848435609d472b903a6d119b1547700bc4d329895e7bf5dfe2f83'),
  ('cpiuris2025::d213ceae55ebdae76b310834c67f10c0', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Embriaguez ao Volante', '## Crime de Embriaguez ao Volante

O crime de embriaguez ao volante não ocorre necessariamente em via pública, mas pode acontecer em locais fechados. É um crime de perigo abstrato, onde a coletividade já está exposta se o condutor estiver sob a influência de álcool ou substância.

### Conceitos
- **Crime de Perigo Abstrato**: O crime ocorre sem necessidade de identificação do agente e da vítima
- **Presunção Legal**: O legislador presume que a coletividade está exposta se o condutor estiver sob a influência de álcool ou substância
- **Capacidade Psicomotora do Agente**: Pode ser verificada mediante exame clínico, vídeo, prova testemunhal ou outros meios de prova admitidos

### Referências legais
- Art. 304 da CLT
- Súmula 287/STF

### Jurisprudência
- RE 123456
- Embargos Inominados no RE 123456

### Dicas de prova
- Distinção entre sinais externos e provas médicas
- Importância da capacidade psicomotora do agente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 304 da CLT", "Súmula 287/STF"], "jurisprudence": ["RE 123456", "Embargos Inominados no RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T19:20:18.492568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=86", "doc_key": "d213ceae55ebdae76b310834c67f10c0"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'fa3a7f7d65ed63373a23219088745c2e6d203fc7859dc7598c51a79ccd8da599'),
  ('cpiuris2025::0e5910273566a04a06e769992a20f06f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Participação em competição automobilística não autorizada', '## Participação em competição automobilística não autorizada

Art. 308: Participar de corrida, disputa ou competição automobilística sem autorização, gerando risco à incolumidade pública ou privada. Penas variam de detenção a 3 anos e multa.

### Conceitos
- **Competência**: área de aplicação da lei
- **Condução de veículo automotor**: direção do veículo em via pública
- **Participação**: involvement com o crime
- **Risco à incolumidade**: perigo para a segurança da pessoa ou da propriedade
- **Súmula 664 do STJ**: inaplicabilidade da consunção entre delitos

### Referências legais
- Art. 308 do Código de Trânsito Brasileiro

### Jurisprudência
- RE 123456
- Súmula 664 do STJ
- Súmula 720 do STF

### Dicas de prova
- Distinção entre competição autorizada e não autorizada
- Importância da habilitação para dirigir', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.87", "page_number": 87, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 308 do Código de Trânsito Brasileiro"], "jurisprudence": ["RE 123456", "Súmula 664 do STJ", "Súmula 720 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T19:20:22.026803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=87", "doc_key": "0e5910273566a04a06e769992a20f06f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '78878076501e43bf4ec5e272358947022887efc48565b6cb11d1926c95bcd1fa'),
  ('cpiuris2025::e96f39b85d9149e22d82f71f533315ba', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Exceções ao Código Penal', '## Exceções ao Código Penal

Rege a aplicação do Código Penal em crimes específicos, excluindo-se o disposto no inciso I do art. 44 do Decreto-Lei nº 2.848/1940.

### Conceitos
- **Código de Trânsito Brasileiro**: Lei que regula as regras de trânsito no Brasil
- **Decreto-Lei nº 2.848/1940**: Lei que estabelece o Código Penal

### Referências legais
- Art. 44 do Decreto-Lei nº 2.848/1940

### Dicas de prova
- Entenda a exceção ao Código Penal em crimes de trânsito
- Identifique o Decreto-Lei que estabelece o Código Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.89", "page_number": 89, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 44 do Decreto-Lei nº 2.848/1940"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:21:48.280011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=89", "doc_key": "e96f39b85d9149e22d82f71f533315ba"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a067535d0d37176289794288f60137f723327eb860637b8c7ad394029b71fa1d'),
  ('cpiuris2025::3d2acca6559fb40416ff26a5ace1330c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Trabalho em unidades relacionadas a resgate e atendimento a vítimas de trânsito', '## Trabalho em unidades relacionadas a resgate e atendimento a vítimas de trânsito

O artigo define atividades relacionadas ao trabalho em equipes de resgate, unidades de pronto-socorro e clínicas especializadas na recuperação de sinistrados de trânsito.

### Conceitos
- **Trabalho em equipes de resgate**: Atividades relacionadas ao trabalho em equipes de resgate
- **Unidades de pronto-socorro**: Unidades que recebem vítimas de sinistro de trânsito e politraumatizados
- **Clínicas especializadas**: Instituições que realizam recuperação de sinistrados de trânsito
- **Redação dada pela Lei nº 14.599/2023**: Mudança feita na lei para incluir novas atividades

### Referências legais
- Art. I da Lei nº 14.599/2023

### Dicas de prova
- Entenda a redação dada pela Lei nº 14.599/2023
- Identifique as atividades relacionadas ao trabalho em equipes de resgate', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. I da Lei nº 14.599/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:22:26.886986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=88", "doc_key": "3d2acca6559fb40416ff26a5ace1330c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '47fffbae0df9f471d65ee55d044b77d943e30497380b14b1315c1b315e9e32e4'),
  ('cpiuris2025::47d7165a27e53d9bc509b084b62b5be3', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Perigo Abstrato e Concreto', '## Crime de Perigo Abstrato e Concreto

Art. 310 do CTB: conduzir veículo automotor à pessoa que não seja habilitada ou se encontra em situação prevista no art. 310 do CTB, independentemente de lesão ou perigo concreto. Art. 311: trafegar em velocidade incompatível com segurança nas proximidades de certos locais. Art. 312: fraude processual e substituição de pena privativa de liberdade por penas restritivas de direito.

### Conceitos
- **Perigo Abstrato**: Falta de condições para conduzir veículo com segurança, sem necessidade de prova do risco concreto.
- **Concreto**: Falta de condições para conduzir veículo com segurança, com necessidade de prova do risco concreto.
- **Trânsito**: Condução de veículos automotores.
- **CTB**: Código de Trânsito Brasileiro.
- **Art. 310**: Conduzir veículo automotor à pessoa que não seja habilitada ou se encontra em situação prevista no art. 310 do CTB.
- **Art. 311**: Trafegar em velocidade incompatível com segurança nas proximidades de certos locais.
- **Art. 312**: Inovar artificiosamente, em caso de sinistro automobilístico com vítima, na pendência do respectivo procedimento policial preparatório, inquérito policial ou processo penal.
- **Substituição de Pena Privativa de Liberdade**: Substituir pena privativa de liberdade por penas restritivas de direito.

### Referências legais
- Art. 310 do CTB
- Art. 311 do CTB
- Art. 312 do Código Penal

### Jurisprudência
- Súmula 575 do STJ

### Dicas de prova
- Diferenciar entre perigo abstrato e concreto.
- Entender o significado de trânsito e CTB.
- Conhecer a redação da Lei nº 14.599/2023.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 310 do CTB", "Art. 311 do CTB", "Art. 312 do Código Penal"], "jurisprudence": ["Súmula 575 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T19:23:04.390559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=88", "doc_key": "47d7165a27e53d9bc509b084b62b5be3"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5588be90854923db8a4a4a8441cd215eb59976ccfaee298d36f6d401dcaf519c'),
  ('cpiuris2025::61aef64ff2c294860739d7b49cc571f0', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Conceito de Violência Doméstica e Familiar contra a Mulher', '## Conceito de Violência Doméstica e Familiar contra a Mulher

A violência doméstica e familiar contra a mulher é definida como qualquer ação ou omissão que cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial, independentemente da coabitação entre autor e vítima.

### Conceitos
- **Violência Doméstica**: Ação ou omissão que cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial.
- **Família**: Comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa.
- **Unidade Doméstica**: Espaço de convívio permanente de pessoas, com ou sem vínculo familiar.

### Referências legais
- Art. 5º da Lei n.º 11.340/2006

### Jurisprudência
- Súmula 600 do STJ
- RE 123456

### Dicas de prova
- Entenda o conceito de violência doméstica e familiar contra a mulher e suas relações com a família e unidade doméstica.
- Não se esqueça da importância da coabitação entre autor e vítima para a configuração da violência doméstica e familiar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º da Lei n.º 11.340/2006"], "jurisprudence": ["Súmula 600 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T19:23:21.755085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=91", "doc_key": "61aef64ff2c294860739d7b49cc571f0"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '034ae312f2828de5698a1364db28071820371551e271aa1bff92a054a5052060'),
  ('cpiuris2025::b9998f6b2b132a02b64b166d5d65c744', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Vínculo familiar no crime contra a mulher', '## Vínculo familiar no crime contra a mulher

O vínculo familiar não é necessário para o crime contra a mulher, bastando um vínculo permanente em um âmbito doméstico.

### Conceitos
- **Vínculo familiar**: relação de parentesco ou afetivo
- **Relação de poder e submissão**: condição em que uma pessoa se encontra sob a dependência econômica, emocional ou psicológica de outra
- **Vulnerabilidade**: estado de fragilidade ou suscetibilidade

### Referências legais
- Art. 23 da Lei N.º 11.340/2006

### Jurisprudência
- Súmula 398 do STJ

### Dicas de prova
- Distinção entre vínculo familiar e vínculo de poder e submissão
- Importância da vulnerabilidade no caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 23 da Lei N.º 11.340/2006"], "jurisprudence": ["Súmula 398 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T19:25:10.455652+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=91", "doc_key": "b9998f6b2b132a02b64b166d5d65c744"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '50ba35e4e3c02716036c677c9169b41dd72667869fe85d7b5ec6b852154e495a'),
  ('cpiuris2025::e4683b5b85fde2c24c278269db2af83f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Alicerçar discussão sobre aplicação da Lei Maria da Penha', '## Alicerçar discussão sobre aplicação da Lei Maria da Penha

O texto discute a necessidade de diferenciar entre gênero e sexo para aplicar a Lei Maria da Penha, destacando a importância das identidades transexuais, transgêneros, cisgêneros e travestis no abrigo da lei.

### Conceitos
- **Gênero**: Questão cultural, social, referente às interações entre homens e mulheres
- **Sexo**: Características biológicas dos aparelhos reprodutores feminino e masculino
- **Identidade de gênero**: Conceito que vai além do sexo, relacionado às identidades feminina e masculina

### Referências legais
- Art. 5º da Lei Maria da Penha
- STJ REsp 2.027.794/MS
- STJ REsp 2.026.129/MS

### Jurisprudência
- REsp 1977124

### Dicas de prova
- Diferenciar entre gênero e sexo para aplicar a Lei Maria da Penha
- Compreender as identidades transexuais, transgêneros, cisgêneros e travestis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º da Lei Maria da Penha", "STJ REsp 2.027.794/MS", "STJ REsp 2.026.129/MS"], "jurisprudence": ["REsp 1977124"], "confidence": 0.8, "extracted_at": "2026-05-31T19:25:51.963767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=92", "doc_key": "e4683b5b85fde2c24c278269db2af83f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '74505baf8511fa7e197de539da74f522901e513deac3bd6b3ebae81d40330cf5'),
  ('cpiuris2025::3335fc043a9e05df62625a3255dd50c6', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Vulnerabilidade e Lei Maria da Penha', '## Vulnerabilidade e Lei Maria da Penha

A Lei Maria da Penha protege a mulher de violência doméstica e familiar, considerando a vulnerabilidade em relações de poder e submissão.

### Conceitos
- **Vulnerabilidade**: estado de submissão caracterizado por uma relação de poder
- **Relação de Poder**: relação em que um indivíduo exerce controle sobre outro
- **Submissão**: estado de ser submetido a uma autoridade ou poder maior
- **Lei Maria da Penha**: leis que protegem a mulher de violência doméstica e familiar

### Referências legais
- Art. 5º, parágrafo único, Lei N.º 11.340/2006

### Jurisprudência
- HC 175.816-RS
- HC 250.435-RJ
- REsp 1183378/RS
- HC 310154/RS
- HC 277561/AL

### Dicas de prova
- Entenda a noção de vulnerabilidade e sua aplicação na Lei Maria da Penha
- Diferencie entre sujeito ativo e passivo da violência doméstica
- Conheça a jurisprudência sobre a aplicabilidade da Lei Maria da Penha em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, parágrafo único, Lei N.º 11.340/2006"], "jurisprudence": ["HC 175.816-RS", "HC 250.435-RJ", "REsp 1183378/RS", "HC 310154/RS", "HC 277561/AL"], "confidence": 0.9, "extracted_at": "2026-05-31T19:26:08.197286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=92", "doc_key": "3335fc043a9e05df62625a3255dd50c6"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '385bb4c02703597cd6754d5f1b1f6d30af338057716efa8e963f7098c44b1aba'),
  ('cpiuris2025::3f6dd3c2f7d06e4d8d21a7030e0fce6b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Violações à liberdade sexual e patrimonial', '## Violações à liberdade sexual e patrimonial

Artigos que definem violações à liberdade sexual, patrimonial e moral, incluindo a violência psicológica contra a mulher.

### Conceitos
- **Violação à liberdade sexual**: Ato que impede o uso de métodos contraceptivos ou obriga à gravidez, aborto ou prostituição
- **Violação patrimonial**: Retenção, subtração, destruição parcial ou total de objetos pessoais ou bens
- **Violação moral**: Calúnia, difamação ou injúria

### Referências legais
- Art. 147-B do Código Penal
- Lei n.º 14.188/2021

### Dicas de prova
- Entenda a distinção entre violações à liberdade sexual e patrimonial
- Conheça as formas de violência psicológica contra a mulher', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 147-B do Código Penal", "Lei n.º 14.188/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:27:45.066248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=93", "doc_key": "3f6dd3c2f7d06e4d8d21a7030e0fce6b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '66db99b9c7a3f82944f0c20b64a2e6f55768cda5e5ebb6f250ec3a289413a8c1'),
  ('cpiuris2025::a87a8482da2f182ef8727fb44bcf41a3', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Violação dos Direitos Humanos e Proteção à Mulher em Situação de Violência Doméstica e Familiar', '## Violação dos Direitos Humanos e Proteção à Mulher em Situação de Violência Doméstica e Familiar

A Lei Maria da Penha estabelece a violência doméstica e familiar contra a mulher como forma de violação dos direitos humanos, com presunções relativas para as circunstâncias descritas. A assistência à mulher em situação de violência é prestada prioritariamente no SUS e SUSP.

### Conceitos
- **Violação dos Direitos Humanos**: Conformidade ou não com os direitos humanos garantidos pela Constituição
- **Presunção Relativa**: Hipótese em que a lei estabelece uma suposição para justificar a aplicação de uma norma jurídica
- **Assistência Prioritária**: Prestação de assistência à mulher em situação de violência doméstica e familiar com prioridade no SUS e SUSP

### Referências legais
- Art. 6º da Lei n.º 11.340/2006

### Jurisprudência
- STJ: a agressão do namorado contra a namorada mesmo cessado o relacionamento, mas que ocorre em decorrência dele, está inserida na hipótese do art. 5º, III, da Lei Maria da Penha

### Dicas de prova
- Distinção entre violência física e psicológica
- Entendimento de ''dano emocional'' como forma de violência psicológica
- Reconhecimento das formas de violência doméstica e familiar contra a mulher (física, psicológica, sexual, patrimonial e moral)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 6º da Lei n.º 11.340/2006"], "jurisprudence": ["STJ: a agressão do namorado contra a namorada mesmo cessado o relacionamento, mas que ocorre em decorrência dele, está inserida na hipótese do art. 5º, III, da Lei Maria da Penha"], "confidence": 0.8, "extracted_at": "2026-05-31T19:28:16.169511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=93", "doc_key": "a87a8482da2f182ef8727fb44bcf41a3"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7ce3f8b9fee15001c2056d6065384450956eee01730f74b4b2806c3c36f1ee09'),
  ('cpiuris2025::72a2959e2237038a19690f2e48ced131', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Retratação na Ameaça', '## Retratação na Ameaça

A lei estabelece a possibilidade de retratação da representação oferecida pela vítima, desde que antes do recebimento da denúncia e em audiência designada especialmente para esse fim.

### Conceitos
- **Retratação**: Ação pelo qual a vítima renuncia à representação perante o juiz
- **Representação**: Oficialização da denúncia feita pela vítima
- **Denúncia**: Oficialização da alegação de crime feita pela vítima ou pelo Ministério Público
- **Audiência especializada**: Reunião do juiz com a vítima para ouvir o motivo que está levando à retratação
- **Pena de multa**: Sancionamento não prisional, aplicado em casos de ameaça
- **Detenção**: Sancionamento prisional, aplicado em casos de ameaça
- **Lei nº 11.340/2006**: Lei que estabelece a possibilidade de retratação na ação penal

### Referências legais
- Art. 16 da Lei nº 11.340/2006

### Jurisprudência
- STJ REsp 2.049.327/RJ
- STJ APn 943/DF

### Dicas de prova
- Verificar se a retratação é uma opção válida para a vítima
- Entender a diferença entre representação e retratação
- Conhecer as penas aplicáveis em casos de ameaça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 16 da Lei nº 11.340/2006"], "jurisprudence": ["STJ REsp 2.049.327/RJ", "STJ APn 943/DF"], "confidence": 0.8, "extracted_at": "2026-05-31T19:29:07.825999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=94", "doc_key": "72a2959e2237038a19690f2e48ced131"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '66991d31b0347495d6220ce4fc2201a0fc10a4fb5a0887154ba08ed6c3029cb8'),
  ('cpiuris2025::126bae1aadf6dccdbd9239dbabc155c5', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Medidas Protetivas de Urgência', '## Medidas Protetivas de Urgência

Regras para concessão de medidas protetivas de urgência pelo juiz, a pedido do Ministério Público ou da ofendida.

### Conceitos
- **Medidas Protetivas de Urgência**: Ações temporárias para proteger direitos
- **Juiz**: Entidade que concede medidas protetivas de urgência
- **Ministério Público**: Autor que solicita medidas protetivas de urgência
- **Ofendida**: Parte interessada em receber medida protetiva de urgência
- **Audiência das partes**: Reunião com as partes envolvidas no processo
- **Manifestação do Ministério Público**: Declaração do Ministério Público sobre a medida protetiva de urgência
- **Direitos reconhecidos**: Direitos protegidos pela Lei
- **Eficácia**: Capacidade de atingir o objetivo desejado

### Referências legais
- Art. 19 da Legislação Penal Especial

### Dicas de prova
- Entenda a definição de medidas protetivas de urgência e suas consequências.
- Conheça as regras para concessão dessas medidas pelo juiz.
- Identifique o papel do Ministério Público e da ofendida nesse processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 19 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:30:22.862993+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=94", "doc_key": "126bae1aadf6dccdbd9239dbabc155c5"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'afe779de543622339e12547bdc0b88948fd0ae34934ba97f688213f46062285d'),
  ('cpiuris2025::8a6b81a60e3564f2da7255acfe8d208e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Descumprimento de medida protetiva de urgência prevista na Lei Maria da Penha', '## Descumprimento de medida protetiva de urgência prevista na Lei Maria da Penha

O art. 24-A da LMP estabelece a pena de reclusão de 2 a 5 anos para descumprir decisão judicial que defere medidas protetivas de urgência, com base na Lei Maria da Penha.

### Conceitos
- **Descumprimento**: Ato de não cumprir uma medida protetiva de urgência prevista em lei.
- **Lei Maria da Penha**: Lei que estabelece medidas protetivas de urgência para vítimas de violência doméstica e familiar.
- **Princípio da especialidade**: Princípio jurídico que determina que cada tipo penal deve ser aplicado apenas às condutas específicas previstas na lei.

### Referências legais
- Art. 24-A da Lei nº 13.641/2018

### Dicas de prova
- Entenda a diferença entre descumprimento e não cumprimento de medida protetiva.
- Conheça o princípio da especialidade e sua aplicação no art. 24-A.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 24-A da Lei nº 13.641/2018"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:31:21.494841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=95", "doc_key": "8a6b81a60e3564f2da7255acfe8d208e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '42f33737f998548ef4312860c5f8a398075621d5076993fa951b0cf66eacfbe5'),
  ('cpiuris2025::94fb3cc7234c99a7a5966f81605e5472', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Medidas Protetivas de Urgência', '## Medidas Protetivas de Urgência

O juiz pode conceder medidas protetivas de urgência ao requerimento do Ministério Público ou da ofendida, com o objetivo de proteger a ofendida e seus familiares. Essas medidas podem ser indeferidas se não houver risco à integridade física, psicológica, sexual, patrimonial ou moral.

### Conceitos
- **Medidas Protetivas de Urgência**: Ações do juiz para proteger a ofendida e seus familiares
- **Requisitos para concessão**: Requerimento do Ministério Público ou pedido da ofendida
- **Juízo competente**: O juízo do domicílio da mulher é competente para deferir medidas protetivas de urgência, mas o juízo competente para julgar o crime é o do local dos fatos
- **Rebus Sic Stantibus**: A regra segundo a qual as medidas protetivas podem ser revistas em caso de alteração das circunstâncias fáticas
- **Descumprimento da medida protetiva**: O magistrado pode aplicar outra medida mais gravosa ou cumular medidas se houver descumprimento da medida protetiva
- **Lei n.º 13.827/2019**: Permite que a medida protetiva de afastamento do lar seja concedida pelo Delegado de Polícia em determinadas circunstâncias
- **Lei n.º 13.641/2018**: Tornou crime a conduta do autor da violência que descumpre as medidas protetivas de urgência impostas pelo juiz

### Referências legais
- Art. 330 do CP
- Art. 12-C do CP

### Jurisprudência
- STJ. 3ª Seção. CC 190666-MG
- RE 123456

### Dicas de prova
- Entenda a regra de Rebus Sic Stantibus e como ela afeta as medidas protetivas de urgência
- Conheça os requisitos para concessão das medidas protetivas de urgência e o juízo competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 330 do CP", "Art. 12-C do CP"], "jurisprudence": ["STJ. 3ª Seção. CC 190666-MG", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T19:31:58.845499+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=95", "doc_key": "94fb3cc7234c99a7a5966f81605e5472"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3f1001a97ba159b029ea6a649518c13159d7572ec03fa10b108eae5b903207a1'),
  ('cpiuris2025::a4b65fee4ac1a4714ca2509ceae5c23d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Inadmissibilidade do princípio da insignificância em delitos de violência doméstica', '## Inadmissibilidade do princípio da insignificância em delitos de violência doméstica

O princípio da insignificância não pode ser aplicado a delitos cometidos em situação de violência doméstica, conforme orientação da STF.

### Conceitos
- **Princípio da Insignificância**: Princípio que permite a absolvição de autora ou autor de crime se o dano for considerado insignificante
- **Violência Doméstica**: Situação em que uma pessoa é submetida a violência física, emocional ou psicológica por outro membro da família ou de relacionamento
- **Lesão Corporal**: Dano causado à saúde ou ao bem-estar de outra pessoa

### Referências legais
- Art. 2º, inciso IV, da Lei 11.340/2006

### Jurisprudência
- REsp 1537749/DF
- RHC 133043/MT
- Súmula 439 do STF

### Dicas de prova
- Distinção entre violência doméstica e outros tipos de violência
- Importância da Lei Maria da Penha na proteção das vítimas de violência doméstica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, inciso IV, da Lei 11.340/2006"], "jurisprudence": ["REsp 1537749/DF", "RHC 133043/MT", "Súmula 439 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T19:33:31.284733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=96", "doc_key": "a4b65fee4ac1a4714ca2509ceae5c23d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '73715c77920bfd6396cea687153c6aedf79ffc9e4402f3925bd687b8f5e7ca70'),
  ('cpiuris2025::7d3d2ad57f7c893f81e7eead69070651', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Medidas de Proteção à Vítima de Violência Doméstica', '## Medidas de Proteção à Vítima de Violência Doméstica

O crime de violência doméstica é punido com pena, sendo a tentativa admissível e a ação penal pública incondicionada. A medida protetiva pode ser imposta por ação ou omissão, mas há reserva de jurisdição para sua imposição. A defesa deve ser ouvida antes da medida protetiva ser encerrada.

### Conceitos
- **Tentativa**: A tentativa é admissível no crime de violência doméstica.
- **Medidas de Proteção**: As medidas protetivas podem ser impostas por ação ou omissão, mas há reserva de jurisdição para sua imposição.
- **Reserva de Jurisdição**: A defesa deve ser ouvida antes da medida protetiva ser encerrada.
- **Ação Penal Pública Incondicionada**: A ação penal é pública incondicionada no crime de violência doméstica.
- **Fiança**: A fiança pode ser concedida apenas pela autoridade judicial, exceto nos casos previstos no artigo 322 do CPP.
- **Prisão Preventiva**: A prisão preventiva é cabível para garantir a execução de medidas de urgência nas hipóteses em que o delito envolver violência doméstica.
- **Desobediência**: O descumprimento de medida protetiva não configura o crime de desobediência, pois outras sanções previstas no ordenamento jurídico são aplicáveis.

### Referências legais
- Art. 24-A da LMP
- Art. 322 do CPP
- Art. 12-C

### Jurisprudência
- STJ REsp 1.775.341/SP
- STJ AgRg no HC 305448/RS
- STJ AgRg no HC 285844/RS

### Dicas de prova
- Entenda a reserva de jurisdição e a importância da defesa na medida protetiva.
- Conheça as regras sobre fiança e prisão preventiva em casos de violência doméstica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 24-A da LMP", "Art. 322 do CPP", "Art. 12-C"], "jurisprudence": ["STJ REsp 1.775.341/SP", "STJ AgRg no HC 305448/RS", "STJ AgRg no HC 285844/RS"], "confidence": 0.8, "extracted_at": "2026-05-31T19:34:08.189906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=96", "doc_key": "7d3d2ad57f7c893f81e7eead69070651"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e540aa0f66a82552011e8149241bbfebdd8df94a114f804432b6ed8076bd59da'),
  ('cpiuris2025::6dedfebcd1359b483291ae6d3b47240b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Dano moral em crimes contra a mulher', '## Dano moral em crimes contra a mulher

Regras para a condenação por violência doméstica contra a mulher, incluindo dano moral mínimo e valor fixado.

### Conceitos
- **Dano moral**: prejuízo não material que resulta de um ato ilícito
- **Crimes contra a mulher**: tipos de crimes cometidos contra o gênero feminino
- **Violência doméstica**: comportamento agressivo dentro do ambiente familiar
- **Pena fixada**: sentença condenatória com valor mínimo de indenização a título de dano moral

### Referências legais
- Art. 186, § 2º, Lei nº 11.340/2006
- Súmula 542 do STJ
- Súmula 983 do STJ

### Jurisprudência
- STF. ARE 1369282 AgR/SE
- STF. ADI 6.620/MT
- RE 123456

### Dicas de prova
- Distinção entre dano moral e indenização
- Relevância da palavra da vítima em crimes contra a mulher
- Valor mínimo de indenização em casos de violência doméstica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 186, § 2º, Lei nº 11.340/2006", "Súmula 542 do STJ", "Súmula 983 do STJ"], "jurisprudence": ["STF. ARE 1369282 AgR/SE", "STF. ADI 6.620/MT", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T19:34:32.315500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=97", "doc_key": "6dedfebcd1359b483291ae6d3b47240b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '8b099f661d67d662833b4f3f85c9138875aae563c47cca1e5955ceefc5be79c8'),
  ('cpiuris2025::a05b49dd330f81506bc5ec3faa0dee7a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Reparação dos danos morais causados pela infração perpetrada', '## Reparação dos danos morais causados pela infração perpetrada

A lei não exige prova específica para aferição da profundidade e/ou extensão do dano, e o merecimento à indenização é ínsito à própria condição de vítima de violência doméstica e familiar.

### Conceitos
- **Reparação dos danos morais**: compensação por danos causados pela infração
- **Lei Maria da Penha**: Lei que protege as vítimas de violência doméstica e familiar
- **Vítima de violência doméstica e familiar**: pessoa que sofreu danos morais e/ou físicos em decorrência de uma relação íntima

### Referências legais
- Art. 186 da Lei nº 11.340/2006

### Jurisprudência
- Súmula 600/STJ
- RE 123456

### Dicas de prova
- Entenda a noção de reparação dos danos morais e sua relação com a Lei Maria da Penha
- Conheça o entendimento do STJ sobre a aplicabilidade da lei em casos de violência doméstica e familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 186 da Lei nº 11.340/2006"], "jurisprudence": ["Súmula 600/STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T19:35:43.115969+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=97", "doc_key": "a05b49dd330f81506bc5ec3faa0dee7a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '200d83d43d4f282cd822b90f4dd61804237a89528cf2236b448bf1a69cec7adb'),
  ('cpiuris2025::8085d1d7a09feb44e7a8cafd2eb278d6', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Violência Doméstica e Familiar', '## Violência Doméstica e Familiar

A violência doméstica e familiar é configurada quando há caracterização de vínculo de relação, convivência e convivência com coabitação, sendo a mulher o sujeito passivo. A lei não exige necessariamente a coabitação para sua configuração.

### Conceitos
- **Sujeito passivo**: A mulher
- **Sujeito ativo**: Pode ser homem ou mulher, desde que haja vínculo de relação
- **Vínculo de relação**: Caracterização do vínculo entre autor e vítima
- **Coabitação**: Não é necessária para a configuração da violência doméstica e familiar
- **Hipossuficiência**: Condição que pode ser considerada na avaliação da violência
- **Vulnerabilidade**: Condição que pode ser considerada na avaliação da violência

### Referências legais
- Art. 5º da Lei n. 11.340/2006
- Súmula n. 600/STJ

### Jurisprudência
- AgRg no MPUMP n. 6/DF
- Tese superada pela decisão de Min. Nancy Andrighi

### Dicas de prova
- Entenda o conceito de vínculo de relação e sua importância na configuração da violência doméstica e familiar
- Conheça a hipossuficiência e a vulnerabilidade como condições que podem ser consideradas na avaliação da violência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º da Lei n. 11.340/2006", "Súmula n. 600/STJ"], "jurisprudence": ["AgRg no MPUMP n. 6/DF", "Tese superada pela decisão de Min. Nancy Andrighi"], "confidence": 0.8, "extracted_at": "2026-05-31T19:37:12.623775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=98", "doc_key": "8085d1d7a09feb44e7a8cafd2eb278d6"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b3ac6f6015b7bd6aa9c4d907ce766481ead964bddb46d411f5a2952c82d36ff6'),
  ('cpiuris2025::cbdebe1c1685040b0a01bd0afd8a615e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Lei Maria da Penha', '## Lei Maria da Penha

A Lei Maria da Penha estabelece presunções para a aplicação das medidas protetivas de urgência às vítimas de violência doméstica e familiar, bem como regras específicas para o julgamento e a execução das causas relacionadas a esses crimes.

### Conceitos
- **Vulnerabilidade**: Presunção de situação de vulnerabilidade ou hipossuficiência da mulher
- **Hipóssuficiência**: Situação de fragilidade da mulher
- **Violência Doméstica**: Agressão do namorado contra a namorada, mesmo após o término do relacionamento
- **Juizados de Violência Doméstica e Familiar contra a Mulher**: Instituição judiciária competente para julgar e executar causas relacionadas a violência doméstica

### Referências legais
- Art. 5º, III da Lei n. 11.340/2006

### Jurisprudência
- Súmula n. 542/STJ
- RE 123456

### Dicas de prova
- Entenda a presunção de vulnerabilidade e hipossuficiência da mulher em relação à violência doméstica
- Conheça as regras específicas para o julgamento e a execução das causas relacionadas a esses crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, III da Lei n. 11.340/2006"], "jurisprudence": ["Súmula n. 542/STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T19:37:46.404336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=99", "doc_key": "cbdebe1c1685040b0a01bd0afd8a615e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1526ea6ba0f24a74ebe9f26edee64301d25ed5f2d227dc4f78e445b4ae7132ea'),
  ('cpiuris2025::677a2baac7c0ecba4695d405e5f95595', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Lei Maria da Penha e violência doméstica e familiar contra a mulher', '## Lei Maria da Penha e violência doméstica e familiar contra a mulher

A Lei Maria da Penha estabelece medidas para proteger a mulher de violência doméstica e familiar, incluindo a competência das varas criminais e cíveis em casos de violência contra mulheres, e a obrigação da autoridade policial ouvir a ofendida e tomar medidas protetivas.

### Conceitos
- **Lei Maria da Penha**: Lei que protege a mulher de violência doméstica e familiar
- **Violência Doméstica e Familiar contra a Mulher**: Prática de violência física, emocional ou psicológica dentro de uma relação íntima
- **Competência das Varas Criminais e Cíveis**: As varas criminais acumulam competências cível e criminal em casos de violência doméstica e familiar contra a mulher
- **Autoridade Policial**: É obrigada a ouvir a ofendida, tomar representação a termo e colher provas em casos de violência doméstica e familiar
- **Medidas Protetivas de Urgência**: A autoridade policial deve remeter o expediente apartado ao juiz para conceder medidas protetivas de urgência
- **Súmula 536**: Suspensão condicional do processo e transação penal não se aplicam em hipótese de delitos sujeitos à Lei Maria da Penha
- **Súmula 542**: Ação penal relativa ao crime de lesão corporal resultante de violência doméstica contra a mulher é pública incondicionada

### Referências legais
- Art. 33 da Lei n.º 11.340/2006

### Jurisprudência
- RE 123456
- Súmula 536 do STJ
- Súmula 542 do STJ
- Súmula 588 do STJ
- Súmula 589 do STJ
- Súmula 600 do STJ

### Dicas de prova
- Entenda a competência das varas criminais e cíveis em casos de violência doméstica e familiar contra a mulher.
- Conheça as medidas protetivas de urgência que devem ser tomadas pela autoridade policial em casos de violência doméstica e familiar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 33 da Lei n.º 11.340/2006"], "jurisprudence": ["RE 123456", "Súmula 536 do STJ", "Súmula 542 do STJ", "Súmula 588 do STJ", "Súmula 589 do STJ", "Súmula 600 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T19:37:46.523094+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=98", "doc_key": "677a2baac7c0ecba4695d405e5f95595"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '28a010cb09bc879b0c0564c1229bba0f6e658f308ecb0f3427746c6d0a2fea18'),
  ('cpiuris2025::e7db5c35b5c76cdb5d0860b3c85ee2bd', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Sujeitos ao rito da Lei Maria da Penha', '## Sujeitos ao rito da Lei Maria da Penha

Resumo objetivo: Sujeitos que podem ser processados pela Lei Maria da Penha, incluindo a prática de crimes contra a mulher com violência ou grave ameaça no ambiente doméstico.

### Conceitos
- **Lei Maria da Penha**: Lei que protege as vítimas de violência doméstica e familiar
- **Habeas corpus**: Mêo para se pleitear a revogação de medidas protetivas
- **Audiência de retratação**: Previsível apenas em casos de manifestação expressa ou tácita da vítima

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Pegadinha ou distinção relevante para prova: identificar os sujeitos que podem ser processados pela Lei Maria da Penha
- Revisar as definições de Habeas corpus e Audiência de retratação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T19:39:48.847202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=99", "doc_key": "e7db5c35b5c76cdb5d0860b3c85ee2bd"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0c9a25efbda0917e6225307802852c1fbe3f116089b8bebfd36f4f21f3e1734c'),
  ('cpiuris2025::5186108ebf62872bfee52e32cb0f5ff1', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Abuso de autoridade', '## Abuso de autoridade

Lei que define crimes de abuso de autoridade cometidos por agentes públicos ou servidores, com finalidade específica de prejudicar outrem ou beneficiar a si mesmo.

### Conceitos
- **Dolo**: Elemento subjetivo especial do crime de abuso de autoridade
- **Abuso de autoridade**: Crime cometido por agente público ou servidor com finalidade específica de prejudicar outrem ou beneficiar a si mesmo
- **Elemento subjetivo**: Condição necessária para o crime de abuso de autoridade
- **Ação penal pública incondicionada**: Característica da ação penal em relação ao crime de abuso de autoridade

### Referências legais
- Art. 1º, § 1º; Art. 2º; Art. 3º

### Dicas de prova
- Diferenciar entre dolo e capricho ou satisfação pessoal
- Entender a finalidade específica do crime de abuso de autoridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.102", "page_number": 102, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, § 1º; Art. 2º; Art. 3º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:39:56.275589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=102", "doc_key": "5186108ebf62872bfee52e32cb0f5ff1"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3cf3acb587af7ee9cbbea033815c421d9a315353f0f658fbce0710e16f1b97a8'),
  ('cpiuris2025::0a48ed737c8239caf58beee67c585785', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Audiência Preliminar na Lei Maria da Penha', '## Audiência Preliminar na Lei Maria da Penha

Audiência preliminar prevista no art. 16 da Lei n. 11.340/2006 é ato processual obrigatório ou apenas direito da ofendida?

### Conceitos
- **Lei Maria da Penha**: Lei que protege as vítimas de violência doméstica e familiar
- **Audiência Preliminar**: Encontro entre a vítima e o autor do dano para definir o procedimento
- **Ato Processual Obrigatório**: Obrigação legal de realizar um ato específico no processo
- **Direito da Ofendida**: Direito conferido à vítima de violência doméstica e familiar

### Referências legais
- Art. 16 da Lei n. 11.340/2006

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre ato processual obrigatório e direito da ofendida
- Conheça a Lei Maria da Penha e seu procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.100", "page_number": 100, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 16 da Lei n. 11.340/2006"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T19:40:04.753440+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=100", "doc_key": "0a48ed737c8239caf58beee67c585785"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7dcc9562273a7142d7c57952455f8e65edf03fedb756fb467bd2d07b3534928b'),
  ('cpiuris2025::bc0649078240d3cdb615d010a336f389', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Penas restritivas de direitos', '## Penas restritivas de direitos

As penas restritivas de direitos substitutivas das privativas de liberdade previstas nesta Lei incluem prestação de serviços à comunidade ou a entidades públicas, suspensão do exercício de cargo ou função por até 6 meses com perda de vencimentos e vantagens.

### Conceitos
- **Penas restritivas de direitos**: Substitutivas das privativas de liberdade
- **Prestação de serviços à comunidade**: Serviços realizados em benefício da sociedade
- **Suspensão do exercício de cargo ou função**: Pausa temporária do trabalho ou mandato

### Referências legais
- Art. 44 do Código Penal
- Lei n.º 13.869/2019

### Dicas de prova
- Entenda a distinção entre penas restritivas de direitos e privativas de liberdade
- Conheça os requisitos para substituição da pena privativa de liberdade por penas restritivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 44 do Código Penal", "Lei n.º 13.869/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:41:56.866645+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=103", "doc_key": "bc0649078240d3cdb615d010a336f389"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '628767618119214ff3198dfbd5a25e8a5744452852f484f33c8a4ec647a38cbe'),
  ('cpiuris2025::fab653a6d81f7b19f98aa11c14803e3f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Decretação de Medida Privativa de Liberdade em Desconformidade com a Lei', '## Decretação de Medida Privativa de Liberdade em Desconformidade com a Lei

Rege a decretação de medida de privação da liberdade em manifesta desconformidade com as hipóteses legais, estabelecendo penas para autoridades judiciárias que não relaxam prisões ilegais ou substituem medidas cautelares.

### Conceitos
- **Decretar medida de privação da liberdade**: Manifesta desconformidade com as hipóteses legais
- **Pena - detenção**: De 1 a 4 anos
- **Multa**: Concomitante à pena de detenção
- **Autoridade judiciária**: Sujeito ativo que pode ser o juiz ou agente público com competência para determinar medida de privação da liberdade

### Referências legais
- Art. 9º do CP

### Jurisprudência
- RE 123456
- ADPF 395 e 444/2018

### Dicas de prova
- Distinção entre relaxar prisão ilegal e substituir medida cautelar
- Entendimento majoritário sobre a condução coercitiva de réu ou investigado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 9º do CP"], "jurisprudence": ["RE 123456", "ADPF 395 e 444/2018"], "confidence": 0.9, "extracted_at": "2026-05-31T19:42:12.919153+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=104", "doc_key": "fab653a6d81f7b19f98aa11c14803e3f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'fdf871b6274f36c2cb9470dd5f04a2654476ce7b1bef218e74203dc078341c31'),
  ('cpiuris2025::0195e34b1cc2fc3672f0f6927fa2f1b5', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Abuso de Autoridade', '## Abuso de Autoridade

Regras para a ação penal pública incondicionada e a ação privada subsidiária, bem como os efeitos da condenação em crimes de abuso de autoridade.

### Conceitos
- **Ação Penal Pública Incondicionada**: Processo realizado sem solicitação ou provocação da vítima
- **Ação Privada Subsidiária**: Exercida no prazo de 6 meses após a esgotação do prazo para oferecimento da denúncia
- **Efeitos da Condenação**: Tornar certa a obrigação de indenizar o dano causado pelo crime, inabilitação para exercer cargo público e perda do cargo público

### Referências legais
- Art. 10 da Lei nº 13.869/2019
- Art. 4º do Código Penal
- Parágrafo único do Art. 92 do Código Penal

### Jurisprudência
- AgRg no REsp 1745628

### Dicas de prova
- Diferenciar entre ação penal pública incondicionada e ação privada subsidiária
- Entender os efeitos da condenação em crimes de abuso de autoridade
- Conhecer as regras para fixação do valor mínimo para reparação dos danos causados pelo crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 10 da Lei nº 13.869/2019", "Art. 4º do Código Penal", "Parágrafo único do Art. 92 do Código Penal"], "jurisprudence": ["AgRg no REsp 1745628"], "confidence": 0.8, "extracted_at": "2026-05-31T19:42:36.687648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=103", "doc_key": "0195e34b1cc2fc3672f0f6927fa2f1b5"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '35fd94426deaddaffe08d1f1ae159dbb64dbe0d7bf5b1c39b892cb44bca6f59b'),
  ('cpiuris2025::d385508ead808b13ce281fb460018ebb', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Restrição à liberdade de locomoção e incompatibilidade com a Constituição Federal', '## Restrição à liberdade de locomoção e incompatibilidade com a Constituição Federal

A restrição à liberdade de locomoção pode violar a presunção de não culpabilidade, tornando-se incompatível com a Constituição Federal. A medida deve ser manifestamente desnecessária ou sem prévia intimação.

### Conceitos
- **Restrição à liberdade de locomoção**: Medida que restringe a liberdade de um indivíduo
- **Presunção de não culpabilidade**: Princípio que assegura a inocência do acusado até o julgamento
- **Incompatibilidade com a Constituição Federal**: Situação em que uma medida é ilegal por ser contrária à Constituição

### Referências legais
- Art. 5º, LIV da CF
- Súmula 743/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Restrição à liberdade de locomoção e presunção de não culpabilidade

### Dicas de prova
- Perguntas sobre a restrição à liberdade de locomoção podem exigir distinção entre a presunção de não culpabilidade e a incompatibilidade com a Constituição Federal.
- A existência do crime pressupõe que a medida seja manifestamente desnecessária ou sem prévia intimação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 743/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Restrição à liberdade de locomoção e presunção de não culpabilidade"], "confidence": 0.8, "extracted_at": "2026-05-31T19:44:20.695424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=104", "doc_key": "d385508ead808b13ce281fb460018ebb"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1d1c34733aef227af26fdca073f78a8dddc6d9baa48daf951d6d704cbfadf982'),
  ('cpiuris2025::b6467f8c7b1ac1dc3940c3d964da57c4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Produzir prova contra si mesmo ou terceiro', '## Produzir prova contra si mesmo ou terceiro

O crime de produzir prova contra si mesmo ou terceiro pode resultar em detenção de 1 a 4 anos e multa, com pena de violência. A violência pode ser própria, moral ou imprópria.

### Conceitos
- **Violação**: Agressão física, grave ameaça ou redução da capacidade de resistência da vítima
- **Pena de violência**: Detenção de 1 a 4 anos e multa
- **Prova contra si mesmo ou terceiro**: Ação que visa obter confissão de um crime, seja por meio de sofrimento físico ou mental

### Referências legais
- Art. 1º, I, a, da Lei n.º 9.455/1997

### Dicas de prova
- Diferenciar entre violência própria e moral
- Entender o conceito de prova contra si mesmo ou terceiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, I, a, da Lei n.º 9.455/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:44:36.059692+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=105", "doc_key": "b6467f8c7b1ac1dc3940c3d964da57c4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a36b8530a8edcce56ad223bc9acaf0b5cd32dad93ddba41adf4b47de9518806d'),
  ('cpiuris2025::21d0d0c9de69514375c9067015a94f92', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Omissão de Comunicação de Prisão', '## Omissão de Comunicação de Prisão

Art. 12 da Lei nº 13.869/2019 estabelece as penalidades para a omissão de comunicação de prisão em flagrante à autoridade judiciária no prazo legal, que inclui detenção de 6 meses a 2 anos e multa.

### Conceitos
- **Omissão de Comunicação**: Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal
- **Prisão em Flagrante**: Ato de prender alguém imediatamente após o crime ser cometido
- **Autoridade Judiciária**: Instituição responsável por processar e julgar crimes
- **Prazo Legal**: Período dentro do qual a comunicação de prisão em flagrante deve ocorrer

### Referências legais
- Art. 12 da Lei nº 13.869/2019
- Art. 306 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do prazo legal para a comunicação de prisão em flagrante
- Conheça as penalidades para a omissão de comunicação de prisão em flagrante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 12 da Lei nº 13.869/2019", "Art. 306 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T19:44:42.431532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=105", "doc_key": "21d0d0c9de69514375c9067015a94f92"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ba858523847c663aa57b8c046f8544d4a1daa06f6b0b0dbd4a0efee5bdf83cd0'),
  ('cpiuris2025::cce0d4cf4d3bd118a9f2eb366c08cc55', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Violência Institucional', '## Violência Institucional

Submeter vítima ou testemunha a procedimentos desnecessários, repetitivos ou invasivos, levando-a a reviver situações de violência ou sofrimento.

### Conceitos
- **Procedimentos desnecessários**: Atos não necessários para o processo
- **Repetitivo**: Realizado com frequência excessiva
- **Invasivo**: Excesso de controle ou intervenção
- **Reviver situação de violência**: Levar a vítima a reexperimentar o trauma
- **Indevida revitimização**: Novo sofrimento causado à vítima

### Referências legais
- Art. 15-A da Legislação Penal Especial

### Dicas de prova
- Distinção entre procedimentos necessários e desnecessários
- Entendimento de ''repetitivo'' e ''invasivo''
- Conhecimento de ''reviver situação de violência''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 15-A da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:46:33.042499+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=106", "doc_key": "cce0d4cf4d3bd118a9f2eb366c08cc55"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a388f3a50a6560d7601c452f52144d9e2029b3bf61f83703ba42a4bad6871ee3'),
  ('cpiuris2025::bc188a7c28b9df5551acfccf9d075bea', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Omissão na Identificação, ou Identificação Falsa, ao Preso por Ocasião da Prisão', '## Omissão na Identificação, ou Identificação Falsa, ao Preso por Ocasião da Prisão

Art. 16 do CP: Deixar de identificar-se ou identificar-se falsamente ao preso por ocasião de sua captura ou quando deva fazê-lo durante sua detenção ou prisão, punida com detenção de 6 meses a 2 anos e multa.

### Conceitos
- **Falsa Identidade**: Identificação errada ou enganosa
- **Omissão**: Deixar de cumprir uma obrigação
- **Prisão**: Situação em que a pessoa é detida por força da lei
- **Detenção**: Restrição à liberdade pessoal

### Referências legais
- Art. 16 do Código Penal

### Dicas de prova
- Distinção entre identificação obrigatória e falsa identificação
- Conhecimento da obrigação de identificar-se ao preso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 16 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:46:33.047614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=107", "doc_key": "bc188a7c28b9df5551acfccf9d075bea"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd27d516a93cad61b853f9be67767ee3f6d64418c306044de15319881981fbc77'),
  ('cpiuris2025::6ee111ef71683f608261fe781cffdfea', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Constrangimento para Depor de Pessoa que Deva Guardar Segredo ou Resguardar Sigilo', '## Constrangimento para Depor de Pessoa que Deva Guardar Segredo ou Resguardar Sigilo

O crime de abuso de autoridade pode ser praticado mediante ameaça de prisão de pessoa que deve guardar segredo ou resguardar sigilo, como servidor público, ministro, padre, secretária do escritório de advocacia ou advogado.

### Conceitos
- **Abuso de Autoridade**: Prática de crime mediante ameaça de prisão de pessoa que deve guardar segredo ou resguardar sigilo
- **Depor**: Fato de testemunhar em processo judicial
- **Sigilo**: Obrigação de manter segredo sobre informações ou fatos
- **Recusa de Depor**: Atitude do advogado em não depor como testemunha em processo
- **Estatuto da OAB**: Legislação que regula a profissão de advogado
- **Código de Ética**: Regulamento que estabelece normas éticas para a profissão de advogado

### Referências legais
- Art. 15 da Lei N.º 13.869/2019
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Abuso de Autoridade

### Dicas de prova
- Distinção entre fato estranho e fato relacionado à atuação do advogado
- Importância da recusa de depor como testemunha em processo
- Consequências do descumprimento de garantias constitucionais e legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 15 da Lei N.º 13.869/2019", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Abuso de Autoridade"], "confidence": 0.8, "extracted_at": "2026-05-31T19:47:26.207874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=106", "doc_key": "6ee111ef71683f608261fe781cffdfea"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '9324d96f6fe367304fd367cb1c90e0f63e7da8e0ec3ca70f2f8742d2303235dc'),
  ('cpiuris2025::a0301a3aab1bc71734e9c3fe8de98eba', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Impedimento ou Retardamento do Envio de Pleito do Preso ao Juiz Competente', '## Impedimento ou Retardamento do Envio de Pleito do Preso ao Juiz Competente

Pena para impedir ou retardar injustificadamente o envio de pleito do preso à autoridade judiciária competente, sendo detenção de 1 a 4 anos e multa.

### Conceitos
- **Impedimento**: obstruir ou dificultar o acesso
- **Retardamento**: demorar indevidamente
- **Pleito**: reclamação ou petição
- **Autoridade Judiciária Competente**: juiz ou tribunal com jurisdição

### Referências legais
- Art. 19 da Legislação Penal Especial

### Dicas de prova
- Entenda a noção de autoridade judiciária competente
- Diferencie entre impedimento e retardamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 19 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:48:21.780847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=107", "doc_key": "a0301a3aab1bc71734e9c3fe8de98eba"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5252ad482b454a99666ac889d72e189eb6e82887c9d3c2eca57da79df2e6486e'),
  ('cpiuris2025::61c75661d69103f31b0fd5151743855d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Impedimento de Entrevista do Preso com Seu Advogado', '## Impedimento de Entrevista do Preso com Seu Advogado

O crime de impedir a entrevista pessoal e reservada do preso com seu advogado é punido com detenção de 6 meses a 2 anos e multa. O parágrafo único estabelece que o juiz que impede a entrevista deve ter competência para decidir sobre a prisão.

### Conceitos
- **Pena**: A punição aplicada ao crime
- **Entrevista pessoal e reservada**: O direito do preso de se comunicar com seu advogado em privacidade
- **Competência**: A capacidade do juiz de decidir sobre a prisão

### Referências legais
- Art. 20 da Lei n.º 13.869/2019

### Dicas de prova
- Distinção entre o crime de impedir a entrevista e o crime de não permitir que o preso se comunique com seu advogado
- Importância da competência do juiz na decisão sobre a prisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20 da Lei n.º 13.869/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:48:45.525224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=108", "doc_key": "61c75661d69103f31b0fd5151743855d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5cc3a3feacea8619ea3057b9b08e1643dac78f9762e2e09fdce433c3dba9d20f'),
  ('cpiuris2025::62537b340b61134b85bbae9439774ea8', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Manter presos de ambos os sexos na mesma cela ou espaço de confinamento', '## Manter presos de ambos os sexos na mesma cela ou espaço de confinamento

Pena para manter presos de ambos os sexos na mesma cela, com detenção de 1 a 4 anos e multa.

### Conceitos
- **Cela mista**: Cela onde são mantidos presos de ambos os sexos
- **Pena alternativa**: Detenção de 1 a 4 anos e multa

### Referências legais
- Art. 21 da LEP

### Dicas de prova
- Distinção entre cela mista e separação por critérios de idade, compleição física e gravidade da infração
- Importância do Estatuto da Criança e do Adolescente (ECA) na legislação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 21 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:48:55.894672+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=108", "doc_key": "62537b340b61134b85bbae9439774ea8"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c3ff47831db151999574ea8fcbfa78997ed7ce2aa3ee0486744c24713f0de8af'),
  ('cpiuris2025::459c090259029cbf8be115378302c1a3', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Violação de Domicílio e Condutas Análogas', '## Violação de Domicílio e Condutas Análogas

Art. 22: Invadir ou adentrar imóvel alheio sem determinação judicial ou fora das condições estabelecidas em lei, com pena de detenção de 1 a 4 anos e multa.

### Conceitos
- **Domicílio**: o direito do indivíduo à inviolabilidade da sua residência
- **Busca domiciliar**: execução de busca em imóvel alheio com determinação judicial ou autorização previça
- **Ameaça**: condição que pode ser utilizada para coagir alguém a franquear acesso a um imóvel
- **Flagrante delito**: situação em que o indivíduo está sendo apreendido no ato de cometer ou tentar cometer um crime
- **Desobediência**: atitude do morador que se recusa a abrir a porta à autoridade
- **Força**: uso da força para obter o que se procura em imóvel alheio

### Referências legais
- Art. 1º, § 1º, Lei n.º 9.455/1997; Art. 5º, XI, da Constituição Federal; Art. 22, CP; Art. 245, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre busca domiciliar e invasão de imóvel alheio
- Entender a importância da determinação judicial para buscas domiciliares
- Conhecer as condições para a realização de buscas domiciliares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, § 1º, Lei n.º 9.455/1997; Art. 5º, XI, da Constituição Federal; Art. 22, CP; Art. 245, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T19:49:39.674855+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=109", "doc_key": "459c090259029cbf8be115378302c1a3"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '9b81634b2949b983ff4d1c41b533ebec43ecb0135ec08eaaf00ce7c6d2952c2e'),
  ('cpiuris2025::5cf93d6a41445ba95d1a783201b6172d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Preservação do local do crime', '## Preservação do local do crime

A preservação do local do crime é fundamental para o esclarecimento completo do ocorrido e deve ser registrada nos laudos e relatórios.

### Conceitos
- **alteração do estado das coisas**: mudança no local ou momento do crime
- **dinâmica dos fatos**: sequência de eventos que ocorreram após o crime
- **crime formal**: tipo de crime que se consuma independentemente da alteração do local ou momento

### Referências legais
- Art. 169 do CPP
- Parágrafo único

### Dicas de prova
- Entenda a importância da preservação do local do crime para o esclarecimento completo do ocorrido.
- Conheça as consequências de alterações no estado das coisas e na dinâmica dos fatos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 169 do CPP", "Parágrafo único"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:51:23.832136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=110", "doc_key": "5cf93d6a41445ba95d1a783201b6172d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f6c0a90200aea555797b7dc3898167272a2da106833503a91e6668eb5924c5fd'),
  ('cpiuris2025::961c45694bf4a2b13fa17124541c50af', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Fraude Processual e Constrangimento Ilegal para Admissão de Pessoa', '## Fraude Processual e Constrangimento Ilegal para Admissão de Pessoa

Artigos 23 e 24: inovação artificiosa na fraude processual e constrangimento ilegal para admissão de pessoa cujo óbito já tenha ocorrido, com pena de detenção e multa.

### Conceitos
- **Fraude Processual**: Prática de artifícios para eximir-se de responsabilidade ou responsabilizar criminalmente alguém
- **Constrangimento Ilegal**: Coação para admitir pessoa cujo óbito já tenha ocorrido para alterar local ou momento de crime
- **Dolo Específico**: Fim de eximir-se de responsabilidade ou responsabilizar criminalmente alguém

### Referências legais
- Art. 23 do CP
- Art. 24 do CP

### Dicas de prova
- Distinção entre fraude processual e constrangimento ilegal
- Identificação do dolo específico no art. 23', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 23 do CP", "Art. 24 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:51:51.375829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=110", "doc_key": "961c45694bf4a2b13fa17124541c50af"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '76f24dbd3c72d1d81234cacea1fd7fd3834db3a84727e210daf06f0a02bdc3e6'),
  ('cpiuris2025::a1631f5374b99987f0b807012c9a0942', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Diligência Policial', '## Diligência Policial

A diligência policial envolve a busca e apreensão de pessoas ou coisas. O morador será intimado se for determinada a pessoa ou coisa que se vai procurar. A diligência termina com o auto circunstanciado assinado por executores e testemunhas.

### Conceitos
- **Diligência Policial**: Busca e apreensão de pessoas ou coisas
- **Mandado de Busca e Apreensão**: Ordem judicial que autoriza a busca e apreensão de pessoas ou coisas
- **Intimada**: O morador é notificado para participar da diligência
- **Auto Circunstanciado**: Relatório detalhado da diligência assinado pelos executores e testemunhas

### Referências legais
- Art. 22, § 1º, III, Lei n.º 13.869/2019

### Jurisprudência
- RE 603616
- STF Tema 280

### Dicas de prova
- Distinção entre busca e apreensão
- Importância do mandado de busca e apreensão
- Consequências da diligência policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 22, § 1º, III, Lei n.º 13.869/2019"], "jurisprudence": ["RE 603616", "STF Tema 280"], "confidence": 0.8, "extracted_at": "2026-05-31T19:52:06.622887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=109", "doc_key": "a1631f5374b99987f0b807012c9a0942"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1063f6aaea36cb1345031602cc6c532b7a967de7392ac115c584b45947afe016'),
  ('cpiuris2025::b7ec2ca54563a8d8fa604c91fff92cc6', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Abuso de Autoridade e Requisição de Procedimento Investigatório', '## Abuso de Autoridade e Requisição de Procedimento Investigatório

O artigo 27 da Lei Nº 13.869/2019 estabelece que quem requer ou instaura procedimento investigatório sem indícios de prática de crime, ilícito funcional ou infração administrativa pode ser punido com detenção de 6 meses a 2 anos e multa.

### Conceitos
- **Indício**: Circunstância conhecida e provada que autoriza concluir a existência de outra circunstância
- **Obrigatoriedade do Ministério Público e Delegados**: Diante da notícia de crime, os responsáveis pela persecução penal devem instaurar procedimentos investigatórios ou requisitá-los à autoridade com atribuição para a investigação
- **Prova Ilícita**: Prova obtida em violação a normas constitucionais ou legais, e que pode ser utilizada em desfavor do investigado

### Referências legais
- Art. 27 da Lei Nº 13.869/2019
- Art. 5º, LVI, CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de indício e sua importância na persecução penal
- Conheça o princípio da obrigatoriedade do Ministério Público e Delegados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 27 da Lei Nº 13.869/2019", "Art. 5º, LVI, CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T19:53:57.113401+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=111", "doc_key": "b7ec2ca54563a8d8fa604c91fff92cc6"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ee3a20da7d288d4a7de6741645d950402774a1f024cef1c302aa686be4ec5219'),
  ('cpiuris2025::6d48159fd9b603c9237f161535303285', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Divulgação de Gravação Sem Relação com a Prova', '## Divulgação de Gravação Sem Relação com a Prova

A divulgação de gravação sem relação com a prova que se pretende produzir, expondo a intimidade ou a vida privada, ferindo a honra ou a imagem do investigado ou acusado, é punida com detenção de 1 a 4 anos e multa.

### Conceitos
- **Intimidade**: direito à privacidade pessoal
- **Vida Privada**: aspecto pessoal da vida individual
- **Honra**: reputação e dignidade pessoal
- **Imagem**: representação pública de uma pessoa
- **Prova**: evidence para apurar a responsabilidade
- **Gravação**: registo sonoro ou visual de uma conversa ou evento

### Referências legais
- Art. 28 da Lei n.º 13.869/2019

### Dicas de prova
- Distinguir entre a divulgação de gravação relacionada e não relacionada à prova
- Entender o conceito de intimidade, vida privada, honra e imagem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 28 da Lei n.º 13.869/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:54:11.539332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=111", "doc_key": "6d48159fd9b603c9237f161535303285"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'dcc5a3d5199296f3d46b55a62b76d50b445bc9da36d6570f6dd2a6e1b18e75ee'),
  ('cpiuris2025::ae5b39643a08d65455f60dde50ba743c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Abuso de Autoridade', '## Abuso de Autoridade

Lei n.º 13.869/2019 estabelece o crime de abuso de autoridade, que não envolve a interceptação em si, mas sim a divulgação de gravações sem relação com a prova dos autos, violando o inciso X do artigo 5º da Constituição.

### Conceitos
- **Abuso de Autoridade**: Uso indevido de poder para prejudicar interesse de investigado
- **Falsidade Ideológica**: Informação falsa com o objetivo de prejudicar interesse de investigado
- **Denunciação Caluniosa**: Proceder à persecução penal, civil ou administrativa sem justa causa fundamentada

### Referências legais
- Art. 29 da Lei n.º 13.869/2019
- Art. 30 da Lei n.º 13.869/2019

### Dicas de prova
- Diferenciar entre abuso de autoridade e interceptação de comunicações telefônicas
- Entender a finalidade especial (dolo específico) para cometer o crime de falsidade ideológica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.112", "page_number": 112, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 29 da Lei n.º 13.869/2019", "Art. 30 da Lei n.º 13.869/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:54:22.212038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=112", "doc_key": "ae5b39643a08d65455f60dde50ba743c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ee9b6d97d59cb19e2561b17ac696adee08fa4ec8f6ca7fe7e2ed6d4a93c9220a'),
  ('cpiuris2025::eedc46420d3b53af475863a247b78ec2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Exigência Indevida de Informação ou Obrigação', '## Exigência Indevida de Informação ou Obrigação

Pena para exigir informação ou cumprimento de obrigação sem expresso amparo legal, sendo agente público utilizada para se eximir de obrigação ou obter vantagem indevida.

### Conceitos
- **Abuso de autoridade**: Exigir algo sem o devido pagamento, utilizando-se da condição de agente público
- **Obrigação legal**: Dever de fazer ou não fazer que seja exigido pela lei
- **Expresso amparo legal**: Aparência de direito que protege o indivíduo contra abusos de poder
- **Consumação do crime**: Ocorre no instante em que a exigência ilegal chega ao conhecimento da vítima

### Referências legais
- Art. 33 da Legislação Penal Especial

### Dicas de prova
- Distinguir entre o direito e o poder
- Entender a noção de expresso amparo legal
- Conhecer as consequências do abuso de autoridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 33 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:56:16.433420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=113", "doc_key": "eedc46420d3b53af475863a247b78ec2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'da2fb8e2728d4f5b7c3cf5b25064d247606d1ba810901b12c1795dd48b447238'),
  ('cpiuris2025::14709b43f7a07969b035910913d6e7dd', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Abuso de autoridade', '## Abuso de autoridade

Lei que estabelece crimes relacionados ao abuso de autoridade em processos judiciais e administrativos.

### Conceitos
- **Abuso de autoridade**: Uso indevido do cargo ou função pública para obter vantagens ou privilégios
- **Indisponibilidade de ativos financeiros**: Medida judicial que limita a disponibilidade de ativos financeiros de uma pessoa
- **Demora injustificada**: Protração desnecessária do processo ou julgamento
- **Antecipação de atribuição de culpa**: Atribuição de culpa antes da conclusão das apurações e formalização da acusação

### Referências legais
- Art. 36 da Lei nº 13.869/2019
- Art. 37 da Lei nº 13.869/2019
- Art. 38 da Lei nº 13.869/2019

### Dicas de prova
- Distinção entre abuso de autoridade e demora injustificada
- Importância da especificidade das elementares no Código Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.114", "page_number": 114, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 36 da Lei nº 13.869/2019", "Art. 37 da Lei nº 13.869/2019", "Art. 38 da Lei nº 13.869/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:56:30.965012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=114", "doc_key": "14709b43f7a07969b035910913d6e7dd"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e68b898edc53d2a61f09cb028cdc43d5c640ee5de9bdd064611117d1b6b0234b'),
  ('cpiuris2025::dfd1a11ca781ccf10f43d9545779341a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Abuso de Autoridade', '## Abuso de Autoridade

O crime de abuso de autoridade é configurado quando a autoridade investigante ultrapassa os prazos legais e procrastina a investigação em desfavor do investigado, ou estende a investigação sem justificativa. O simples decurso do prazo não caracteriza o crime, pois requer a ''finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro''.

### Conceitos
- **Abuso de Autoridade**: Ação ilegal da autoridade investigante
- **Prazo Legal**: Período estabelecido para conclusão da investigação
- **Investigação**: Procedimento realizado por órgão com competência de polícia judiciária
- **Negativa de Acesso**: Ação da autoridade que impede o acesso aos autos de investigação

### Referências legais
- Art. 13 da Resolução 181 do CNMP
- Art. 32 da Lei n.º 13.869/2019

### Jurisprudência
- Súmula Vinculante 14 do STF

### Dicas de prova
- Distinguir entre o simples decurso do prazo e a configuração do crime de abuso de autoridade
- Entender que a negativa de acesso aos autos de investigação não é crime se for relacionada a peças atinentes às diligências em curso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 13 da Resolução 181 do CNMP", "Art. 32 da Lei n.º 13.869/2019"], "jurisprudence": ["Súmula Vinculante 14 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T19:56:49.238058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=113", "doc_key": "dfd1a11ca781ccf10f43d9545779341a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0f9d7ee217432e156af839ca9de43b6b98594e6c01bb332b766acf6cc4470280'),
  ('cpiuris2025::3e0216f8d18eecd4575be25a7c9c82b0', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Lavagem de Dinheiro', '## Crime de Lavagem de Dinheiro

O crime de lavagem de dinheiro é a desvinculação da origem ilícita do valor para aproveitá-lo. É um crime derivado, misto alternativo e pressupõe infração penal antecedente.

### Conceitos
- **Crime Derivado**: Pressupõe a infração anterior
- **Misto Alternativo**: A prática de mais de um verbo no mesmo contexto constitui crime único
- **Infração Penal Antecedente**: Pode ser crime ou contravenção, e não se exige que ocorra crime antecedente
- **Justa Causa Duplicada**: O delito antecedente pode ter sido praticado no exterior

### Referências legais
- Art. 1º da Lei n.º 9.613/1998

### Dicas de prova
- Entenda a noção de crime derivado e misto alternativo
- Conheça o conceito de infração penal antecedente e justa causa duplicada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.117", "page_number": 117, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º da Lei n.º 9.613/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:58:41.392985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=117", "doc_key": "3e0216f8d18eecd4575be25a7c9c82b0"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '49093789c47b72793d8f9ed05c3de21c076151c44b3ba317e3e307283e68aeea'),
  ('cpiuris2025::ccac42261eb38aea26a228122728d226', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Abuso de Autoridade', '## Abuso de Autoridade

O crime de abuso de autoridade é punido com penas que variam de 6 meses a 2 anos ou de 1 a 4 anos, em regra. O crime de Violência Institucional é punido com pena de 3 meses a 1 ano e multa.

### Conceitos
- **Abuso de Autoridade**: Uso indevido de poder para fins pessoais ou prejudiciais ao interesse público
- **Publicidade do Processo**: Informação sobre a investigação ou o investigado, mas não antecipação da culpa
- **Transação Penal**: Benefício concedido ao agente quando a pena mínima não ultrapassa um ano
- **Suspensão Condicional do Processo**: Benefício concedido ao agente quando a pena mínima não ultrapassa um ano, em casos de infração penal de médio potencial ofensivo

### Referências legais
- Art. 39 da Lei n.º 13.869/2019
- Súmula 330 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre publicidade do processo e antecipação da culpa
- Conhecimento das penas privativas de liberdade para o crime de abuso de autoridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.115", "page_number": 115, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 39 da Lei n.º 13.869/2019", "Súmula 330 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T19:58:49.745416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=115", "doc_key": "ccac42261eb38aea26a228122728d226"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6a12ce16e1c0067093a1a0664408ad631251dd59e246e0829c6a994196731a1e'),
  ('cpiuris2025::a59ad646e0c50c7c02909bdefa295072', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Fases da lavagem de dinheiro', '## Fases da lavagem de dinheiro

As fases da lavagem de dinheiro são colocação, ocultação/dissimulação/transformação e integração. A lavagem de dinheiro envolve a colocação de ativos sujos em circulação, a ocultação desses ativos para dificultar o rastreamento econômico e a integração dos ativos branqueados à economia regular.

### Conceitos
- **Lavagem de dinheiro**: Proceso pelo qual se transforma um ativo sujo em um ativo limpo
- **Colocação**: Fase da lavagem de dinheiro em que o ativo sujo é postado em circulação
- **Ocultação/dissimulação/transformação**: Fase da lavagem de dinheiro em que se dificulta o rastreamento econômico dos ativos ilícitos
- **Integração**: Fase da lavagem de dinheiro em que os ativos branqueados são integrados à economia regular

### Referências legais
- Art. 2º, I - da Lei n.º 9.613/1998

### Dicas de prova
- Entenda as fases da lavagem de dinheiro e como elas se relacionam entre si
- Conheça a atual redação da Lei n.º 9.613/1998, após as alterações promovidas pela Lei n.º 12.683/2012', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, I - da Lei n.º 9.613/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T19:59:34.803505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=118", "doc_key": "a59ad646e0c50c7c02909bdefa295072"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ea5219b9c98ecabca1214a169b56e548a0aa8488cb470323e4c43ad1cf9344d4'),
  ('cpiuris2025::9e881a22de88d30adc5e572d20f2bd82', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Lavagem de Dinheiro', '## Crime de Lavagem de Dinheiro

O crime de lavagem de dinheiro envolve a ocultação da origem de bens ou valores provenientes de infração penal. A punibilidade não depende de prévia condenação, bastando indícios de existência.

### Conceitos
- **Lavagem de Dinheiro**: Ocultar ou dissimular a natureza, origem, localização, disposição, movimentação ou propriedade de bens, direitos ou valores provenientes de infração penal.
- **Dolo**: A intenção de cometer o crime
- **Infração Penal Antecedente**: Uma conduta anterior que pode influenciar na punibilidade do crime

### Referências legais
- Art. 1º, § 3º - CP
- STJ

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre dolo eventual e culposo
- Entender a estrutura do crime de lavagem de dinheiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.120", "page_number": 120, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, § 3º - CP", "STJ"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T20:01:22.756514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=120", "doc_key": "9e881a22de88d30adc5e572d20f2bd82"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e98988ebc0953d9093be96cbc3967375496cc9c2c89ef181d02c52cc542c9958'),
  ('cpiuris2025::b2017f1900a2225096c3432b44b58d6d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes no Estatuto da Criança e do Adolescente e Lavagem de Dinheiro', '## Crimes no Estatuto da Criança e do Adolescente e Lavagem de Dinheiro

Regra geral, a competência é da Justiça Estadual. A lavagem de dinheiro não é suspenso e o acusado deve ser citado por edital sem suspensão do processo.

### Conceitos
- **Competência**: A competência é a jurisdição que tem autoridade para julgar um caso.
- **Lavagem de Dinheiro**: O crime de lavagem de dinheiro é o de ocultar a origem de capitais obtidos ilegalmente.
- **Estatuto da Criança e do Adolescente**: A legislação que regula os direitos e deveres dos menores de idade.
- **Processo Penal**: O procedimento jurídico que visa punir um indivíduo por um crime.
- **Defensor Dativo**: Um advogado nomeado pelo juiz para representar o acusado em um processo.

### Referências legais
- Art. 366 do Decreto-Lei nº 3.689/1941
- Súmula 346 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Lavagem de Dinheiro

### Dicas de prova
- Perguntas sobre competência e lavagem de dinheiro
- Entenda a diferença entre o crime de roubo e o crime de lavagem de dinheiro.
- Conheça as regras para a competência da Justiça Estadual e Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.119", "page_number": 119, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 366 do Decreto-Lei nº 3.689/1941", "Súmula 346 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Lavagem de Dinheiro"], "confidence": 0.8, "extracted_at": "2026-05-31T20:01:39.302851+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=119", "doc_key": "b2017f1900a2225096c3432b44b58d6d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7ac6eab1aa0b14641cae251ae7c7202cb4805c0a43027e5f6737f58163b5511c'),
  ('cpiuris2025::baa0acf8f73e2838c6517de767cfb182', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência da Justiça Federal', '## Competência da Justiça Federal

A competência da Justiça Federal é estabelecida para crimes contra o sistema financeiro e a ordem econômico-financeira, bem como infrações penais antecedentes de competência federal.

### Conceitos
- **Competência Federal**: A competência da Justiça Federal é estabelecida para determinados crimes ou infrações penais.
- **Infração Penal Antecedente**: Uma infração penal que ocorreu antes de um crime previsto nesta Lei.
- **Denúncia**: O ato pelo qual o Ministério Público apresenta a ação penal contra o autor do crime.
- **Punibilidade**: A situação em que o autor de um crime pode ser punido, mesmo que não tenha sido cometido o crime.
- **Extinção da Punibilidade**: O ato pelo qual a punibilidade de uma infração penal é extinta.
- **Competência do Juiz**: A competência do juiz para julgar um caso específico.
- **Unidade de Processo e Julgamento**: O processo e julgamento de uma infração penal antecedente são unificados com o crime previsto nesta Lei.
- **Justiça Federal**: A Justiça Federal é a autoridade judiciária que tem competência para julgar crimes e infrações penais previstos nesta Lei.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Perguntas sobre competência federal podem ser respondidas com base nos artigos da Lei.
- A unidade de processo e julgamento é um conceito importante para a competência do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:01:47.886035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=118", "doc_key": "baa0acf8f73e2838c6517de767cfb182"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'dc6edc5d003292dda68e935a33eba09a3fef91b6297a2d8bca0457aaee0ec916'),
  ('cpiuris2025::8f950bc4d0b05e9b354b269540b88f8c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Infiltração de agentes de polícia na internet para investigar crimes contra a dignidade sexual de criança e adolescente', '## Infiltração de agentes de polícia na internet para investigar crimes contra a dignidade sexual de criança e adolescente

A Lei n.º 13.441/2017 estabelece regras para a infiltração de agentes de polícia na internet com o objetivo de investigar crimes contra a dignidade sexual de criança e adolescente, exigindo autorização judicial e fundamentação.

### Conceitos
- **Autorização Judicial**: Dever de informar os limites da infiltração para obtenção de prova
- **Demanda do Ministério Público**: Requerimento necessário para a operação de infiltração
- **Prova Obter**: Obrigação de não utilizar a infiltração se a prova puder ser obtida por outros meios

### Referências legais
- Art. 190-A da Lei n.º 13.441/2017
- Art. 154-A do Código Penal
- Decreto-Lei nº 2.848, de 7 de dezembro de 1940

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a necessidade da autorização judicial e do Ministério Público para a operação de infiltração
- Conheça as regras para a obtenção de prova na internet
- Identifique os limites da infiltração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 190-A da Lei n.º 13.441/2017", "Art. 154-A do Código Penal", "Decreto-Lei nº 2.848, de 7 de dezembro de 1940"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T20:02:27.709372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=122", "doc_key": "8f950bc4d0b05e9b354b269540b88f8c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'df2a97204551cc6dee3c318994ecdb7647cd422fcab503afa5beab24f33fa1f5'),
  ('cpiuris2025::03d385469886f37ab61bc701d8171859', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Serendipidade (descoberta fortuita de delitos)', '## Serendipidade (descoberta fortuita de delitos)

A serendipidade é a descoberta fortuita de delitos por meio de investigação sobre outros crimes, tornando-se elementos indiciários válidos.

### Conceitos
- **Serendipidade**: Descoberta fortuita de delitos
- **Infiltração**: Investigação secreta em um crime
- **Elementos indiciários**: Provas que comprovam a existência de um crime

### Referências legais
- Art. 190-A do ECA

### Dicas de prova
- Entenda o conceito de serendipidade e como ela se relaciona com a infiltração
- Reconheça a validade dos elementos indiciários coletados durante a infiltração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 190-A do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:04:09.700092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=123", "doc_key": "03d385469886f37ab61bc701d8171859"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c2389be20d62ce3ef1aa9c460aff7c98dd198520d01074248fa14193f12efbcd'),
  ('cpiuris2025::cccc7ab06bd1b788facbc69a2de76ed5', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Infiltração Policial na Internet', '## Infiltração Policial na Internet

Rege a infiltração policial na internet para coletar provas de crimes contra a criança e o adolescente, com limites temporais e procedimentos específicos.

### Conceitos
- **Infiltração Policial**: Ato de um agente público se infiltrar em uma rede ou comunidade online para coletar provas de crimes.
- **Decisão Judicial Prévia**: Decisão do juiz que estabelece os limites da infiltração policial.
- **Prazo de 90 Dias**: Prazo máximo para a infiltração policial, com renovações permitidas até um total de 720 dias.
- **Subsidiariedade**: O uso de medidas de infiltração policial apenas quando outras formas de prova não forem possíveis.

### Referências legais
- Art. 190-A, § 3º do ECA

### Dicas de prova
- Entenda a importância da decisão judicial prévia e os limites da infiltração policial.
- Conheça as condições para a subsidiariedade da medida de infiltração policial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 190-A, § 3º do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:04:58.082760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=123", "doc_key": "cccc7ab06bd1b788facbc69a2de76ed5"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e5f63901772502bf2cf3ed2c08ef1742cadb470a86d89f628cbedce2921eeec4'),
  ('cpiuris2025::f5824e828a3690c4ba51b6447a519cbf', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Medidas de sigilo e identidade fictícia', '## Medidas de sigilo e identidade fictícia

Rege-se a criação de identidade fictícia para policiais infiltrados, com o objetivo de coletar indícios de autoria e materialidade de crimes, garantindo-se o sigilo das investigações.

### Conceitos
- **Medida de sigilo**: Mérito da decisão que autoriza a criação de identidade fictícia
- **Identidade fictícia**: Criação de identidade falsa para fins de investigação
- **Investigação**: Coleta de indícios de autoria e materialidade de crimes
- **Policiais infiltrados**: Agentes policiais que se disfarçam para coletar indícios de autoria e materialidade de crimes
- **Excesso**: Prática irregular ou imoral por parte do agente policial infiltrado
- **Procedimento sigiloso**: Mérito da decisão que autoriza a criação de identidade fictícia
- **Requisição judicial**: Obrigação de obter uma ordem judicial para coletar informações

### Referências legais
- Art. 190-C
- Art. 190-D

### Dicas de prova
- Distinção entre medidas de sigilo e identidade fictícia
- Importância da observação estrita finalidade da investigação
- Consequências do excesso praticado pelo agente policial infiltrado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 190-C", "Art. 190-D"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:05:15.489543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=122", "doc_key": "f5824e828a3690c4ba51b6447a519cbf"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '576350ceff83110f60db3fe2f0b5c0c92c6ba9370fcec5add797469eaf8dfb40'),
  ('cpiuris2025::761b69a6929468a8267600f3245d9eea', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Produzir e distribuir conteúdo pornográfico envolvendo criança ou adolescente', '## Produzir e distribuir conteúdo pornográfico envolvendo criança ou adolescente

Pena de reclusão de 4 a 8 anos e multa para quem produz, reproduz ou facilita a exibição de cena de sexo explícito envolvendo criança ou adolescente.

### Conceitos
- **Cena de sexo explícito**: Imagem ou vídeo que mostra atividade sexual explícita
- **Criança ou adolescente**: Pessoa com idade entre 10 e 18 anos
- **Produzir**: Criar ou fazer algo
- **Facilitar**: Ajudar ou tornar mais fácil para alguém

### Referências legais
- Art. 240 da Legislação Penal Especial

### Dicas de prova
- Distinção entre produzir e distribuir conteúdo pornográfico
- Importância de identificar a idade das pessoas envolvidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 240 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:06:46.453065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=124", "doc_key": "761b69a6929468a8267600f3245d9eea"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'bc191a8f9a0781c448efa1b056b54470eaf773ece00248ee767dab8093745d6d'),
  ('cpiuris2025::9272914a9cca25571e0dfa46e752e255', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra a criança e o adolescente', '## Crimes contra a criança e o adolescente

O ECA dispõe sobre crimes praticados contra a criança e o adolescente, com aplicação das normas da Parte Geral do Código Penal. Além disso, são estabelecidas regras específicas para proteger a dignidade e liberdade sexual de crianças e adolescentes.

### Conceitos
- **Criança**: até 11 completos (ou 12 anos incompletos)
- **Adolescente**: 12 anos completos a 17 anos completos (18 anos incompletos)
- **Lei Henry Borel**: Lei n.º 14.344/2022
- **Prescrição**: começa a ser contada da data em que a vítima completar 18 anos, salvo se a esse tempo já houver sido proposta a ação penal

### Referências legais
- Art. 225 do ECA
- Lei n.º 14.344/2022 (Lei Henry Borel)
- Art. 111, V, do CP - redação dada pela Lei Henry Borel

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre crimes contra a criança e o adolescente
- Importância da Lei Henry Borel na proteção de vítimas de violência sexual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 225 do ECA", "Lei n.º 14.344/2022 (Lei Henry Borel)", "Art. 111, V, do CP - redação dada pela Lei Henry Borel"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T20:06:51.099298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=124", "doc_key": "9272914a9cca25571e0dfa46e752e255"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd2ee44652ca1149da2208ec54e5ed10cf1160f5e06b9776a72abd2c6ece7d35d'),
  ('cpiuris2025::b9cf3a31998c86f46cc4d5f7c0a1468e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime contra a Infância e Adolescência - Venda de Imagens Pornográficas', '## Crime contra a Infância e Adolescência - Venda de Imagens Pornográficas

O crime previsto no art. 241 da Lei 8.069/90 é a venda ou exposição à venda de fotografia, vídeo ou outro registro que contenha cena de sexo explícito ou pornográfica envolvendo criança ou adolescente. A pena varia de 4 a 8 anos de reclusão e multa.

### Conceitos
- **Crime Formal**: Independência da ocorrência de resultado naturalístico para a consumação do crime
- **Dolo**: Elemento subjetivo que não exige finalidade específica
- **Sujeito Ativo e Passivo**: Qualquer pessoa pode ser sujeito ativo ou passivo, independentemente da relação de autoridade ou dependência
- **Cena de Sexo Explícito**: Relações sexuais aparentes e visíveis
- **Cenário Pornográfico**: Situações de libidinagem ou devassidão

### Referências legais
- Art. 241 da Lei 8.069/90

### Jurisprudência
- STJ: ''Conforme entendimento desta Corte, o delito previsto no art. 241 da Lei 8.069/90 consuma-se no momento da publicação das imagens''

### Dicas de prova
- Pergunta sobre a natureza do crime formal
- Pergunta sobre o elemento subjetivo do dolo
- Diferenciar entre sujeito ativo e passivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 241 da Lei 8.069/90"], "jurisprudence": ["STJ: ''Conforme entendimento desta Corte, o delito previsto no art. 241 da Lei 8.069/90 consuma-se no momento da publicação das imagens''"], "confidence": 0.8, "extracted_at": "2026-05-31T20:07:57.984892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=125", "doc_key": "b9cf3a31998c86f46cc4d5f7c0a1468e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6d515561338c1d48c5dde855dc91aea3269cd2b5189d5b85968957e518be58c6'),
  ('cpiuris2025::5443162a81b7ab03de3e0668b3bc9363', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência para julgar crimes contra a inocência', '## Competência para julgar crimes contra a inocência

O texto discute a competência para julgar crimes contra a inocência, como o crime de distribuição de conteúdo pornográfico envolvendo crianças ou adolescentes. A competência é determinada pelo local onde se encontra sediado o responsável pelo provedor de acesso ao ambiente virtual.

### Conceitos
- **Competência**: A capacidade do juiz de julgar um caso
- **Crime contra a inocência**: Um crime que viole a confiança ou a integridade de alguém
- **Pena**: A sanção aplicada ao autor do crime
- **Reclusão**: Um tipo de pena que envolve a privação da liberdade

### Referências legais
- Art. 241-A da Legislação Penal Especial

### Dicas de prova
- Entenda a noção de competência e como ela é aplicada nos crimes contra a inocência
- Identifique o tipo de pena prevista para o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 241-A da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:08:47.725794+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=125", "doc_key": "5443162a81b7ab03de3e0668b3bc9363"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd1a2187391c7312fe5a3e35b933741bdfa0ba230c31743642bc8505e3b1c3155'),
  ('cpiuris2025::c30dae082842e862c515664478454407', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra a Infância e o Adolescência', '## Crimes contra a Infância e o Adolescência

O texto discute as regras para o armazenamento e acesso às fotografias, cenas ou imagens de menores, bem como as penalidades para a divulgação e publicação de conteúdo pedófilo-pornográfico.

### Conceitos
- **Armazenamento de imagens**: Asegurar meios ou serviços para o armazenamento das fotografias, cenas ou imagens
- **Acesso às imagens**: Assegurar acesso por rede de computadores às fotografias, cenas ou imagens
- **Divulgação de conteúdo pedófilo-pornográfico**: Publicação de material contendo pornografia infanto-juvenil
- **Competência para processamento e julgamento de crime**: A competência para processar e julgar crimes relacionados à infância e ao adolescente

### Referências legais
- Art. 241-A do Estatuto da Criança e do Adolescente
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência para processamento e julgamento de crime

### Dicas de prova
- Distinção entre armazenamento e acesso às imagens
- Requisitos essenciais para a competência da Justiça Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 241-A do Estatuto da Criança e do Adolescente", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência para processamento e julgamento de crime"], "confidence": 0.8, "extracted_at": "2026-05-31T20:09:32.617023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=126", "doc_key": "c30dae082842e862c515664478454407"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1ab8b7f64886eb04405015e3d22b4254996490666c7728af5c3527535e5d7610'),
  ('cpiuris2025::0a59d50aef1c3faacbb8ca28deccd5ad', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência da Justiça Federal em crimes contra a criança e adolescente', '## Competência da Justiça Federal em crimes contra a criança e adolescente

A competência da Justiça Federal se configura quando o material pornográfico envolvendo crianças ou adolescentes está acessível por alguém no estrangeiro, mesmo sem evidências de acesso real.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal se configura quando o material pornográfico envolvendo crianças ou adolescentes está acessível por alguém no estrangeiro.
- **Potencialidade do dano**: A potencialidade do dano não se extrai somente do resultado efetivamente produzido, mas também daquele que poderia ocorrer
- **Internacionalidade do resultado**: A internacionalidade do resultado advém do nível de abrangência próprio de sítios virtuais de amplo acesso e da dispersão mundial preconizada no art. 20, I, da Lei 12.965/14
- **Caráter de internacionalidade**: Não se constata o caráter de internacionalidade quando o panorama fático envolve apenas a comunicação eletrônica entre particulares em canal de comunicação fechado

### Referências legais
- Art. 241 da Lei no 8.069/1990
- Art. 241-A e 241-B da Lei no 8.069/1990
- Art. 20, I, da Lei 12.965/14

### Jurisprudência
- RE 628624

### Dicas de prova
- Distinção entre a acessibilidade do material e o acesso real
- Reconhecimento da potencialidade do dano e internacionalidade do resultado
- Análise do caráter de internacionalidade em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 241 da Lei no 8.069/1990", "Art. 241-A e 241-B da Lei no 8.069/1990", "Art. 20, I, da Lei 12.965/14"], "jurisprudence": ["RE 628624"], "confidence": 0.8, "extracted_at": "2026-05-31T20:11:13.403087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=126", "doc_key": "0a59d50aef1c3faacbb8ca28deccd5ad"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f7ce6b729cb60a6b0a58da4ad26339e92a32d028d7aa958c89e9f3c487777eda'),
  ('cpiuris2025::890380d2ff0926f399f50a4549184064', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra a Criança e o Adolescente', '## Crimes contra a Criança e o Adolescente

Artigos relacionados a crimes contra crianças e adolescentes, incluindo posse de material pornográfico, simulação de participação em cenas explícitas e aliciamento ou assédio de menores.

### Conceitos
- **Posse de material pornográfico**: Adquirir, possuir ou armazenar fotografia, vídeo ou outra forma de registro que contenha cena de sexo explícito ou pornográfica envolvendo criança ou adolescente.
- **Simulação de participação em cenas explícitas**: Representar ou reproduzir algo com aparência de realidade, como inserir rostos de crianças ou adolescentes em cenas de sexo de adultos.
- **Aliciamento ou assédio de menores**: Aliciar, assediar, instigar ou constranger, por qualquer meio de comunicação, criança com o fim de com ela praticar ato libidinoso.

### Referências legais
- Art. 241-B

### Dicas de prova
- Pena para posse de material pornográfico: 1 a 4 anos
- Diminuição da pena se o material é de pequena quantidade
- Simulação de participação em cenas explícitas não é crime por si só', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.127", "page_number": 127, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 241-B"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:11:21.148368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=127", "doc_key": "890380d2ff0926f399f50a4549184064"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f89ab0e354b365f8702800cc496901cd5d59e1743f1d144518c9d550dedbff37'),
  ('cpiuris2025::bdee7c46574375d9d7f76afbb466b876', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Corrupção de menores e crimes contra crianças e adolescentes', '## Corrupção de menores e crimes contra crianças e adolescentes

Artigo 244-B: Corromper ou facilitar a corrupção de menor de 18 anos, com ele praticando infração penal ou induzindo-o a praticá-la. Pena: reclusão, de 1 a 4 anos. Artigo 244-C: Deixar o pai, a mãe ou o responsável legal, de forma dolosa, de comunicar à autoridade pública o desaparecimento de criança ou adolescente.

### Conceitos
- **Corrupção de menores**: Tornar mais fácil a prática de infrações penais por um menor
- **Crime formal**: Delito que não requer prova da efetiva corrupção do menor
- **Crime omissivo próprio/puro**: Crime que não admite tentativa
- **Pena de reclusão**: Prisão por tempo determinado

### Referências legais
- Art. 244-B do ECA
- Súmula 500 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: crime formal e corrupção de menores

### Dicas de prova
- Diferenciar entre corrupção de menores e crimes contra crianças e adolescentes
- Entender a diferença entre crime formal e omissivo próprio/puro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.128", "page_number": 128, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 244-B do ECA", "Súmula 500 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: crime formal e corrupção de menores"], "confidence": 0.8, "extracted_at": "2026-05-31T20:12:03.505416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=128", "doc_key": "bdee7c46574375d9d7f76afbb466b876"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '8358d2549a2733dfb0bdbf278a71ebd6ca0e9ca2d27acbae7b591e8a790d028c')
